; ===== РАЗДЕЛЕНИЕ ПОДГОТОВКИ И ВЫВОДА СПРАЙТОВ (2026-07-30) =====
; ЗАЧЕМ. Замер: проход vec_nat_sprites = 40-50 тыс. тактов при кадре 59904, причём ВСЯ
; работа с фреймбуфером (restore/save/draw) была РАЗМАЗАНА по проходу и попадала на
; такты 25-45 тыс. — луч в это время уже в середине экрана. Отсюда мерцание: спрайт
; стирался в начале прохода, а рисовался, когда луч ушёл ниже (пропажа фигуры), а
; двухплоскостной герой (p1+p2 двумя отдельными проходами блиттера по 5-7 тыс. тактов)
; успевал показаться в ОДНОЙ плоскости — отсюда смена цвета кадр-в-кадр.
;
; КАК. Работа разрезана на две фазы, разнесённые ВО ВРЕМЕНИ КАДРА:
;   ФАЗА 1 ПОДГОТОВКА (vec_spr_prep) — идёт в игровом тике, фреймбуфер НЕ трогает
;     вообще. Считает геометрию (hi0/lo0/ncols/плоскости) в ЗАПИСЬ ВЫВОДА и собирает
;     СДВИНУТЫЙ спрайт в линейный буфер 48Б (3 столбца по 16 строк) внутри свободного
;     хвоста страницы слота. Сдвиг делается ОДИН раз на объект, а не по разу на
;     плоскость, как раньше (dual-герой сдвигался дважды).
;   ФАЗА 2 ВЫВОД (vec_spr_out) — вызывается ИЗ ISR В НАЧАЛЕ КАДРА, сразу после
;     VBlank-обязательных палитры и скана клавиатуры, то есть ДО того, как луч дойдёт
;     до игрового поля (при vec_vscroll=0x1F поле начинается с 32-й экранной строки =
;     ~13.8 тыс. тактов от прерывания). Порядок внутри пачки: restore всех (20->0), затем
;     вывод сверху вниз со скользящим фронтом сейвов (задача #5, см. vec_spr_out).
;     Вывод — простой OR буфера в fb (31 такт/байт против 108 у старого блиттера,
;     потому что ни сдвига, ни проверки правого края, ни разрывной адресации).
;
; ЦЕНА КАДРА ЗАДЕРЖКИ. Пачка выводит то, что подготовил ПРОШЛЫЙ тик. Логика игры не
; сдвинута ни на такт (координаты меняются в тот же кадр, что и раньше), сдвинута
; только картинка. Снапшот vec_nsp_prev тоже обновляет ПАЧКА (из записи вывода), а не
; подготовка: если пачка не успела выполниться (тик растянулся на кадр), объект
; остаётся «изменившимся» и будет подготовлен заново — вывод не теряется.
;
; ФОРМАТ СТРАНИЦЫ СЛОТА (256Б, 0xE000+idx*256):
;   +0x00..0x05  шапка save-under (valid, hi0, lo0, ncols, hi0b, hi0c)
;   +0x06..0x95  фон под спрайтом (до 3 плоскостей x 3 столбца x 16 строк = 144Б)
;   +0x96..0x9E  ЗАПИСЬ ВЫВОДА: pending(1=рисовать,2=скрыт), hi0, lo0, ncols, hi0b,
;                hi0c, Y, X, pat  (последние три -> vec_nsp_prev после вывода)
;   +0xA0..0xCF  СДВИНУТЫЙ СПРАЙТ: 3 столбца по 16Б, порядок НИЗ-ВВЕРХ (как данные слота)
; --------------------------------------------------------------------------------
;  vec_spr_prep: HL -> cur[Y,X,pat,col]; vnc_pbase/vnc_maskon уже выставлены вызывающим.
;  Геометрия столбцов — та же, что раньше считал vec_su_save (клип ncols по правому
;  краю экрана здесь ЕДИНСТВЕННОЕ место, где край проверяется: буфер линейный).
vec_spr_prep:
;  === ОТРИЦАТЕЛЬНЫЙ Y = НЕ «СКРЫТ», А «ЧАСТИЧНО ВЫШЕ ПОЛЯ» (жалоба с железа 2026-08-06) =====
;  ЖАЛОБА: «при прыжке в ВЕРХНЕЙ строке спрайт героя ПРОПАДАЕТ». Причина не в луче.
;  На верхней строке лабиринта герой стоит с Y=8..14, а прыжок поднимает его на 18 пикс:
;  игровая логика (порт 1:1 с Z80) уводит Y ЗА НОЛЬ, и он приходит байтом 0xFF..0xF6
;  (то есть -1..-10). Проверка «Y >= 0xD0 -> скрыт» считала это парковкой и НЕ ВЫВОДИЛА
;  героя вовсе: замер /tmp/topjump.js на верхней строке пирамиды 1 (X=112, Y=12) —
;  146 кадров из 300 (49%) с pending=2, ровно верхняя половина КАЖДОГО прыжка.
;  Прежний замер «скрытий 0» гонял прыжки на Y=72 — это ВТОРАЯ строка снизу от верха,
;  там Y за ноль не уходит, и дефект не воспроизводился.
;  ЧТО НА САМОМ ДЕЛЕ ЗНАЧАТ ЭТИ ЗНАЧЕНИЯ (TMS9918 и игра): Y=0xD0 (208) — терминатор
;  списка спрайтов, а ПАРКОВКА у игры — 0xE0/0xE1 (замер /tmp/ydist.js, 3182 кадра
;  геймплея: ворота/мумии/нож/карта/герой прячутся ИСКЛЮЧИТЕЛЬНО значениями 0xE0 и 0xE1,
;  других значений >=0xC0 нет). Значения 0xF0..0xFF — это -16..-1, спрайт частично выше
;  поля, и VDP рисует его ОБРЕЗАННЫМ сверху. Поэтому «скрыт» = 0xD0..0xEF, а 0xF0..0xFF
;  идут обычным путём: lo0 = 239-Y даёт 240..249, и петли вывода/сейва/стирания
;  доходят до конца столбца через `inc l` — байты продолжаются в строках выше поля
;  (там же, где верхняя половина строки SCORE), то есть ровно туда, куда просит геометрия.
;  ЦЕНА ТЕСТА: add a,0x30 сдвигает диапазон парковки в 0x00..0x1F, и одно `cp 0x20`
;  ловит его целиком (+2 байта против cp 0x0D0). А после этого равно Y+0x30, поэтому
;  lo0 = 239-Y считается как cpl + add 32 вместо cpl + sub 16 — те же 2 байта.
	ld	a, (hl)	; 0xD0..0xEF -> объект скрыт (парковка); 0xF0..0xFF -> Y отрицательный
	add	a, 0x30
	cp	0x20
	jp	c, vsp_hide
;  ПРАВИЛО MSX «Y+1» (ЗАДАЧА #20, 2026-07-31). Спрайт с Y-координатой Y выводится VDP'шкой
;  начиная с ЭКРАННОЙ строки Y+1, а не Y — это спецификация TMS9918, и вся геометрия игры
;  посчитана под неё. Тайл-путь у нас точен: строка знакоместа R занимает fb-смещения
;  255-8R..248-8R, т.е. fb = 255 - экранная_строка. Значит спрайту нужен НИЗ столбца
;  lo0 = 255-(Y+16) = 239-Y. Стояло 240-Y => ВСЕ спрайты игры ехали на пиксель ВВЕРХ.
;  ГДЕ ЭТО ВИДНО ГЛАЗОМ: карта долины. Силуэт подсветки (pat #E4) в оригинале ложится
;  РОВНО на краевые пиксели пирамидки — сверено с MSX-эмулятором на живой игре:
;  attrPiramidMap Y=79 X=138, знакоместа #C2/#C3 в строке 10 (экранные строки 80..87),
;  спрайт col c приходится на col c+2 глифа, и строка k спрайта = строка k глифа:
;    k=0 {5,6}->{7,8}=весь ряд глифа; k=1 {4,7}->{6,9}=края ряда {6..9}; k=2 {3,8}->{5,10};
;    k=3 {2,9}->{4,11}; k=4 {1,10}->{3,12}; k=5 {0,1,10,11}->{2,3,12,13}; k=6 {2,3,8,9}->
;    {4,5,10,11}; k=7 {4,5,6,7}->{6,7,8,9} — обводка ровно по силуэту.
;  Со сдвигом на строку вверх обводка садилась на СОСЕДНИЙ ряд глифа и вылезала за него
;  «крыльями» (замер fb: глиф пирамиды 1 занимал fb 191..184, спрайт — fb 192..185).
;  Правка операнда, ноль байт и ноль тактов; чинит заодно стрелку карты, героя, мумий.
	cpl	; lo0 = 239-Y (НИЗ столбца; формат слота низ-вверх).
	add	a, 32	; A здесь = Y+0x30 (см. тест выше): cpl даёт 207-Y, +32 = 239-Y
	ld	(vsu_lo), a
	inc	hl	; X
;  ЗАДАЧА #44 ШАГ 1: КОМПЕНСАЦИЯ ПРИЖАТОГО АРТА МУМИИ. Её силуэт сдвинут в клетке влево
;  на 3 (momia_push_left в tools/gfx/spr_unpack.py + smk_shift для зеркал), поэтому вывод
;  берёт X+3 — на экране фигура остаётся РОВНО на месте (coltab_frame_parity: 0 расхождений).
;  Одна константа на все шесть вариантов (3 кадра x 2 направления): будь она разной по
;  кадрам, X>>3 менялся бы при смене КАДРА анимации, а с ним hi0 — и объект вылетал бы со
;  слитого пути вывода (~3000 тактов на пачку), съедая весь выигрыш.
;  ПРИЗНАК — ПАТТЕРН, А НЕ НОМЕР СЛОТА. Слоты врагов 6-13 держат НЕ ТОЛЬКО мумий: в
;  пирамиде 1 там сидят твари с pat=0xE8, то есть из набора sprites2 (vec_spr_buf), а он
;  не сдвинут. Первая попытка метить «мумию» по индексу слота дала 48 байт расхождения
;  ровно на них. Проверяем ровно те 12 паттернов, которые ЧИТАЮТ таблицу vec_spr_momia:
;  прямые 0x28-0x33 и зеркальные 0x88-0x93.
	ld	b, (hl)	; B = X
	inc	hl
	ld	a, (hl)	; pat
	sub	0x28
	cp	12
	jp	c, vsp_xmum
	sub	0x60	; зеркальный диапазон 0x88-0x93
	cp	12
	ld	a, 0	; MVI флаги не трогает
	jp	nc, vsp_xadd
vsp_xmum:
	ld	a, 3
vsp_xadd:
	add	a, b
	ld	(vnsx_x), a
	ld	c, 3	; X&7==0 -> footprint 2 столбца, иначе 3
	and	7
	ld	(vsp_sh), a
	jp	nz, vsp_c3
	dec	c
vsp_c3:
	ld	a, (vnsx_x)	; B = col0 = X>>3
	rrca
	rrca
	rrca
	and	0x1F
	ld	b, a
	add	a, c	; col0+ncols<=32?
	cp	33
	jp	c, vsp_ncok
	ld	a, 32	; клип по правому краю экрана
	sub	b
	ld	c, a
vsp_ncok:
	ld	a, c
	ld	(vsu_nc), a
	ld	a, (vnc_pbase)	; hi0 = плоскость + col0
	add	a, b
	ld	(vsu_hi), a
;  hi0b: ВТОРАЯ СВОЯ плоскость. Её базу задаёт вызывающий (vnc_dupb), подготовка лишь
;  прибавляет столбец. Было зашито «pbase==0xA0 -> hi0b=hi0+0x20», то есть ровно одна
;  пара p1+p2 (idx6, одежда героя/заливка створки); мумиям нужна и пара p0+p2 (idx10),
;  см. таблицы vns_mumpb/vns_mumdb. Для прежних жителей значение то же, такты те же.
	ld	a, (vnc_dupb)
	or	a
	jp	z, vsp_hwb
	add	a, b	; B = col0 (жив с vsp_ncok)
vsp_hwb:
	ld	(vsu_hib), a
	ld	a, (vnc_maskon)	; hi0c: гасимая p0 у masked-спрайта (створка ворот)
	or	a
	jp	z, vsp_nomask
	cp	2
	jp	z, vsp_mask2
	ld	a, (vsu_hi)
	and	0x1F
	add	a, 0x80
	jp	vsp_hwc
;  РЕЖИМ 2 (спрайты карты долины, см. vns_pbher): гасим ОБЕ чужие плоскости. Основная
;  плоскость спрайта — p2 (hi0), гасимые — p0 (уходит в hi0b) и p1 (в hi0c). Признак
;  «hi0b не рисует, а ГАСИТ» — байт слота +0xD0, его ставит vsd_set (там же он и обнуляется
;  по умолчанию, поэтому ставить здесь бесполезно: vsd_* идёт ПОСЛЕ подготовки).
vsp_mask2:
	ld	a, (vsu_hi)
	and	0x1F
	add	a, 0x80	; p0 -> hi0b
	ld	(vsu_hib), a
	ld	a, (vsu_hi)
	and	0x1F
	add	a, 0x0A0	; p1 -> hi0c
	jp	vsp_hwc
vsp_nomask:
	xor	a
vsp_hwc:
	ld	(vsu_hic), a
	call	vsp_pat	; выбор паттерна + сборка сдвинутого спрайта в буфер
	call	vclp	; ЗАДАЧА#56: жёсткое отсечение габарита сверху (см. ниже)
;  СУЖЕНИЕ FOOTPRINT'А: 3-й столбец буфера часто ПУСТ (у спрайта уже нет битов, которые
;  сдвиг вынес бы так далеко). Тогда объекту хватает 2 столбцов — и вывод, и сохранение
;  фона, и стирание следующего кадра становятся на треть короче. Проверка 16 байт
;  развёрнута (192 такта в тике) и окупается 1.5-2 тыс. тактов ПОД ЛУЧОМ.
	ld	a, (vsu_nc)
	cp	3
	jp	nz, vsp_wr1
	ld	a, (vsp_pg)
	ld	h, a
	ld	l, 0x0C0
	xor	a
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	or	a
	jp	nz, vsp_wr1
	ld	a, 2
	ld	(vsu_nc), a
vsp_wr1:
	ld	a, 1	; pending=1: стереть старое, сохранить фон, вывести
	jp	vsp_wrec
vsp_hide:
;  ЗАДАЧА#46: тело скрытия переехало в ХВОСТ ЗА ВЫРАВНИВАНИЕМ (v06c/vec_outlist.asm) —
;  там же и весь разбор. Здесь остаётся один переход: перед `.align 256` свободно 7 байт,
;  и лишние байты ЗДЕСЬ растят образ сразу на 256 (см. шапку src/kvalley_8c.asm). Правка
;  даже освобождает 2 байта pre-align.
	jp	vsp_hidep	; pending=2: только стереть и инвалидировать слот
;  vsp_append: vec_nsp_idx -> vsp_list[vsp_n++]
vsp_append:
	ld	a, (vsp_n)
	add	a, vsp_list&255
	ld	l, a
	ld	h, 255&(vsp_list>>8)
	ld	a, (vec_nsp_idx)
	ld	(hl), a
	ld	a, (vsp_n)
	inc	a
	ld	(vsp_n), a
	ret
;  vsp_wrec: A = код pending -> ЗАПИСЬ ВЫВОДА (слот+0x96) + индекс в список вывода.
vsp_wrec:
	push	af
	call	vec_su_ptr	; H = страница слота
	ld	l, 0x96
	pop	af
	ld	(hl), a
	inc	l
	ld	a, (vsu_hi)
	ld	(hl), a
	inc	l
	ld	a, (vsu_lo)
	ld	(hl), a
	inc	l
	ld	a, (vsu_nc)
	ld	(hl), a
	inc	l
	ld	a, (vsu_hib)
	ld	(hl), a
	inc	l
	ld	a, (vsu_hic)
	ld	(hl), a
;  ЗАДАЧА#37: +0x9F = 2-я плоскость ДЛЯ ВЫВОДА. Отдельная копия нужна потому, что
;  +0x9A (та же плоскость ДЛЯ СОХРАНЕНИЯ ФОНА) дедуп может обнулить: фон под ней
;  снимает сосед. Рисовать её при этом обязательно — спрайты пары складываются OR-ом.
	ld	l, 0x9F
	ld	a, (vsu_hib)
	ld	(hl), a
;  ЗАДАЧА#53: +0xD2 = «мой буфер спрайта связан слиянием пары» (ставит vsd_dropb ниже —
;  и донору, и приёмнику). Полный путь подготовки перезаписывает буфер целиком, поэтому
;  признак снимается здесь; ставится он заново, если дедуп в этом тике сработает.
;  Читает признак ПОВТОРНЫЙ ВЫВОД (vns_draw в vec_sprites.asm): объекту, чей буфер
;  держит чужой вклад, переиспользовать буфер нельзя — сосед мог за это время уехать.
	ld	l, 0x0D2
	ld	(hl), 0
	ld	l, 0x9C	; +0x9C: Y,X,pat — их пачка положит в vec_nsp_prev
	ex	de, hl
	ld	hl, (vec_nsp_ptr)
	ld	a, (hl)
	ld	(de), a
	inc	hl
	inc	de
	ld	a, (hl)
	ld	(de), a
	inc	hl
	inc	de
	ld	a, (hl)
	ld	(de), a
	call	vsp_append	; индекс слота -> хвост списка вывода
;  ===== ДЕДУП ОБЩЕЙ ПЛОСКОСТИ (ЗАДАЧА#37, 2026-07-31) ================================
;  ЧТО ЗА ДУБЛЬ. Герой — ДВА спрайта в ОДНОЙ точке: слот 4 (одежда) пишет p2, слот 5
;  (кожа) пишет p1 И ДУБЛЬ в p2 (AURA, hi0b = hi0+0x20 = 0xC0+col0 = ровно hi0 слота 4).
;  Значит ОДИН И ТОТ ЖЕ кусок p2 сохранялся в фон ДВАЖДЫ и стирался ДВАЖДЫ. Замер:
;  двойное покрытие в 73.9% пачек, 50.6 байт на пачку, ~3.6 тыс. тактов КАЖДЫЙ кадр — и
;  всё это ПОД ЛУЧОМ, ровно перед выводом героя. Слоты 4 и 5 всегда в пачке вместе
;  (980 пачек: «только 4» = 0, «только 5» = 0).
;  ПОЧЕМУ РЕШЕНИЕ ПРИНИМАЕТСЯ ЗДЕСЬ. Предыдущая попытка искала пары СКАНОМ внутри пачки,
;  и бухгалтерия (~425 тактов на объект) съедала экономию. Здесь всё за O(1): подготовка
;  идёт по возрастанию индекса слота, поэтому «сосед по плоскости» — это ПРЕДЫДУЩИЙ
;  подготовленный объект (vsp_dpg), и хватает четырёх сравнений.
;  ПРАВИЛО (проверяется по факту, без привязки к номерам слотов): если у нас есть 2-я
;  плоскость hi0b, а у предыдущего подготовленного объекта ТА ЖЕ строка (lo0), ТОТ ЖЕ
;  hi0 (плоскость+столбец) и он не уже нас по столбцам — его сейв покрывает нашу 2-ю
;  плоскость целиком, и её можно не сохранять (+0x9A := 0). Если УЖЕ нас — наоборот,
;  снимаем сейв С НЕГО (pending=3: «выводить, фон не снимать, слот не держать»), потому
;  что покрывает уже наша 2-я плоскость. Так один из двух сейвов уходит ВСЕГДА.
;  ПОЧЕМУ ЭТО НЕ ДАЁТ ШЛЕЙФА. Выживший сейв покрывает ОБЪЕДИНЕНИЕ (мы всегда снимаем
;  более УЗКИЙ), значит стирание следующего кадра возвращает фон под всем, что было
;  нарисовано. А снимается фон по-прежнему ЧИСТЫЙ: lo0 у пары равны, порог фронта
;  сейвов lo0-16 строго ниже общего lo0 => оба объекта сохраняются ДО вывода любого
;  из них (инвариант фронта, см. шапку vec_spr_out).
;  ДЕДУП НЕ ДЛЯ РЕЖИМА 2. У спрайтов карты hi0b не РИСУЕТ, а ГАСИТ (см. vsp_mask2), и снять
;  с них сейв второй плоскости «потому что сосед покрывает» нельзя: восстанавливать фон
;  придётся именно нам. Уходим сразу в vsd_set.
	ld	a, (vnc_maskon)
	cp	2
	jp	z, vsd_set
;  ДЕДУП — ТОЛЬКО ДЛЯ ПАР (слоты 0-3 створки, 4-5 герой). ЗАДАЧА#51: у мумий появилась
;  вторая СВОЯ плоскость, и без этого гейта дедуп мог бы слить силуэт мумии в буфер
;  соседа (условие «его hi0 == наша hi0b» выполнимо для мумии idx6 рядом с кожей героя).
;  Мумия — не пара: её вторую плоскость никто не покрывает. До правки слоты 6+ сюда не
;  доходили сами (vsu_hib у них был нулём), так что поведение не меняется ни на такт.
	ld	a, (vec_nsp_idx)
	cp	6
	jp	nc, vsd_set
	call	vec_su_ptr
	ld	l, 0x96
	ld	a, (hl)
	dec	a	; pending!=1 (скрыт) -> цепочку рвём: сравнивать не с чем
	jp	nz, vsd_none
	ld	a, (vsu_hib)	; нет 2-й плоскости -> дедупить нечего, но цепочку продолжаем
	or	a
	jp	z, vsd_set
	ld	a, (vsp_dpg)	; предыдущего подготовленного в этом тике не было
	or	a
	jp	z, vsd_set
	ld	h, a	; HL = запись вывода предыдущего объекта
	ld	l, 0x98
	ld	a, (vsu_lo)
	cp	(hl)	; та же строка?
	jp	nz, vsd_set
	dec	l	; +0x97 hi0 предыдущего
	ld	a, (vsu_hib)
	cp	(hl)	; его плоскость+столбец == наша 2-я?
	jp	nz, vsd_set
	ld	l, 0x99
	ld	a, (vsu_nc)
	cp	(hl)	; наш ncols <= его -> его сейв покрывает нашу 2-ю плоскость
	jp	z, vsd_dropb
	jp	c, vsd_dropb
	ld	l, 0x9F	; наш шире: гасим сейв ПРЕДЫДУЩЕГО, но только если он однослойный
	ld	a, (hl)	; (у двух- и трёхплоскостного сейв снимает не только эту плоскость;
	;              берём НЕДЕДУПЛЕННУЮ копию hi0b, +0x9A мог быть обнулён этим же дедупом)
	or	a
	jp	nz, vsd_set
	ld	l, 0x9B
	ld	a, (hl)
	or	a
	jp	nz, vsd_set
	ld	l, 0x96
	ld	(hl), 3	; pending=3: выводить, фон не снимать, слот инвалидировать
	jp	vsd_set
;  СЛИЯНИЕ ПАРЫ В ОДИН БУФЕР (задача #37, шаг 3). Мало не сохранять общую плоскость —
;  надо ещё и не ВЫВОДИТЬ её вторым проходом: пока в одну и ту же плоскость пишут ДВА
;  объекта, слитая запись «фон OR спрайт» невозможна в принципе (второй подставит вместо
;  вклада первого свой фон — ровно на этом сняли vso_fast, см. ниже). Поэтому наш спрайт
;  OR-ится ПРЯМО В БУФЕР СОСЕДА, и общую плоскость выводит он один, уже двумя спрайтами
;  сразу. Картинка та же: OR ассоциативен. Работа тоже та же — vsb_or этой плоскости
;  больше не идёт, вместо него тот же объём OR-а, но в ОЗУ и в тике, а не под лучом.
;  Буфер соседа при этом портится безопасно: vsp_pat перезаписывает все 48 байт каждый
;  раз, когда объект готовится (обнулять заранее не нужно — каждый байт пишется ровно
;  один раз, см. vsp_row/vsp_zrow).
vsd_dropb:
	call	vec_su_ptr
	ld	l, 0x9A
	ld	(hl), 0	; нашу 2-ю плоскость в фон не снимаем (её снимает сосед)
	ld	l, 0x9F
	ld	(hl), 0	; и не выводим — сливаем спрайт в его буфер
;  ЗАДАЧА#53: пометить ОБОИХ — и нас (донор), и соседа (приёмник). Буфер приёмника с
;  этого момента держит чужой вклад, а наш собственный вывод p2 отдан ему: ни тому, ни
;  другому нельзя в следующем тике переиспользовать готовый буфер, если второй уехал.
;  ОСТОРОЖНО С H: ниже идёт слияние буферов, и H обязан остаться СВОЕЙ страницей.
;  Первая версия ставила пометку соседу через ld h,(vsp_dpg) и не возвращала H —
;  слияние шло из буфера соседа в него же. Поймал bonus_ending_gate: концовка
;  расходилась с эталоном на 82-108 пикселей во всех пяти фазах (у силуэта пропадал
;  бит p2, idx6 -> idx4), тогда как до правки было 2 пикселя в одной фазе.
	ld	l, 0x0D2
	ld	(hl), 1	; пометка СЕБЕ
	ld	d, h	; своя страница — на время пометки соседа
	ld	a, (vsp_dpg)
	ld	h, a
	ld	(hl), 1	; пометка СОСЕДУ (L по-прежнему 0xD2)
	ld	h, d	; вернуть свою страницу
	ld	a, (vsp_dpg)
	ld	d, a	; DE = буфер соседа, HL = наш буфер (обе страницы, шаг inc l/inc e)
	ld	e, 0x0A0
	ld	l, 0x0A0
	ld	b, 48
vsd_orl:
	ld	a, (de)
	or	(hl)
	ld	(de), a
	inc	l
	inc	e
	dec	b
	jp	nz, vsd_orl
;  ===== НЕПРОЗРАЧНЫЙ ГЕРОЙ (ЗАДАЧА#39, 2026-08-02) ==================================
;  ЧТО ЛЕЧИМ. Спрайты выводятся OR-ом, поэтому фон ПРОСВЕЧИВАЕТ сквозь фигуру: лестница
;  (p0+p1) под героем добавляет свои биты в его цвет. Палитро-корректный замер
;  (tools/verify/hero_opaque_probe.js, 1118 выводов пары, 83964 пикселя силуэта): видимая
;  примесь 1102 пикс, и в КАЖДОМ лишний бит стоит в p0 (индексы 14->6 и 14->2).
;  ПОЧЕМУ НЕЛЬЗЯ ПРОСТО ГАСИТЬ. (1) Гашение одной своей плоскости p1 убирает лишь 24%
;  примеси (1102 -> 838): главный виновник — ЧУЖАЯ плоскость p0. (2) Гасить p0 без
;  сохранения нельзя: герой уйдёт, а в лестнице останется дыра — вернуть её будет нечем.
;  (3) Гейт «под силуэтом есть чужие биты» нельзя читать из fb в подготовке: к этому
;  моменту пачка уже погасила p0 под текущей позицией, чтение протухшее, гейт начнёт
;  осциллировать => фигура замигает «непрозрачная/прозрачная».
;  КАК СДЕЛАНО. Детектор смотрит СОХРАНЁННЫЙ ФОН СЛОТА (он всегда чистый: снят до вывода
;  и восстанавливается стиранием) под маской силуэта. Сработал — включаем непрозрачный
;  вывод ШТАТНЫМИ средствами, без единого нового прохода по fb:
;    сосед (одежда, держит после дедупа ВЕСЬ силуэт) получает hi0c = p0 — обычная
;      «гасимая плоскость» masked-спрайта: save-under её СОХРАНЯЕТ, стирание ВОЗВРАЩАЕТ,
;      vec_spr_show гасит её силуэтом (vsb_andn). Дыры в лестнице не остаётся;
;    мы (кожа) гасим СВОЮ плоскость p1 силуэтом СОСЕДА перед своим OR — тогда под
;      одеждой не остаётся фоновых битов p1 (vop_i1/vop_pg, см. vec_spr_show).
;  ЦЕНА. hi0c != 0 => vsp_fastmark отвергает пачку, и в эти кадры пачка идёт СТАРЫМ путём.
;  Замер: детектор срабатывает в 5% выводов пары — остальные 95% не меняются ни на такт и
;  идут слитой записью, как раньше. Вид фигуры при этом одинаков на обоих путях: там, где
;  детектор молчит, гасить под силуэтом нечего, и OR даёт ровно тот же цвет.
;  ДЕТЕКТОР СМОТРИТ НА НОВЫЙ ГАБАРИТ, А НЕ НА СТАРЫЙ (ЗАДАЧА#40, 2026-08-03). Первая
;  версия гейта ОРила сохранённый фон слота — а он снят под ПРОШЛОЙ позицией. Отсюда
;  жалоба с железа: «когда герой спускается сверху — в самом начале проскакивает зелёный,
;  либо в самом конце лестницы, когда поднимается». Ровно тот же класс, что протухший
;  save-under у створок ворот: решение принимается по данным позапрошлого кадра.
;  ЗАМЕР (детерминированный спуск/подъём по найденной в комнате лестнице, шаг 1/2/3 пикселя
;  за тик — tools/verify: см. scratchpad/descend_probe.js): «непрозрачность нужна, а режим
;  выключен» 2/8/20 выводов, примеси 6/145/239 пикс, и ПЕРВЫЙ КАДР ПЕРЕСЕЧЕНИЯ всегда среди
;  них. Чем быстрее движение, тем больше промахов — подпись лага один-в-один.
;  ГДЕ ВЗЯТЬ ЧИСТЫЙ ФОН ПОД НОВЫМ ГАБАРИТОМ. Плоскость p0 герой не пишет НИКОГДА, кроме
;  собственного гашения, поэтому:
;    (1) читаем p0 прямо из fb под НОВЫМ габаритом — там чистый фон, если прошлая пачка
;        не гасила (а это 95% кадров);
;    (2) если гасила (hi0c в ШАПКЕ соседа), то погашенный участок — это старый габарит, и
;        чистый фон оттуда лежит в слоте вторым блоком плоскостей. Объединение (1)+(2)
;        накрывает и старый, и новый габарит: новые строки берутся из fb, погашенные — из
;        сейва. Пропустить пересечение больше нечем.
;  Маской силуэта по-прежнему не режем: габарит шире фигуры, и это даёт естественное
;  ОПЕРЕЖЕНИЕ на кадр (лишнее срабатывание безвредно — гасить нечего, картинка та же),
;  а OR идёт 12 тактов на байт против 33 у маскированного скана.
	xor	a
	ld	(vop_i1), a	; по умолчанию — прозрачный вывод, как было
	call	vec_su_ptr	; геометрия у пары одна на двоих, берём свою
	ld	l, 0x99
	ld	c, (hl)	; C = ncols (счётчик столбцов)
	ld	a, c
	or	a
	jp	z, vsd_set
	ld	l, 0x98
	ld	e, (hl)	; E = lo0 (низ столбца, 16 байт подряд внутри страницы)
	ld	l, 0x97
	ld	a, (hl)
	and	0x1F
	add	a, 0x80	; D = страница fb плоскости p0, первый столбец
	ld	d, a
	xor	a
	call	vop_box	; --- (1) fb под НОВЫМ габаритом ---
	or	a
	jp	nz, vop_on
	ld	a, (vsp_dpg)	; --- (2) погашенный прошлой пачкой кусок: он в сейве соседа ---
	ld	h, a
	ld	l, 5
	ld	a, (hl)	; hi0c ШАПКИ: гасили ли p0 в прошлой пачке?
	or	a
	jp	z, vsd_set
	ld	l, 0
	ld	a, (hl)	; шапка валидна?
	dec	a
	jp	nz, vsd_set
	ld	l, 3
	ld	a, (hl)	; ncols сейва: им ограничен валидный фон в слоте
	or	a
	jp	z, vsd_set
	add	a, a
	add	a, a
	ld	b, a	; B = 4*ncols витков по 4 байта
	add	a, a
	add	a, a
	add	a, 6	; второй блок плоскостей = сохранённая p0 (hi0b у одежды нет)
	ld	l, a
	xor	a
	call	vop_or4
	or	a
	jp	z, vsd_set	; чужого фона нет ни там, ни там -> просвечивать нечему
vop_on:
;  === ПОД СТВОРКОЙ ВОРОТ ГАСИТЬ НЕЧЕГО (жалоба с железа 2026-08-04: «мерцание красным
;  === через правую зелёную створку, когда герой за неё уходит») ======================
;  ЧТО ПРОИСХОДИЛО. Створка непрозрачна и выводится ПОСЛЕДНЕЙ (ключ сортировки 0), как
;  плоскости 0-3 на MSX, поэтому герой под ней не виден ни одной своей плоскостью: p1 и p2
;  у створки и так подняты, OR героя в них ничего не меняет. НО детектор выше видит под
;  героем «чужой фон» (это лица кирпичей створки, p0=1) и включает ГАШЕНИЕ p0 силуэтом.
;  Гашение исполняется в пачке РАНЬШЕ створки, а её деталь (та самая p0) — позже, и в это
;  окно успевает луч: лица кирпичей на мгновение теряют p0 и показываются idx6 КРАСНЫМ
;  вместо idx14 зелёного. Замер (tools/verify/door_leaf_purity.js, сцена «герой под
;  створкой»): 895 пиксель-кадров на 8 кадрах из 21.
;  ПОЧЕМУ ЭТО НЕ ЛОВИЛОСЬ РАНЬШЕ: старая метрика искала «чужие» индексы idx2/idx4, а кожа
;  героя — idx6, ТОТ ЖЕ индекс, что у швов кирпича. И в кадровом снимке дефекта нет вовсе:
;  к концу кадра створка уже починена, это чисто ЛУЧЕВОЙ транзиент.
;  ЛЕЧЕНИЕ: если габарит объекта пересекается с живой створкой, гашение не включаем —
;  оно всё равно бессмысленно (створка накроет объект целиком), а вреда от него ровно
;  столько, сколько описано выше.
	call	vom_hidden
	or	a
	jp	nz, vsd_set
	ld	a, (vec_nsp_idx)
	inc	a
	ld	(vop_i1), a	; нам — гасить свою плоскость силуэтом соседа
	ld	a, (vsp_dpg)
	ld	(vop_pg), a
	ld	h, a	; соседу — гасимая p0 (штатный masked-механизм; его
	ld	l, 0x97	; собственная подготовка пишет 0x9B заново каждый тик,
	ld	a, (hl)	; поэтому сбрасывать этот байт нам не нужно)
	and	0x1F
	add	a, 0x80
	ld	l, 0x9B
	ld	(hl), a
;  Слияние основной плоскости пары (после дедупа p2): кожа отдаёт p1 в +0x9A одежды
;  и pending=3. Restore один — у одежды уже есть hi0c, слитая запись и так закрыта.
	ld	a, (vsp_dpg)
	cp	0x0E4
	jp	nz, vsd_set
	ld	h, a
	ld	l, 0x9A
	ld	a, (vsu_hi)
	ld	(hl), a
	inc	h
	ld	l, 0x96
	ld	(hl), 3
vsd_set:
	call	vec_su_ptr
	ld	l, 0x0D0
	ld	(hl), 0	; ЗАДАЧА#41: признак «hi0b ГАСИТ» снят по умолчанию
	ld	a, (vnc_maskon)	; режим 2 (спрайты карты долины): hi0b тоже ГАСИТ — подсветке
	cp	2	; надо погасить ОБЕ чужие плоскости, чтобы сесть в один слот idx2
	jp	nz, vsd_nm2
	ld	(hl), a	; !=0 — признак стоит (значение неважно, читается как флаг)
vsd_nm2:
;  ЗАДАЧА#52: ЗАЛИВКА створки (maskon==1 ставится только ей) помечается страницей слота
;  ДЕТАЛИ — пары идут подряд (attribDoor: 0/1 и 2/3, заливка первой). Байт +0xD3: +0xD0
;  занят под «hi0b гасит», +0xD1 под ZFLAG слота.
	ld	l, 0x0D3
	ld	(hl), 0
	ld	a, (vnc_maskon)
	dec	a
	jp	nz, vsd_nlf
	ld	a, (vec_nsp_idx)
	inc	a
	add	a, 0x0E0
	ld	(hl), a
;  [2026-08-18] P2-БЛОК ФОНА ЗАЛИВКЕ НЕ НУЖЕН — И ОПАСЕН. Пара рисуется в пачке
;  ПЕРВОЙ, и save створки в кадре, где одежда героя стоит в её габарите (вход в
;  пирамиду: герой идёт из-за двери), клал ОДЕЖДУ в p2-блок «фоном»; при скрытии
;  створок (finEntraSale) restore выплёвывал её на раму — КРАСНЫЕ ТОЧКИ справа
;  ворот на всю фазу c0 (жалоба с железа). Легального p2-фона в дверном проёме
;  нет (рама p0/p1, за створкой чернота), а p2 в fb заливка гасит сама (vsc_leaf
;  по +0x9F — копия для ВЫВОДА, её мы не трогаем). Обнуляем hi0b-ДЛЯ-СЕЙВА:
;  save не снимает p2-блок, шапка получает hi0b=0, restore/fixup согласованы.
	ld	l, 0x9A
	ld	(hl), 0
vsd_nlf:
;  НЕПРОЗРАЧНЫ: мумии 6..13 (enemyAttrib) И НОЖ 15..18 (knifeAttrib). Оба одноплоскостные
;  (p2), оба берут маску из своего же буфера — механизм тот же, гейт общий.
;  НОЖ ДОБАВЛЕН 2026-08-04 (жалоба с железа «нож при падении пересекается с лестницей
;  зелёным»): OR одной плоскостью поверх лестницы p0+p1 давал p0+p1+p2 = idx14. Замер
;  до правки — tools/verify/knife_purity.js: 375 из 9700 пикс силуэта (3.87%) не своего
;  цвета, из них 212 — зелень на лестнице. Цена гейта 7 байт.
	ld	a, (vec_nsp_idx)
	sub	6
	cp	8
	jp	c, vsd_opa	; 6..13 = мумия
	sub	9	; 15..18 = нож -> 0..3
	cp	4
	jp	nc, vsd_dpg
vsd_opa:
	call	vom_check
vsd_dpg:
	call	vec_su_ptr
	ld	a, h
	ld	(vsp_dpg), a
	ret
;  ===== НЕПРОЗРАЧНАЯ МУМИЯ (ЗАДАЧА#41, 2026-08-03, ОБРАТИМЫЙ ЭКСПЕРИМЕНТ) ============
;  ЗАЧЕМ. У мумии тот же дефект, что был у героя: фон просвечивает сквозь фигуру. Замер
;  (палитро-корректный, 2034 вывода, 131657 пикселей силуэта): примесь видна в 442 выводах
;  (21.7%), 4770 пикселей = 3.6% площади, в среднем 11 пикселей на поражённый вывод.
;  ЧЕМ МУМИЯ ОТЛИЧАЕТСЯ ОТ ГЕРОЯ. Герой — ПАРА объектов: сосед держит весь силуэт и отдаёт
;  его как маску, а гасить надо ОДНУ чужую плоскость (p0) — под неё есть штатное поле hi0c.
;  Мумия ОДНОПЛОСКОСТНАЯ (замер: у всех 2034 выводов ровно одна плоскость; p2 у серых, p0 у
;  золотых): маска берётся из её собственного буфера, но гасить надо ДВЕ чужие плоскости.
;  Поле гашения одно, зато dual (hi0b) мумии не нужен — и save-under, и стирание, и fixup
;  ходят по цепочке hi0 -> hi0b -> hi0c и умеют ТРИ блока (0x06..0x95 = 3 x 16 x ncols, при
;  ncols=3 ровно 144 Б). Поэтому hi0b переназначается ВТОРЫМ ГАСЯЩИМ, а чтобы вывод знал,
;  что его надо гасить, а не рисовать, в свободном хвосте страницы слота стоит признак
;  слот+0xD0 (0 = рисовать OR, 1 = гасить ANDN; см. vec_spr_show).
;  ДЕТЕКТОР — ТОТ ЖЕ, ЧТО У ГЕРОЯ ПОСЛЕ ЗАДАЧИ#40: смотрим фон под НОВЫМ габаритом, иначе
;  на кадре входа в лестницу гашение опаздывает. Источники те же: (1) обе чужие плоскости
;  прямо из fb — там чисто, если прошлая пачка не гасила; (2) если гасила (hi0b в ШАПКЕ),
;  погашенное лежит в слоте вторым и третьим блоками плоскостей.
;  ЦЕНА: срабатывание уводит пачку на старый путь (vsp_fastmark отвергает объект с hi0b/
;  hi0c), а сейв и стирание мумии втрое длиннее. Цифры — в шапке файла, пункт 14.
;  vom_hidden: A != 0, если габарит ТЕКУЩЕГО объекта пересекается с живой створкой ворот
;  (слоты 0-3, pending=1). Створки непрозрачны и выводятся последними, поэтому всё, что
;  попало под них, накрыто целиком — гасить чужие плоскости под ними не нужно и вредно
;  (см. блок у vop_on). Клоб A,B,C,D,E,H,L и скретч vom_nc/vom_pl/vom_lo — все три
;  переписываются заново теми, кто их читает (vom_check пишет vom_nc первой строкой).
;  Габарит объекта: столбцы [c0, c0+ncols), строки [lo0-15, lo0] (lo убывает вниз по экрану).
vom_hidden:
	call	vec_su_ptr
	ld	l, 0x99
	ld	a, (hl)
	or	a
	ret	z	; ncols=0 -> пересекаться нечему, A=0
	ld	(vom_nc), a
	ld	l, 0x97
	ld	a, (hl)
	and	0x1F
	ld	(vom_pl), a	; свой c0
	ld	l, 0x98
	ld	a, (hl)
	ld	(vom_lo), a	; свой lo0
	ld	b, 0	; B = индекс створки 0..3
vhd_slot:
	ld	a, b
	add	a, 0x0E0
	ld	h, a
	ld	l, 0x96
	ld	a, (hl)
	dec	a	; pending==1 -> створка выводится в этой пачке
	jp	nz, vhd_next
	ld	l, 0x99
	ld	c, (hl)	; C = ncols створки
	ld	a, c
	or	a
	jp	z, vhd_next
	ld	l, 0x97
	ld	a, (hl)
	and	0x1F
	ld	d, a	; D = c0 створки
	add	a, c	; A = правый край створки
	ld	e, a
	ld	a, (vom_pl)
	ld	c, a	; C = свой c0
	ld	a, (vom_nc)
	add	a, c	; A = свой правый край
	cp	d	; свой правый край <= c0 створки -> мимо
	jp	c, vhd_next
	jp	z, vhd_next
	ld	a, e	; правый край створки <= свой c0 -> мимо
	cp	c
	jp	c, vhd_next
	jp	z, vhd_next
	ld	l, 0x98
	ld	d, (hl)	; D = lo0 створки
	ld	a, (vom_lo)
	sub	16	; свой нижний край (с защитой от заёма)
	jp	nc, vhd_r1
	xor	a
vhd_r1:
	cp	d	; свой низ >= lo0 створки -> мимо
	jp	nc, vhd_next
	ld	a, d
	sub	16
	jp	nc, vhd_r2
	xor	a
vhd_r2:
	ld	e, a	; низ створки
	ld	a, (vom_lo)
	cp	e	; свой lo0 <= низа створки -> мимо
	jp	c, vhd_next
	jp	z, vhd_next
	ld	a, 1	; ПЕРЕСЕКАЮТСЯ
	ret
vhd_next:
	inc	b
	ld	a, b
	cp	4
	jp	c, vhd_slot
	xor	a
	ret
vom_check:
	call	vec_su_ptr
	ld	l, 0x99
	ld	a, (hl)
	or	a
	ret	z	; ncols=0 -> сканировать нечего
	ld	(vom_nc), a
	ld	l, 0x98
	ld	e, (hl)	; E = lo0 (vop_box его не трогает)
	ld	l, 0x97
	ld	a, (hl)	; своя плоскость+столбец -> две чужие по кругу
	add	a, 0x20	; 0x80 -> 0xA0 -> 0xC0 -> 0x80 (столбец сохраняется)
	cp	0x0E0
	jp	c, vom_s1
	sub	0x60
vom_s1:
	ld	(vom_p1), a
	add	a, 0x20
	cp	0x0E0
	jp	c, vom_s2
	sub	0x60
vom_s2:
	ld	(vom_p2), a
	ld	a, e
	ld	(vom_lo), a	; lo0 нужен и точному скану, где E занят спрайтом
	xor	a
	ld	(vom_m), a	; маска плоскостей, которые ПРИДЁТСЯ гасить
;  ===== ДВУХПЛОСКОСТНАЯ МУМИЯ (ЗАДАЧА#51): ОДНА ИЗ «ЧУЖИХ» — ЕЁ СОБСТВЕННЫЙ ДУБЛЬ =====
;  Круговой перебор выше даёт ДВЕ плоскости, отличные от hi0. У цветной мумии (idx6 =
;  p1+p2, idx10 = p0+p2) одна из них — её ВТОРАЯ СВОЯ плоскость (hi0b ЗАПИСИ), и гасить
;  её нельзя ни в коем случае: мумия стёрла бы себе половину цвета. Значит чужая ровно
;  одна — кладём её В ОБЕ ячейки vom_p1/vom_p2, и весь дальнейший механизм (vom_one,
;  vsq_sticky, vom_hit, vom_one1) работает без изменений: маска может стать только 1,
;  до `cp 3` в vom_on дело не дойдёт, hi0b останется РИСУЮЩИМ.
	ld	(vom_dl), a	; A=0: по умолчанию объект одноплоскостный
	ld	l, 0x9A
	ld	a, (hl)	; hi0b ЗАПИСИ != 0 -> вторая СВОЯ плоскость есть
	or	a
	jp	z, vom_sgl
	ld	c, a
	ld	a, (vom_p1)
	cp	c
	ld	a, (vom_p2)	; своя = p1 -> чужая ровно p2
	jp	z, vom_dw
	ld	a, (vom_p1)	; иначе своя = p2, чужая = p1
vom_dw:
	ld	(vom_p1), a
	ld	(vom_p2), a
	ld	(vom_dl), a	; !=0 (страница) — флаг «у объекта есть свой дубль»
	call	vom_one
	jp	vom_st
;  (1) ОБЕ ЧУЖИЕ ПЛОСКОСТИ В fb ПОД НОВЫМ ГАБАРИТОМ, по каждой ОТДЕЛЬНО (ЗАДАЧА#42).
;  Сначала дешёвый OR по габариту (12 тактов на байт): если плоскость пуста — гасить её не
;  надо вовсе. Если не пуста — точный проход ПОД СИЛУЭТОМ (48 тактов на байт), потому что
;  габарит шире фигуры: замер показал 692 срабатывания по габариту против 442 настоящих.
vom_sgl:
	ld	a, (vom_p1)
	call	vom_one
	ld	a, (vom_p2)
	call	vom_one
vom_st:
;  ===== СТИКИ-ГАШЕНИЕ (ЗАДАЧА#50, 2026-08-04): НЕ ОТПУСКАТЬ, ПОКА СТОЛБЕЦ ТОТ ЖЕ =======
;  ЗАЧЕМ. Смена НАБОРА гасимых плоскостей между тиками — крупнейшая причина отказа слитой
;  записи (замер fastmark_why с починенной атрибуцией слота: 55 отказов «hi0b записи !=
;  шапки» + 14 «hi0c» на 1200 тиков, все на слотах мумий 6/7): у идущей по лестнице мумии
;  vom_one отпускает и вновь берёт плоскость через кадр, и КАЖДОЕ переключение выбрасывает
;  ВСЮ пачку (вместе с героем!) на обычный путь — а там дыра стирания героя avg ~13 тыс.
;  тактов, луч в ней — вот и «герой мерцает вверху» (hero_atomic.js: пачки [7,4,5,6]).
;  ЧТО ДЕЛАЕМ. Плоскость, которую гасили в ПРОШЛОЙ пачке (она в ШАПКЕ слота), продолжаем
;  гасить, пока её страница совпадает с одной из наших чужих (то есть столбец не уехал).
;  Гасить ЧИСТУЮ плоскость — визуальный no-op (ANDN по нулям), а набор плоскостей при
;  этом СТАБИЛЕН, и пачка остаётся на слитом пути. Отпускаем набор только в тик, когда
;  столбец сменился — в такой тик слитая запись невозможна и так (hi0 изменился).
;  ЧЕМ ЭТО ОТЛИЧАЕТСЯ ОТ СТРАХОВКИ, СНЯТОЙ ЗАДАЧЕЙ#45. Та возвращала гашение по грубому
;  «в сейве что-то есть ПО ГАБАРИТУ» и была вредна, потому что ТОГДА (до шага C) любой
;  hi0b/hi0c сам по себе выбрасывал пачку со слитого пути — держать гашение было дорого.
;  После шага C слитая запись многоплоскостные объекты УМЕЕТ, и цена перевернулась:
;  дорого не ДЕРЖАТЬ плоскость, а ПЕРЕКЛЮЧАТЬ набор.
	call	vsq_sticky
	ld	a, (vom_m)
	or	a
	jp	nz, vom_on
	ld	a, (vom_dl)
	or	a
	jp	nz, vom_dtail	; у объекта свой дубль -> общий хвост (2) не годится
	call	vec_su_ptr	; --- (2) погашенное прошлой пачкой лежит в сейве ---
	ld	l, 4
	ld	a, (hl)	; hi0b ШАПКИ: гасили ли в прошлой пачке?
	or	a
	ret	z
;  ЗАДАЧА #45: ЕСЛИ ГАБАРИТ НЕ СДВИНУЛСЯ, эта страховка НЕ НУЖНА — и вредна. vom_one уже
;  посмотрел ОБА погашенных блока сейва, и теперь смотрит их ПОД СИЛУЭТОМ. Страховка же
;  берёт те же блоки ЦЕЛИКОМ по габариту, поэтому возвращала гашение ровно в том же тике,
;  в котором точный проход его отпустил, и весь выигрыш обнулялся.
;  Смысл страховки — случай, когда габарит УЕХАЛ: тогда страницы hi0b/hi0c шапки не
;  совпали с плоскостями записи, vom_one ушёл читать ЖИВОЙ fb, а там под старым положением
;  всё погашено нами же, и «чисто» — ложь. Вот там осторожность и остаётся.
;  [дедуп 2026-08-18] проверка «шапка валидна + габарит совпал» вынесена в vom_geq —
;  тот же код стоял и в vom_dtail (дубль 30 Б x2, экономия пошла на vop_eff/vhr_one).
	call	vom_geq
	ret	z	; шапка невалидна ЛИБО габарит тот же -> решение vom_one окончательное
vom_c2:
	ld	l, 3
	ld	a, (hl)	; ncols сейва
	or	a
	ret	z
	add	a, a
	add	a, a
	ld	b, a	; B = 4*ncols витков
	ld	(vom_b), a
	add	a, a
	add	a, a
	add	a, 6	; второй блок плоскостей
	ld	l, a
	xor	a
	call	vop_or4
	or	a
	jp	nz, vom_on
	ld	a, (vom_b)	; третий блок: L уже стоит на его начале
	ld	b, a
	xor	a
	call	vop_or4
	or	a
	ret	z	; чужого фона нет нигде -> мумия выводится как раньше
	ld	a, 3	; под старым габаритом гасили — какую именно плоскость, по сейву
	ld	(vom_m), a	; не разобрать, поэтому консервативно обе (это редкий хвост)
	jp	vom_on
;  ===== ХВОСТ (2) ДЛЯ ОБЪЕКТА СО СВОИМ ДУБЛЕМ (ЗАДАЧА#51) =============================
;  ОБЩИЙ ХВОСТ ЗДЕСЬ НЕПРИМЕНИМ: он опознаёт «прошлая пачка гасила» по hi0b ШАПКИ, а у
;  цветной мумии hi0b — это её СОБСТВЕННАЯ вторая плоскость, и блок фона под ней не пуст
;  почти никогда. Общий хвост поставил бы vom_m=3, а vom_on переназначил бы hi0b ГАСЯЩИМ
;  — мумия стёрла бы себе половину цвета.
;  СМЫСЛ СТРАХОВКИ ТОТ ЖЕ: если ГАБАРИТ УЕХАЛ, vom_one читал ЖИВОЙ fb, а под старым
;  положением мы сами всё погасили — «чисто» там ложь. Гасимая плоскость у нас ровно
;  одна, поэтому разбирать нечего: включаем её (vom_m=1) и уходим общим путём.
vom_dtail:
	call	vec_su_ptr
	ld	l, 5
	ld	a, (hl)	; hi0c ШАПКИ: гасили ли в прошлой пачке?
	or	a
	ret	z
	call	vom_geq	; (общая с хвостом (2) проверка, см. [дедуп 2026-08-18])
	ret	z	; шапка невалидна ЛИБО габарит тот же -> решение vom_one окончательное
	ld	a, 1
	ld	(vom_m), a
	jp	vom_on
;  vom_geq: шапка валидна И габарит (hi0/lo0/ncols) совпал с записью вывода?
;  HL = слот (L любой). Выход ФЛАГОМ: Z -> вызывающему выйти (шапка невалидна ЛИБО
;  габарит тот же — решение vom_one окончательное), NZ -> габарит уехал, нужен
;  осторожный хвост. Клоб A, L.
vom_geq:
	ld	l, 0
	ld	a, (hl)	; шапка валидна?
	dec	a
	jp	nz, vgq_z	; невалидна -> вернуть Z («выйти»)
	ld	l, 1
	ld	a, (hl)	; hi0 шапки == hi0 записи?
	ld	l, 0x97
	cp	(hl)
	ret	nz	; уехал
	ld	l, 2
	ld	a, (hl)	; lo0?
	ld	l, 0x98
	cp	(hl)
	ret	nz
	ld	l, 3
	ld	a, (hl)	; ncols?
	ld	l, 0x99
	cp	(hl)
	ret		; Z от cp: совпал -> «выйти», NZ -> уехал
vgq_z:
	xor	a
	ret
;  vom_one: нужна ли ГАСИМАЯ плоскость A (страница fb = плоскость+столбец)? Дешёвый OR по
;  габариту, и только если он не пуст — точный проход под силуэтом. Ставит бит в vom_m.
vom_one:
	ld	(vom_pl), a
;  ЕСЛИ ЭТУ ПЛОСКОСТЬ ГАСИЛА ПРОШЛАЯ ПАЧКА, читать её из fb НЕЛЬЗЯ — там уже не фон.
;  Чистый фон оттуда лежит в сейве: блоки идут [своя, hi0b, hi0c], пропущенных нет.
;  Здесь работает инерция (решение по СТАРОМУ габариту): выключаем гашение только когда
;  сохранённый кусок пуст. Лишний кадр гашения не виден — гасить в нём уже нечего.
	call	vec_su_ptr
	ld	l, 0
	ld	a, (hl)	; шапки нет -> прошлая пачка ничего не гасила
	dec	a
	jp	nz, vom_fb
	ld	l, 4
	ld	a, (vom_pl)
	cp	(hl)	; это первый гасящий прошлой пачки?
	jp	z, vom_blk1
	ld	l, 5
	cp	(hl)	; второй?
	jp	nz, vom_fb
	ld	a, (hl)
	ld	l, 4
	ld	a, (hl)
	or	a	; первого не было -> второй лежит вторым блоком
	jp	z, vom_blk1
	ld	l, 3
	ld	a, (hl)
	add	a, a	; смещение третьего блока = 6 + 32*ncols
	add	a, a
	add	a, a
	add	a, a
	add	a, a
	jp	vom_blkw
vom_blk1:
	ld	l, 3
	ld	a, (hl)
	add	a, a	; смещение второго блока = 6 + 16*ncols
	add	a, a
	add	a, a
	add	a, a
vom_blkw:
	add	a, 6
	ld	e, a
	ld	l, 3
	ld	a, (hl)
	add	a, a
	add	a, a
	ld	b, a	; B = 4*ncols витков
	ld	a, e
	ld	l, a
	xor	a
	call	vop_or4
	or	a
	ret	z	; сохранённый фон пуст -> гашение этой плоскости больше не нужно
;  ===== ЗАДАЧА #45: ИНЕРЦИЯ ТОЖЕ СМОТРИТ ПОД СИЛУЭТ, А НЕ ПО ГАБАРИТУ ==================
;  ЧТО БЫЛО. Здесь стоял `jp vom_hit`: раз сохранённый блок не пуст ГДЕ-ТО В ГАБАРИТЕ —
;  гасим. Габарит шире фигуры, поэтому, сработав однажды, гашение держалось кадрами само
;  себя (сейв -> инерция -> сейв). Замер tools/debug/vom_rate.js: после прижатия силуэта
;  мумии влево (задача #44) детектор гасил в 30.6% вызовов против 0.7% раньше, и 172
;  срабатывания из 190 давала именно эта ветка — при НУЛЕ реально загрязнённых пикселей
;  по tools/verify/momia_purity.js. Цена холостого гашения — лишняя плоскость в сейве,
;  стирании и выводе плюс уход всей пачки со слитого пути (vsp_fastmark отвергает hi0b).
;  ЧТО СТАЛО. Тот же точный проход «фон И силуэт», что задача #42 уже делает для живого
;  fb, только фон берётся из сохранённого блока. Оба массива лежат В ОДНОЙ СТРАНИЦЕ слота
;  и подряд (блок плоскости = 16*ncols байт, силуэт = 0xA0..0xCF), поэтому проход
;  одноцикловый, без разбивки по столбцам.
;  КОГДА ЭТО ЗАКОННО. Сейв снят под СТАРЫМ габаритом, силуэт собран под НОВЫМ; складывать
;  их поэлементно можно, только если габарит не сдвинулся. По hi0 это уже гарантировано
;  входом сюда: в инерционную ветку пускает совпадение hi0b/hi0c ШАПКИ с плоскостью
;  ТЕКУЩЕЙ записи, а они отличаются ровно на столбец (hi0 = плоскость+столбец). Остаётся
;  сверить lo0 и ncols; если они разъехались — ведём себя как раньше (гасим), это тот же
;  осторожный хвост, что и был.
	ld	l, 2
	ld	a, (hl)	; lo0 шапки == lo0 записи?
	ld	l, 0x98
	cp	(hl)
	jp	nz, vom_hit
vom_blo:	; метка для замера: lo0 совпал
	ld	l, 3
	ld	a, (hl)	; ncols шапки == ncols записи?
	ld	l, 0x99
	cp	(hl)
	jp	nz, vom_hit
vom_bok:	; метка для замера (tools/debug/vom_rate.js): габарит совпал, идёт точный проход
	add	a, a	; B = 16*ncols байт подряд (весь блок плоскости)
	add	a, a
	add	a, a
	add	a, a
	ld	b, a
	ld	d, h	; DE = сохранённый фон плоскости (E уцелел: vop_or4 не трогает DE)
	ld	l, 0x0A0	; HL = сдвинутый силуэт в буфере слота
vom_bx:
	ld	a, (de)
	and	(hl)
	jp	nz, vom_hit
	inc	l
	inc	e
	dec	b
	jp	nz, vom_bx
	ret		; под силуэтом чисто -> гашение этой плоскости больше не нужно
vom_fb:
	ld	a, (vom_pl)
	ld	d, a
	ld	a, (vom_nc)
	ld	c, a
	ld	a, (vom_lo)
	ld	e, a
	xor	a
	call	vop_box	; дешёвый: пусто по габариту -> точно не нужна
	or	a
	ret	z
;  ТОЧНЫЙ ПРОХОД: фон И силуэт. DE = спрайт в слоте (идёт подряд через все столбцы),
;  HL = fb, B = строки, C = столбцы; выход по ПЕРВОМУ найденному биту — искать дальше
;  незачем, а в «грязном» случае это ещё и быстрее.
	call	vec_su_ptr
	ld	d, h	; DE = буфер спрайта слота
	ld	e, 0x0A0
	ld	a, (vom_nc)
	ld	c, a
	ld	a, (vom_pl)
	ld	h, a	; H = страница fb проверяемой плоскости
vom_xc:
	ld	a, (vom_lo)
	ld	l, a
	ld	b, 16
vom_xr:
	ld	a, (de)
	and	(hl)
	jp	nz, vom_hit
	inc	l
	inc	e
	dec	b
	jp	nz, vom_xr
	inc	h	; следующий столбец fb; спрайт (DE) уже на его начале
	dec	c
	jp	nz, vom_xc
	ret		; под силуэтом чисто -> эту плоскость гасить не надо
;  vsq_sticky: vom_m |= гасимые плоскости ШАПКИ слота, чьи страницы совпали с vom_p1/vom_p2
;  (столбец не уехал). Сопоставление по РАВЕНСТВУ страницы: страница шапки = плоскость +
;  столбец, поэтому уехавший столбец отсеивается сам. Клоб A,B,C,L (H = страница слота).
vsq_sticky:
	call	vec_su_ptr
	ld	l, 0
	ld	a, (hl)
	dec	a
	ret	nz	; шапки нет — гасить в прошлой пачке не могли
	ld	l, 4
	ld	a, (hl)	; hi0b шапки
	call	vsq_one
	ld	l, 5
	ld	a, (hl)	; hi0c шапки (хвостовой вызов — общий выход через ret)
vsq_one:
	or	a
	ret	z	; плоскости в шапке нет
	ld	c, a
	ld	a, (vom_p1)
	cp	c
	ld	a, 1	; MVI флаги не трогает
	jp	z, vsq_set
	ld	a, (vom_p2)
	cp	c
	ret	nz	; страница не совпала — столбец уехал, набор можно отпустить
	ld	a, 2
vsq_set:
	ld	b, a
	ld	a, (vom_m)
	or	b
	ld	(vom_m), a
	ret
vom_hit:
	ld	a, (vom_pl)	; отметить плоскость в маске: бит 0 = первая, бит 1 = вторая
	ld	c, a
	ld	a, (vom_p1)
	cp	c
	ld	a, 1
	jp	z, vom_mset
	ld	a, 2
vom_mset:
	ld	c, a
	ld	a, (vom_m)
	or	c
	ld	(vom_m), a
	ret
vom_on:
	call	vec_su_ptr
	ld	l, 0x0D0
	ld	(hl), 0	; по умолчанию hi0b не используется
	ld	a, (vom_m)
	cp	3
	jp	nz, vom_one1	; гасить надо ОДНУ плоскость -> хватит штатного hi0c
	ld	l, 0x0D0
	ld	(hl), 1	; hi0b теперь ГАСИТ
	ld	a, (vom_p1)
	ld	l, 0x9A
	ld	(hl), a	; hi0b для сейва
	ld	l, 0x9F
	ld	(hl), a	; hi0b для вывода
	ld	a, (vom_p2)
	ld	l, 0x9B
	ld	(hl), a	; hi0c — второе гашение
	ret
;  Гасить надо ровно ОДНУ плоскость: она уходит в штатный hi0c, hi0b остаётся нулём —
;  слот держит ДВА блока плоскостей вместо трёх, сейв/стирание/вывод короче на треть.
vom_one1:
	ld	a, (vom_m)
	dec	a
	ld	a, (vom_p1)
	jp	z, vom_o1w
	ld	a, (vom_p2)
vom_o1w:
	ld	l, 0x9B
	ld	(hl), a
	ret
;  vop_box: A |= фон под габаритом одной плоскости. D = страница fb (плоскость+столбец),
;  C = ncols, E = lo0. Столбец fb — 16 подряд байт внутри страницы, столбцы = соседние
;  страницы. Клоб B,H,L,C,D; A накапливает, E цел.
vop_box:
	ld	h, d
	ld	l, e
	ld	b, 4
	call	vop_or4
	inc	d
	dec	c
	jp	nz, vop_box
	ret
;  vop_or4: A |= байты по (HL), B четвёрок; HL продвигается через inc l (столбец fb и блок
;  слота — 16 подряд байт внутри страницы). Развёрнуто вчетверо: 12 тактов на байт.
vop_or4:
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	dec	b	; A не трогает
	jp	nz, vop_or4
	ret
vsd_none:
	xor	a
	ld	(vsp_dpg), a
	ret
;  --- выбор паттерна (перенесено из vec_nsx: зеркала генерятся на лету) ---
;  ШАГ4a: зеркало «влево» ТОЛЬКО для pat в [0x60,0x94) — это ровно диапазон, куда
;  flipSprites клал горизонт-копии hero(0x60-0x87)+momia(0x88-0x93). pat>=0x94 — НЕ
;  зеркала, а реальные спрайты (двери входа и пр.), их берём напрямую.
;  ===== ЖЁСТКОЕ ОТСЕЧЕНИЕ ГАБАРИТА СВЕРХУ (ЗАДАЧА#56, 2026-08-10) =====================
;  ЧТО ЛЕЧИМ. Столбец спрайта — 16 подряд байт ВНУТРИ страницы fb, обход через `inc l`.
;  При отрицательном Y (прыжок на верхней площадке уводит Y до -16) lo0 = 239-Y доходит
;  до 255, и строки lo0+1..lo0+15 ЗАВОРАЧИВАЮТСЯ через 255->0 — то есть в ВЕРХНЮЮ КАЙМУ.
;  Раньше это был просто мусор над полем (top_border_gate: 40% кадров). ТЕПЕРЬ В КАЙМЕ
;  ЖИВЁТ ТАБЛО (fb 15..8), и писать туда нельзя ВООБЩЕ — ни спрайтом, ни нулём: и то и
;  другое затирает буквы. Значит клип ЖЁСТКИЙ: то, что выше fb 255, не пишется никак.
;  ПОЧЕМУ ЭТО ОДНА ПРОЦЕДУРА В ПОДГОТОВКЕ, А НЕ ПРАВКА ШЕСТИ ПЕТЕЛЬ. Все петли работы с
;  fb — вывод OR (vsb_or), слитая запись по столбцам (vsb_mcol) и по строкам (vsb_mrow),
;  стек-блит (vpz_wr, POP парами!), сохранение фона (vsu_scol) и стирание (vsu_rcol) —
;  РАЗВЁРНУТЫ РОВНО НА 16 СТРОК и все опираются на один и тот же документированный
;  инвариант «lo0 <= 240, столбец не пересекает границу страницы» (см. шапку vsb_or).
;  При отрицательном Y инвариант нарушался — и ломался он в ОДНОМ месте, в геометрии.
;  Поэтому чиним геометрию: габарит прижимается к lo0 = 240, а данные спрайта СДВИГАЮТСЯ
;  внутри буфера на d = lo0-240 строк вверх по индексу, освободившийся низ зануляется.
;  СТРОКИ, ВЫШЕДШИЕ ЗА fb 255, ПРИ ЭТОМ ВЫТАЛКИВАЮТСЯ ИЗ БУФЕРА И ПРОПАДАЮТ — это и есть
;  отсечение. Ни одна петля не изменилась ни на байт, ни на такт.
;  ПОЧЕМУ КАРТИНКА ОСТАЁТСЯ ВЕРНОЙ. Буфер лежит НИЗ-ВВЕРХ: байт k столбца идёт в fb-строку
;  lo0+k. Хотим, чтобы содержимое строки lo0+k оказалось в строке 240+j, то есть j = k+d.
;  Это ровно сдвиг индекса на +d; байты с k > 15-d уезжают за конец столбца (их строки
;  fb > 255 — их и надо выбросить), а места j < d занимают НУЛИ. Ноль в буфере безвреден
;  на ЛЮБОМ пути: OR-вывод оставляет фон как есть, слитая запись кладёт «фон OR 0» = фон,
;  а save/restore и вовсе работают с фоном, а не с буфером. Итог совпадает с MSX: VDP
;  режет спрайт по верхней строке экрана, у нас верхняя строка экрана = fb 255.
;  ГДЕ СТОИТ ВЫЗОВ: сразу после vsp_pat (буфер собран) и ДО сужения footprint'а — сдвиг
;  может обнулить 3-й столбец целиком, и тогда объект законно сузится до 2 столбцов.
;  ДЕДУП ПАРЫ (vsd_dropb) не ломается: он срабатывает только при РАВНЫХ lo0, значит у
;  донора и приёмника одинаковый d, и OR-слияние буферов идёт строка-в-строку.
;  ЦЕНА: 72 Б образа (легли в зазор выравнивания — итоговый образ не вырос ни на байт),
;  0 тактов на подавляющем большинстве объектов (`sub 241` + переход по C), ~450 тактов
;  ТИКА в кадрах, где габарит реально заворачивает (верхняя площадка).
;  Клоб A,B,C,D,E,H,L — ровно как у соседнего vsp_pat, вызыватель после него всё
;  перечитывает из памяти.
;  ===== РАУНД 2 (2026-08-12): КЛИП СДВИНУТ НА 8 СТРОК — ЗАЗОР ОТДАН СПРАЙТАМ =========
;  ЖАЛОБА ВЛАДЕЛЬЦА С ЖЕЛЕЗА: «под HUD невидимая область — герой запрыгивает под неё и
;  его спрайт скрывается». Так и было: клип резал габарит по fb 255 = верхней строке
;  ПОЛЯ, а над полем лежал пустой зазор, куда спрайту было нельзя. Теперь зазор fb 7..0
;  (8 строк между полем и табло, см. карту кадра в vec_boot.asm) — РАБОЧАЯ ЗОНА:
;  габарит пускается до fb 7 включительно, и герой в прыжке виден над верхней строкой,
;  как на MSX. Выше fb 7 не пускаем НИКОГДА: fb 15..8 — буквы табло.
;  АРИФМЕТИКА. Порог 241 -> 249: заворота «не бывает» при lo0 <= 248, потому что габарит
;  = lo0..lo0+15 = 248..255 и 0..7 — то есть ровно верхняя строка поля плюс весь зазор.
;  Прижимаем к 248 (было 240), d = lo0-248 (1..7); формула хвоста (cpl + add 17 = 16-d)
;  от порога не зависит и не тронута. ЦЕНА: НОЛЬ БАЙТ, две непосредственные константы.
;  ЧТО ЭТО ПОТРЕБОВАЛО ОТ ПЕТЕЛЬ. Инвариант «lo0 <= 240» превратился в «lo0 <= 248», то
;  есть столбец fb ТЕПЕРЬ МОЖЕТ ЗАВОРАЧИВАТЬСЯ 255->0. Пройдены все шесть потребителей:
;    vsb_or   — адресует `inc l`  -> заворот внутри столбца, H цел         ОК
;    vsb_mcol — `ld (bc),a`+`inc c`                                        ОК
;    vsb_mrow — `ld (bc),a`+`inc c`, конец строки по равенству с lo0+16    ОК
;    vpz_wr   — стек-блит: SP смотрит в БУФЕР СЛОТА (он не заворачивается),
;               приёмник fb — `inc l`                                      ОК
;    vsu_rcol — restore: SP в слоте, приёмник fb — `inc l`                 ОК
;    vsu_scol — save: SP смотрит В СТОЛБЕЦ fb, и POP переносит в СТАРШИЙ БАЙТ ->
;               на завороте читал бы СОСЕДНИЙ СТОЛБЕЦ. ЕДИНСТВЕННАЯ сломанная
;               петля; для завёрнутого габарита заведён отдельный проход без SP
;               (vsu_scw в vec_saveunder.asm).
vclp:
	ld	a, (vsu_lo)
	sub	249	; lo0 <= 248 -> заворота за зону спрайтов нет
	jp	c, vclp_no
	inc	a	; A = d = lo0-248 (1..7)
	ld	(vclp_d1+1), a
	ld	(vclp_d2+1), a
	cpl	; 255-d
	add	a, 17	; = 16-d: сколько байт столбца переживает клип
	ld	(vclp_n+1), a
	ld	a, 248
	ld	(vsu_lo), a	; габарит прижат к ВЕРХУ ЗАЗОРА (fb 7 — строка под табло)
	ld	a, (vsp_pg)
	ld	h, a
	ld	c, 0x0A0	; C = база столбца буфера: 0xA0, 0xB0, 0xC0
vclp_col:
	ld	a, c
	add	a, 15
	ld	l, a	; HL = верх столбца (приёмник, идём вниз)
vclp_d1:
	sub	0	; ОПЕРАНД: d -> DE = источник = приёмник - d
	ld	e, a
	ld	d, h
vclp_n:
	ld	b, 0	; ОПЕРАНД: 16-d
vclp_mv:
	ld	a, (de)
	ld	(hl), a
	dec	l
	dec	e
	dec	b
	jp	nz, vclp_mv
vclp_d2:
	ld	b, 0	; ОПЕРАНД: d
	xor	a
vclp_z:
	ld	(hl), a	; низ столбца: строк спрайта там больше нет
	dec	l
	dec	b
	jp	nz, vclp_z
	ld	a, c	; следующий столбец буфера
	add	a, 16
	ld	c, a
	cp	0x0D0
	jp	c, vclp_col
vclp_no:
	ret

vsp_pat:
	ld	hl, (vec_nsp_ptr)
	inc	hl
	inc	hl
	ld	a, (hl)	; A = pat
	ld	b, 0
	cp	0x60
	jp	c, vsp_hp
	cp	0x94
	jp	nc, vsp_hp
	sub	0x60	; база = pat-0x60; B=1 (зеркало)
	ld	b, 1
;  ЗАДАЧА #12 + фаза 2 shared-pool: герой — карта (vsp_hbase) + vec_spr_pool; кадр
;  собирается в vec_spr_asml. Мумия — линейная таблица образа. sprites2/карта — vec_spr_buf.
;  Зеркало: кэш vec_spr_buf_mir сплошной (собирает vec_spr_mkmir через тот же vsp_asm).
vsp_hp:
	and	0x0FC	; база паттерна 16x16 (младшие 2 бита игнорируются)
	ld	l, a	; L = номер базового паттерна
	ld	a, b
	or	a
	ld	de, vec_spr_buf_mir	; зеркало -> предотзеркаленный кэш
	jp	nz, vsp_off
	ld	a, l
	cp	0x28	; < 0x28 -> набор героя (карта + pool -> asml)
	jp	nc, vsp_nh
;  ОПЕРАНД: vec_spr_prota / vec_spr_knife / vec_spr_pico (КАРТЫ индексов ячеек).
;  loadAnimation пишет сюда базу через IndexSprites. Хвост 0x18-0x27 у prota уже в карте
;  (= knife), отдельной развилки нет.
vsp_hbase:
	ld	de, 0
	call	vsp_asm
	ld	(vnsx_pat), hl
	jp	vsp_msk
vsp_nh:
	ld	de, vec_spr_momia-0x140	; мумия: паттерны 0x28-0x33
	cp	0x0A0
	jp	c, vsp_off
	sub	0x0A0	; sprites2/карта: остаток буфера в ОЗУ, сжатие -0xA0
	ld	l, a
	ld	de, vec_spr_buf
vsp_off:
	ld	h, 0
	add	hl, hl	; *8
	add	hl, hl
	add	hl, hl
	add	hl, de	; HL = БАЗА паттерна (32Б: L0-15, R0-15)
	ld	(vnsx_pat), hl	; ЗАДАЧА#34: флага vnsx_mir больше нет — обе ветки давно клали в
;  него НОЛЬ (зеркало берётся готовым из vec_spr_buf_mir), а on-the-fly реверс не вызывался
;  --- настройка сдвига и масок (одна на объект: обе половины сдвинуты одинаково) ---
vsp_msk:
	ld	a, (vsp_sh)
	ld	l, a
	ld	h, 0
	ld	de, vsp_masks
	add	hl, de
	ld	a, (hl)	; маска своего столбца = 0xFF>>s
	ld	(vsp_m1+1), a
	cpl	; ~маска = перелив в соседний столбец
	ld	(vsp_m2+1), a
	ld	hl, vsp_r0	; вход в цепочку rrca = vsp_r0 - s (каждый rrca = 1 байт)
	ld	a, (vsp_sh)
	ld	c, a
	ld	a, l
	sub	c
	ld	l, a
	ld	a, h
	sbc	a, 0
	ld	h, a
	ld	(vsp_jp+1), hl
;  --- половина 0 (экранный X): столбец 0 буфера ЗАПИСЬЮ, перелив в столбец 1 ---
	call	vec_su_ptr	; H = страница слота
	ld	a, h
	ld	(vsp_pg), a
	ld	hl, (vnsx_pat)	; слева = ЛЕВАЯ половина базы (зеркало уже готово в кэше)
	ld	b, h
	ld	c, l	; BC = паттерн половины
	xor	a	; 0x00 = nop: столбец 0 пишется поверх (обнулять не надо)
	ld	(vsp_orm), a
	ld	(vsp_orm2), a
	ld	a, 0x9F	; конец главного столбца (0xAF-16)
	ld	(vsp_cpe+1), a
	ld	(vsp_cpe2+1), a
	ld	a, (vsp_pg)
	ld	h, a
	ld	d, a
	ld	l, 0x0AF	; столбец 0, верхняя строка (буфер идёт вниз)
	ld	e, 0x0BF	; столбец 1 — перелив
	call	vsp_row
;  --- половина 1 (X+8): столбец 1 ЧЕРЕЗ OR (там уже лежит перелив половины 0) ---
	ld	hl, (vnsx_pat)	; справа = ПРАВАЯ половина базы (+16)
	ld	a, l
	add	a, 16
	ld	l, a
	ld	a, h
	adc	a, 0
	ld	h, a
	ld	b, h
	ld	c, l
	ld	a, 0x0B6	; 0xB6 = or (hl)
	ld	(vsp_orm), a
	ld	(vsp_orm2), a
	ld	a, 0x0AF	; конец главного столбца (0xBF-16)
	ld	(vsp_cpe+1), a
	ld	(vsp_cpe2+1), a
	ld	a, (vsp_pg)
	ld	h, a
	ld	d, a
	ld	l, 0x0BF
	ld	e, 0x0CF
;  --- строчная петля сдвига: BC=паттерн (сверху вниз), HL=главный столбец буфера,
;  DE=столбец перелива (оба идут ВНИЗ по адресу = ВВЕРХ по экрану). Сдвиг — вход в
;  цепочку rrca по самомодифицируемому jp; маски и конец столбца — тоже immediate'ы.
;  Правый край экрана здесь НЕ проверяется (буфер линейный) — его режет ncols вывода.
vsp_row:
	ld	a, (bc)
	inc	bc
	or	a	; ПРОЗРАЧНАЯ строка (в среднем 6 из 10) -> короткий путь без сдвига
	jp	z, vsp_zrow
vsp_jp:
	jp	vsp_r0	; ОПЕРАНД: vsp_r0-s (ровно s штук rrca)
vsp_r7:
	rrca
vsp_r6:
	rrca
vsp_r5:
	rrca
vsp_r4:
	rrca
vsp_r3:
	rrca
vsp_r2:
	rrca
vsp_r1:
	rrca
vsp_r0:
	push	af	; повёрнутый байт нужен дважды (свой столбец + перелив)
vsp_m1:
	and	0x0FF	; ОПЕРАНД: 0xFF>>s
vsp_orm:
	or	(hl)	; САМОМОД: 0xB6=OR (2-я половина) / 0x00=nop (1-я)
	ld	(hl), a
	dec	l
	pop	af
vsp_m2:
	and	0	; ОПЕРАНД: ~(0xFF>>s)
	ld	(de), a
	dec	e
	ld	a, l
vsp_cpe:
	cp	0	; ОПЕРАНД: адрес за концом главного столбца
	jp	nz, vsp_row
	ret
;  Прозрачная строка (A=0): в свой столбец кладём то, что там уже лежит (для 2-й половины
;  это перелив 1-й, для 1-й — ничего, потому что nop), в соседний — ноль. Обнулять буфер
;  заранее не нужно: каждый байт записывается ровно один раз.
vsp_zrow:
vsp_orm2:
	or	(hl)	; САМОМОД вместе с vsp_orm
	ld	(hl), a
	dec	l
	xor	a
	ld	(de), a
	dec	e
	ld	a, l
vsp_cpe2:
	cp	0	; ОПЕРАНД вместе с vsp_cpe
	jp	nz, vsp_row
	ret
;  Фаза 2: собрать 32Б кадр героя из карты + pool → vec_spr_asml.
;  Вход: L = pat&0xFC, DE = база карты (vec_spr_prota/knife/pico).
;  Выход: HL = vec_spr_asml. Портит AF, BC, DE.
vsp_asm:
	ld	h, 0
	add	hl, de		; HL = &map[pat]
	ld	de, vec_spr_asml
	ld	b, 4
vsa_cell:
	ld	a, (hl)
	inc	hl
	push	hl
	push	de
	ld	l, a
	ld	h, 0
	add	hl, hl
	add	hl, hl
	add	hl, hl		; *8
	ld	de, vec_spr_pool
	add	hl, de
	pop	de
;  [2026-08-26] РАЗВЁРТКА ЭТОЙ ПЕТЛИ ОТКАЧЕНА. Перенос slots-in-ram e0dab49 давал
;  vsp_asm 2432 -> 1728 такта на вызов (-29%), но на нём же стенд topright_jump_probe
;  показал остаток спрайта в верхнем ряду (orphan 0 -> 10), а бисект вышел НЕмонотонным
;  (следующий шаг с той же развёрткой давал 0). Пока причина не понята, у владельца на
;  железе должна быть сборка без открытого вопроса. Возвращать вместе с разбором
;  заворота габарита — см. docs/PLAN-2026-08-26-flicker.md.
	ld	c, 8
vsa_b:
	ld	a, (hl)
	ld	(de), a
	inc	hl
	inc	de
	dec	c
	jp	nz, vsa_b
	pop	hl
	dec	b
	jp	nz, vsa_cell
	ld	hl, vec_spr_asml
	ret
vsp_masks:
	db	0x0FF, 0x07F, 0x03F, 0x01F, 0x00F, 0x007, 0x003, 0x001
;  ================= ФАЗА 2: ВЫВОД (вызывается из ISR в начале кадра) =================
;  СТИРАНИЕ + СКОЛЬЗЯЩИЙ ФРОНТ СЕЙВОВ В ПОРЯДКЕ ЛУЧА (задача #5, 2026-07-31):
;   1) стереть ВСЕХ (20->0, раскрутка перекрытий) — как было, это критично для корректности;
;   2) отсортировать порядок вывода по lo0 ПО УБЫВАНИЮ (= сверху вниз, порядок хода луча);
;   3) идти по этому порядку и перед выводом объекта досохранять фон РОВНО ТЕМ, кто может
;      с ним пересечься по вертикали (lo0 > lo0(объекта)-16: высота спрайта 16 строк).
;      Остальные сохранятся, когда до них дойдёт очередь.
;
;  ЗАЧЕМ (замер 4000 кадров живой игры). Раньше «сохранить фон» было ГЛОБАЛЬНЫМ проходом
;  ПЕРЕД выводом, поэтому ПЕРВЫЙ пиксель попадал в fb только после 2/3 всей работы пачки:
;  при 3 объектах на такте 17474, при 4 — 21647, при 6 — 38677 от прерывания. А луч
;  приходит на ВЕРХ игрового поля уже на такте 13780 (дальше 192 такта на строку).
;  Верхние объекты систематически не успевали: транзиентных пикселей в верхней половине
;  поля 2028 против 10 в нижней (200x). Скользящий фронт выводит первый объект сразу,
;  как только сохранён он сам и его соседи по вертикали. РАБОТА ТА ЖЕ (ни одного лишнего
;  байта в fb), меняется только порядок; логика тика не сдвинута ни на такт, поэтому
;  отзывчивость и плавность не затронуты вообще.
;
;  ===== ЧТО ЗАМЕРЕНО И ОТВЕРГНУТО ПО ФЛИКУ (задача #5, шаг 2, 2026-07-31) =====
;  Инструменты: tools/verify/beam_anchor.js (окна луча), beam_ops.js (цена проходов),
;  beam_dup.js (двойное покрытие fb), spr_resid_gate.js (гейт шлейфа).
;
;  1) «ОБНОВЛЯТЬ ВЕРХНИЕ СПРАЙТЫ ПОСЛЕ ПРОХОДА ЛУЧА» — НЕКУДА ПОСТАВИТЬ. Кадр целиком
;     исполняется ВНУТРИ ISR (палитра -> скан клавиш -> пачка -> H_TIMI), main = чистый
;     halt, а прерывание одно на кадр и растрового регистра у Вектора нет: узнать позицию
;     луча можно только счётом тактов от IRQ, а работа до любой точки — от данных.
;     Замер 12000 кадров: игровой тик укладывается в свой кадр лишь в 60.5% случаев
;     (конец тика p50 = 51116 тактов, p90 = 93392 при кадре 59904); в кадрах, где в пачке
;     ЕСТЬ верхний объект, тик вылезал за кадр в 97-100%. Прямая симуляция переноса пары
;     (стирание+вывод) на два единственных якоря внутри тика — РВЁТ БОЛЬШЕ, чем сейчас:
;       как есть                        15.6% объектов рвётся лучом,  83432 пикс
;       якорь «после vec_nat_sprites»   26.5%,                      174208 пикс
;       якорь «конец тика H_TIMI»       25.7%,                      172048 пикс
;     Кадра задержки схема, вопреки ожиданию, НЕ добавляет (вывод уезжает в ТОТ ЖЕ тик,
;     что подготовил данные: -0.97 кадра), но выигрыш всё равно отрицательный.
;     Выигрыш есть только на узкой верхней зоне (Ytop<48: 13.7% против 15.6%), а ГЕРОЙ
;     туда не заходит НИКОГДА: замер Ytop героя (слоты 4/5) min=55, p50=95, доля Ytop<48
;     = 0 из 1884 объекто-кадров. Верхняя зона — это мумии (слот 6), и она и так чиста.
;
;  2) ОКНО СТИРАНИЯ (стирание третьим фронтом, рядом со своим объектом) — НЕ РАБОТАЕТ,
;     ПОТОМУ ЧТО ОБЪЕКТЫ СЦЕПЛЕНЫ. Типовая раскладка lo0 [160,160,151,151,144,144] —
;     ОДНА цепочка пересечений, а в цепочке все сейвы обязаны предшествовать всем выводам
;     (иначе сейв снимет чужие нарисованные пиксели = шлейф). Значит стирание в лучшем
;     случае подъезжает к НАЧАЛУ сейвов, то есть всё равно за ~20 тыс. тактов до вывода.
;     Реализовано и замерено: транзиент 1392 -> 2144 пикс, опоздавших 6 -> 8, пачка +1000
;     тактов на объект (бухгалтерия фронтов) — ОТКАЧЕНО.
;     По той же причине бесполезен и обратный порядок стираний (снизу вверх): замер дал
;     ровно 0 разницы в транзиенте — все restore успевают в первые ~10 тыс. тактов, а луч
;     приходит на героя на 27.4 тыс.
;
;  3) ГДЕ ФЛИК НА САМОМ ДЕЛЕ (детерминированный A/B, 400 сценариев): весь остаточный
;     транзиент сидит на Ytop 64..95 — это ГЕРОЙ и мумии, 1368 из 1392 пикселей. Луч
;     приходит на них на 27.4-31.2 тыс. тактов, а пачка из 4 объектов доводит их до fb
;     на 27.8-31.4 тыс. Не хватает 152..3812 тактов. Верх экрана (Ytop<48) уже чист.
;
;  4) ЧТО ЭТО ЗНАЧИТ ДЛЯ СЛЕДУЮЩЕГО ШАГА. Переставлять работу внутри пачки больше нечего —
;     нужно её СОКРАЩАТЬ. Два адреса, оба замерены:
;     а) ДВОЙНАЯ РАБОТА ГЕРОЯ. Слот 4 (одежда) пишет p2, слот 5 (кожа) пишет p1 и ДУБЛЬ
;        в p2 — один и тот же кусок p2 сохраняется и стирается ДВАЖДЫ. beam_dup.js:
;        двойное покрытие в 73.9% пачек, 50.6 байт на пачку; при 36 тактах/байт на сейв
;        и 35 на стирание это ~3.6 тыс. лишних тактов КАЖДЫЙ кадр, ровно перед выводом
;        героя — т.е. ровно та дырка из пункта 3. Слоты 4 и 5 всегда попадают в пачку
;        вместе (980 пачек, «только 4» = 0, «только 5» = 0), так что дедуп безопасен.
;        ВАЖНО: решение о дедупе должно приниматься в ПОДГОТОВКЕ (тик, O(1) на объект).
;        Реализация со сканом пар внутри пачки замерена и ОТКАЧЕНА: сама бухгалтерия
;        (~425 тактов на объект) съедала сэкономленные 1.6 тыс.
;     б) КОМПОЗИЦИЯ В БУФЕРЕ. Сейчас область экрана «в разобранном виде» всё время от
;        стирания до вывода — для цепочки это вся пачка. Если собирать «фон OR спрайт»
;        в ОЗУ и выводить одним проходом, разобранного состояния нет вовсе, а опасное
;        окно = длительность одного блита. Цены на объект (beam_ops.js, 2 плоскости,
;        2 столбца, 64 байта fb): стирание 2249 + сейв 2309 + вывод 3299 = 7857 тактов;
;        при композиции под лучом остаётся только финальный блит (~1.5 тыс. обычной
;        записью, ~0.9 тыс. стек-блитом) — окно уже в 5-16 раз. ОЗУ: композиция идёт
;        ПОПЛОСКОСТНО, буфера на 48Б достаточно, и он влезает в свободный хвост страницы
;        слота 0xD0..0xFF — НОВОГО ОЗУ НЕ НУЖНО.
;
;  ===== ЗАМЕРЕНО И ОТВЕРГНУТО ПО МУМИЯМ И ПРЕДСДВИГАМ (2026-07-31) =====
;  Инструменты (в репозитории): tools/verify/mummy_survey.js (цена кадра в разрезе
;  ворота/герой/мумии/нож/карта), tools/verify/sprite_phase_profile.js (профиль кадра
;  по фазам спрайтовой подсистемы). Оба гоняют 6-8 пирамид по 900 кадров ГЕЙМПЛЕЯ.
;
;  ГДЕ НА САМОМ ДЕЛЕ УХОДИТ КАДР (тактов на кадр геймплея, кадр = 59904):
;    флаги Ф 2494 + sticky 836 + список видимых 1360 + распространение П 2587 +
;    цикл подготовки 2914  = 10190 (собственный код vec_nat_sprites, 17.0% кадра)
;    vec_spr_prep 5037 (8.4%), из них СДВИГ (vsp_pat) 4264
;    save-under restore+save 3432 (5.7%), пачка vec_spr_out+show 3439 (5.7%)
;    прочий тик 20213, halt 16359.
;  В разрезе объектов (подготовка + пачка): ГЕРОЙ 9213, МУМИИ 1158, ворота 89.
;  Мумии — 5% работы подсистемы: на экране их НЕ БОЛЬШЕ ДВУХ (замер 12 пирамид, max=2,
;  средн. 1.7/1.4/1.2/0.7/1.0/1.4/1.1 на пирамидах 1-7, дальше почти ноль), и они
;  МЕДЛЕННЫЕ: атрибуты слота 6 меняются в 4.1% кадров, слота 7 — в 15.8%, тогда как
;  оба слота героя (4,5) — в 33.6%. Итог: 0.078 подготовок мумии против 0.68 героя.
;
;  1) «СВЕСТИ ЦВЕТ МУМИЙ В ОДНУ ПЛОСКОСТЬ» — ВЫИГРЫШ РОВНО НОЛЬ. Мумия УЖЕ пишет
;     ОДНУ плоскость: vns_pbcol даёт ей pbase=0x80 (p0, золото) или 0xC0 (p2, серый),
;     а hi0b (дубль в p2) ставится ТОЛЬКО при pbase=0xA0, hi0c — только слотам 0-3.
;     Замер 8 пирамид: 606 подготовок видимых мумий, ВСЕ «плоскостей=1» (столбцов 2 —
;     75.6%, 3 — 24.4%), обе окраски (ниббл 8/10 -> p0, 4/15 -> p2). Экономии 3200
;     тактов «на мумию» не существует: она была бы при сведении ДВУХ плоскостей в одну,
;     а у мумий двух никогда не бывает. ЦВЕТ ТРОГАТЬ НЕ НАДО: вид мумий не меняется.
;
;  2) ПРЕДСДВИГИ МУМИЙ — НЕ ОКУПАЮТСЯ. Весь сдвиг мумий = 483 такта/кадр (0.8% кадра;
;     6200 тактов на подготовку x 0.078 подготовок/кадр). Предсдвиг снял бы из них
;     ~450. ЦЕНА: 3 паттерна x 2 направления x 7 сдвигов x 48Б = 2016Б ОЗУ (8 сдвигов —
;     2304Б; «4 чётных + досдвиг на 1» — 1152Б, но досдвиг 3-столбцового буфера стоит
;     ~1300 тактов и съедает половину выигрыша). Свободно 147Б в образе + ~985Б в p3 =
;     ~1132Б => не хватает ~884Б РАДИ 0.75% КАДРА. Расчёт на загрузке пирамиды дёшев
;     (3x2x7x6200 = 260 тыс. тактов = 4.3 кадра, идёт под экраном загрузки), но сам
;     выигрыш слишком мал.
;
;  3) ПРЕДСДВИГИ ГЕРОЯ — НЕВОЗМОЖНЫ, И ПО ПАМЯТИ, И ПО ОТЗЫВЧИВОСТИ. Набор героя — 10
;     паттернов (320Б; мумии ещё 3). [АДРЕСА УСТАРЕЛИ с задачи #12, 2026-08-01: и герой, и
;     мумии лежат в ОБРАЗЕ распакованными (src/gen/vec_sprdata.asm), в vec_spr_buf их блоков
;     0..0x19F больше нет. На вывод рассуждения это не влияет — счёт идёт по числу паттернов.]
;     Таблица: 10 x 2 направления x 7 сдвигов x 48Б = 6720Б (со сдвигом 0 — 7680Б);
;     «4 чётных» = 3840Б; «только текущее направление» = 3360Б. Против 1184Б свободных в p3
;     (0xF6A0-0xF83F 416Б + 0xFD00-0xFFFF 768Б, обе зоны подтверждены замером и негативным
;     контролем — см. опись в vec_boot.asm) НЕ ХВАТАЕТ (минимальный разумный вариант). Но даже с памятью вариант мёртв:
;     набор героя перезагружается КАЖДЫМ loadAnimation (подбор ножа/кирки), пересчёт =
;     10x2x7x5545 = 776 тыс. тактов = 13 кадров = 260 мс ЗАМИРАНИЯ в момент подбора,
;     а «только текущее направление» переносит эту паузу на КАЖДЫЙ разворот героя
;     (6.5 кадра). Отзывчивость — приоритет №1, поэтому вариант отвергнут без замера
;     на железе. Кэш «текущий паттерн x 8 сдвигов» (384Б) тоже в минус: паттерн героя
;     меняется чаще, чем повторяется пара (паттерн, сдвиг).
;
;  4) КУДА БИТЬ ДАЛЬШЕ (замерено тем же профилем): 4 отдельных прохода по 21 слоту —
;     флаги Ф, sticky, список видимых, цикл подготовки — стоят 7604 такта/кадр (12.7%)
;     НЕЗАВИСИМО от того, сколько объектов шевельнулось. Это в 1.8 раза больше, чем ВЕСЬ
;     сдвиг спрайтов (4264), и в 15 раз больше, чем всё, что можно снять с мумий.
;     >>> СДЕЛАНО, ЗАДАЧА#36 (2026-07-31), см. vec_sprites.asm. Ключ — не «слить проходы»,
;     а НЕ ХОДИТЬ ВОВСЕ: замер 1192 кадров дал НОЛЬ флагов перерисовки в 71% кадров и
;     взведённый sticky лишь в 0.5%. Три гейта + переписанные обходы:
;       - vfl_any: нет ни одного флага -> список видимых, фаза P и цикл подготовки
;         пропускаются целиком (они и так были no-op'ами);
;       - vfl_dany: слияние sticky идёт только когда vec_su_fixup что-то пометил;
;       - цикл подготовки идёт ПО МАССИВУ ФЛАГОВ (41 такт на пустой слот вместо 136),
;         внешний цикл фазы P держит индекс в регистре D (53 вместо 101),
;         в фазе F случай «оба скрыты» идёт сквозь, без переходов (121 вместо 131).
;     ПРОФИЛЬ (5405 кадров геймплея, тактов/кадр) ДО -> ПОСЛЕ:
;       флаги Ф 2382 -> 2706, sticky 797 -> 59, список видимых 1303 -> 664,
;       распространение П 2478 -> 1235, цикл подготовки 2787 -> 705;
;       собственный код vec_nat_sprites 9746 -> 5369 (-4378 тактов, -45%);
;       halt (простой) 15742 -> 21265. Флаги Ф выросли не из-за кода (он стал дешевле на
;       слот), а потому что укоротившийся тик стал УКЛАДЫВАТЬСЯ В КАДР чаще => игровой тик
;       (а с ним и подготовка) зовётся чаще: кадров с тиком длиннее кадра 47.7% -> 33.5%.
;     ЛУЧ (tools/verify/beam_late.js, 8000 кадров): конец пачки avg 21000 -> 18550 тактов
;       от прерывания; «закончен позже луча» герой 5.6% -> 2.3%, мумии 14.6% -> 4.2%;
