;  ПОЧЕМУ ШЛЕЙФ НЕ ВЕРНЁТСЯ (2026-07-30, проверка на ЖЕЛЕЗЕ — «белое отстаёт от красного»).
;  Шлейф был, когда сейв объекта захватывал в «фон» пиксели УЖЕ НАРИСОВАННОГО соседа.
;  У ГЕРОЯ это принципиально: он состоит из двух спрайтов (слот4 одежда -> p2, слот5 кожа
;  -> p1 и дубль в p2), они стоят В ОДНОЙ ТОЧКЕ и оба пишут p2. ИНВАРИАНТ ФРОНТА: объект
;  E сохраняется позже вывода объекта J, только если на шаге J фронт остановился ПЕРЕД E,
;  то есть lo0(E) <= lo0(J)-16 — их габариты не делят НИ ОДНОЙ строки fb, и сейв E не
;  может снять ни одного нарисованного пикселя J. Пара героя (равные lo0) всегда
;  сохраняется до вывода любого из них: порог lo0-16 строго ниже общего lo0.
;  Гейт: scratchpad/t5/resid.js — (A) fb == независимая модель композиции, (B) сохранённый
;  фон == чистый фон под габаритом. 1500 кадров живой игры: 0 расхождений, 0 бит у героя.
;  vsp_fastmark: можно ли ВСЮ пачку вывести слитой записью? Решает ПОДГОТОВКА (тик), не
;  пачка — под лучом на разбор условий такта нет. Флаг один на пачку: так проверка стоит
;  один проход + попарный обход (объектов единицы), а пачка не тратит ни такта на выбор
;  пути для каждого объекта.
;  ОБЪЕКТ ГОДЕН, если фон под ним УЖЕ лежит в его слоте и покрывает ровно то, куда мы
;  собираемся писать: слот валиден, габарит (hi0, lo0, ncols) НЕ ИЗМЕНИЛСЯ с прошлого
;  кадра, а НАБОР ПЛОСКОСТЕЙ шапки (сейв) СОВПАДАЕТ с набором плоскостей записи вывода.
;  Тогда ни стирать, ни пересохранять фон не нужно: слитая запись сама переводит байт из
;  старого в новое.
;  ШАГ C (2026-08-03): ПЛОСКОСТЕЙ МОЖЕТ БЫТЬ НЕСКОЛЬКО. Раньше здесь стоял отказ на любой
;  hi0b/hi0c, и это была САМАЯ ЧАСТАЯ причина отказа (284 из 492 негодных объектов): все
;  непрозрачные мумии (hi0b и hi0c — две ГАСЯЩИЕ плоскости, ЗАДАЧА#41) и спрайты карты
;  долины. Гашение — та же форма «фон-из-слота OP спрайт», просто OP = AND NOT, и слитая
;  запись умеет её так же (vsn_col). Условие годности прежнее по смыслу: сейв обязан
;  покрывать РОВНО ТЕ плоскости, в которые пишем (+4 == +0x9F и +5 == +0x9B), иначе под
;  какой-то из них в слоте нет фона.
;  ЧЕГО СЛИТАЯ ЗАПИСЬ НЕ УМЕЕТ И ПОСЛЕ ШАГА C: НЕПРОЗРАЧНОГО ГЕРОЯ (vop_i1 != 0). Там кожа
;  гасит СВОЮ плоскость силуэтом СОСЕДА — чужим буфером, которого в слоте нет; это делает
;  только vec_spr_show. Пачка с включённым режимом идёт старым путём целиком, как и до
;  шага C (тогда её отсекал hi0c соседа).
;  ПАРА ОБЪЕКТОВ КОНФЛИКТУЕТ, если делит ПЛОСКОСТЬ и пересекается И по строкам (|dlo0|<16,
;  спрайт 16 строк), И по столбцам: тогда второй композит подставил бы вместо вклада
;  первого свой фон — ровно то, на чём сняли vso_fast. Такая пачка идёт старым путём.
;  Пара героя сюда НЕ попадает: её общая плоскость слита в один буфер (vsd_dropb), после
;  чего слот 4 держит p2, слот 5 — p1, плоскости разные.
;  МНОГОПЛОСКОСТНЫЙ ОБЪЕКТ СРАВНИВАЕТСЯ ТОЛЬКО ПО ГАБАРИТУ (шаг C). Проверка плоскостей
;  смотрит на hi0, то есть на ПЕРВУЮ плоскость; у мумии с hi0b/hi0c конфликт может сидеть
;  во ВТОРОЙ или ТРЕТЬЕЙ (мумия гасит p1, а герой в p1 рисует). Поэтому пара, в которой
;  хоть один многоплоскостный, считается конфликтующей по одному лишь пересечению
;  габаритов. Замер (884 пачки): ЗЕРО потерь — доля слитых пачек с этим ужесточением и
;  без него одна и та же (69.8%), а свои плоскости объекты держат в разных местах экрана.
;  ПОБОЧНО ЭТО ЗАКРЫВАЕТ ЧЕРЕДОВАНИЕ ПАРЫ (vpr_scan/vpr_wr): пара по определению делит
;  область fb, то есть пересекается габаритами, поэтому пачка с многоплоскостной парой
;  сюда просто не проходит, и vpr_wr (он пишет ОДНУ плоскость) многоплоскостного объекта
;  не увидит никогда.
;  vfm_zs: блок фона слота ЦЕЛИКОМ НУЛЕВОЙ? H = страница слота (L любой). Размер блока
;  берётся из ШАПКИ (ncols +3, hi0b +4, hi0c +5) — он описывает то, что реально лежит.
;  Результат в слот +0xD1: 1 = нулевой. Клоб A,B,C,L. Развёрнуто по 4 байта: 12 тактов на
;  байт (то же ядро, что vop_or4 у непрозрачной мумии), 32 байта = ~500 тактов В ТИКЕ.
vfm_zs:
	ld	l, 3
	ld	a, (hl)
	add	a, a
	add	a, a
	ld	c, a	; 4*ncols = четвёрок байт на ОДНУ плоскость
	ld	b, a
	ld	l, 4
	ld	a, (hl)	; hi0b есть -> плоскостей больше
	or	a
	jp	z, vfz_c
	ld	a, b
	add	a, c
	ld	b, a
vfz_c:
	ld	l, 5
	ld	a, (hl)	; hi0c есть -> и ещё одна
	or	a
	jp	z, vfz_go
	ld	a, b
	add	a, c
	ld	b, a
vfz_go:
	ld	l, 6	; данные слота
	xor	a
vfz_l:
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	or	(hl)
	inc	l
	dec	b
	jp	nz, vfz_l
	or	a
	ld	a, 0	; MVI флаги не трогает
	jp	nz, vfz_w
	inc	a
vfz_w:
	ld	l, 0x0D1
	ld	(hl), a
	ret
;  vfm_geo (ФАЗА 4 УНИФИКАЦИИ, 2026-08-06): ОДНА проверка геометрии объекта на два
;  решателя. До этого те же пять условий стояли ДВАЖДЫ — в проходе 1 vsp_fastmark и
;  построчным дублем в хвосте vmx_one (разными регистрами, с разными выходами).
;  ВХОД: H = страница слота (L любой). ВЫХОД:
;    C=1        — объект НЕГОДЕН для слитой записи (A=1), B/D/E/vfm_tn не определены;
;    C=0        — годен; B = hi0, (vfm_tn) = ncols | бит7 «многоплоскостный»,
;                 D = верх объединения габаритов, E = низ+15;
;                 A = бит7 (0 => объект ОДНОПЛОСКОСТНЫЙ, то есть Z=1).
;  Два флага сразу и нужны двум вызывающим: vsp_fastmark берёт `ret c` (многоплоскостные
;  ему годятся, шаг C), а vmx_one — `ret z` (чередование vpr_wr умеет только пару
;  ОДНОПЛОСКОСТНЫХ, и «негоден» с A=1 тоже даёт NZ).
;  Клоб A,D,E,L,B и (vfm_tn). C и H сохраняются — на них стоят петли обоих вызывающих.
vfm_geo:
	ld	l, 0x9F	; ШАГ C: сейв обязан покрывать РОВНО те плоскости, в которые
	ld	a, (hl)	; пишем. hi0b записи == hi0b шапки?
	ld	l, 4
	cp	(hl)
	jp	nz, vfg_bad
	ld	e, a
	ld	l, 0x9B	; hi0c записи == hi0c шапки?
	ld	a, (hl)
	ld	l, 5
	cp	(hl)
	jp	nz, vfg_bad
	or	e	; страницы плоскостей всегда >= 0x80, поэтому старший бит суммы
	and	0x80	; = «объект МНОГОПЛОСКОСТНЫЙ». Пометка едет в кэш вместе с ncols
	ld	d, a	; (D свободен до чтения lo0), а попарная проверка по ней решает,
	;              можно ли верить сравнению плоскостей
;  ЗАДАЧА#53 ОСТАТОК (2026-08-06): ГАБАРИТ МОЖЕТ ПЕРЕЕХАТЬ ПО СТОЛБЦАМ И СМЕНИТЬ ШИРИНУ.
;  Раньше здесь стояло РАВЕНСТВО hi0 и ncols шапки и записи, и это была самая частая
;  причина отказа: 138 отказов из 292 давала «сменился ncols» и 90 — «уехал hi0»
;  (замер fast_why, 762 решения) — вместе 78% всех отказов и 30% всех решений.
;  ЧТО РАЗРЕШЕНО (2026-08-06, ПОКИНУТЫЕ СТОЛБЦЫ): габарит может и сужаться, и уезжать
;  ВПРАВО — фаза 1 закрывает покинутый столбец фоном целиком (см. vsm_p1c). Остались два
;  ограничения, и оба нужны попарной проверке, а не механике переезда:
;    dc <= 1        — вправо ровно один столбец (объект за кадр больше не проезжает:
;                     столбец = 8 пикселей, скорость <= 2 пикс/кадр);
;    dc + dn >= -1  — правый край ушёл влево не больше чем на столбец.
;  ЗАЧЕМ ИМЕННО ЭТИ ДВА: в кэш попарной проверки едет ОДИН диапазон столбцов, а объект
;  занимает объединение старого и нового габаритов (фаза 1 пишет в СТАРЫЙ, фаза 3 читает
;  фон из НОВОГО). При этих двух гейтах объединение целиком лежит в [c_нов-1, c_нов+ncols+1),
;  то есть в «ncols + 2 столбца от левого края объединения» — надмножество считается
;  тремя байтами кода (dec b + add a,2), а точный min/max стоил бы 17.
;  ПРОВЕРКА: dc=1 -> левый край объединения = СТАРЫЙ столбец (dec b), правый = c_ст +
;  max(1+ncols_нов, ncols_ст) <= c_ст + ncols_нов + 2 при dn >= -2; dc<=0 -> левый край
;  новый, правый = c_нов + max(ncols_нов, -dc+ncols_ст) <= c_нов + ncols_нов + 2 при
;  dc+dn >= -2. Оба следуют из гейтов с запасом в один столбец.
;  ПЛОСКОСТЬ ОБЯЗАНА СОВПАСТЬ: фон в слоте лежит под ТОЙ плоскостью, что в шапке. Страницы
;  соседних плоскостей идут подряд (p0 = 0x80+c, p1 = 0xA0+c), поэтому одной арифметики
;  над hi0 мало — сравниваем биты плоскости явно.
;  ПЕРЕЕЗД УМЕЕТ ТОЛЬКО ОДНОПЛОСКОСТНЫЙ ОБЪЕКТ: у многоплоскостного блоки фона в слоте
;  идут подряд по 16*ncols, и смена ширины развела бы их по размеру. Замер geo_probe
;  (задача #53) показал, что горизонтальных случаев у многоплоскостных не бывает вовсе.
	ld	l, 1	; габарит: hi0 шапки против hi0 записи
	ld	e, (hl)
	ld	l, 0x97
	ld	a, (hl)
	ld	b, a	; B = hi0 (плоскость+столбец) — в кэш для попарной проверки
	sub	e
	ld	(vfm_ci), a	; dc (скретч прохода 1: проход 2 vfm_ci переинициализирует)
	jp	z, vfg_dc0
;  ПЛОСКОСТЬ СЧИТАЕМ ДО ПРАВКИ B: hi0_ст = 0x9F (плоскость 0, столбец 31) и hi0_нов = 0xA0
;  (плоскость 1, столбец 0) дают dc = 1, и после `dec b` xor сравнивал бы hi0_ст с самим
;  собой — смена плоскости прошла бы гейт.
	ld	a, b
	xor	e
	and	0x0E0
	jp	nz, vfg_bad	; сменилась ПЛОСКОСТЬ -> фон в слоте не под ней
	ld	a, (vfm_ci)
	or	a
	jp	m, vfg_dc0
	dec	a	; dc > 0: умеем ровно один столбец вправо
	jp	nz, vfg_bad
	dec	b	; и левый край ОБЪЕДИНЕНИЯ габаритов = СТАРЫЙ столбец
vfg_dc0:
	ld	l, 3	; ncols
	ld	e, (hl)
	ld	l, 0x99
	ld	a, (hl)
	sub	e	; dn
	ld	e, a
	ld	a, (vfm_ci)
	or	e	; ни переезда, ни смены ширины -> прежний путь без проверок
	jp	z, vfg_keep
	ld	a, d	; переезд/смену ширины умеет только ОДНОПЛОСКОСТНЫЙ
	or	a
	jp	nz, vfg_bad
	ld	a, (vfm_ci)
	add	a, e
	inc	a	; dc + dn >= -1: правый край ушёл влево не дальше столбца
	jp	m, vfg_bad
	ld	a, (hl)	; ГАБАРИТ ПЕРЕЕХАЛ -> в кэш попарной проверки идёт ОБЪЕДИНЕНИЕ
	add	a, 2	; старого и нового: левый край уже в B, ширина = ncols_нов + 2
	jp	vfg_kw	; (надмножество, доказательство — в шапке выше)
vfg_keep:
	ld	a, (hl)	; ncols ЗАПИСИ (L всё ещё 0x99)
vfg_kw:
	or	d	; ncols + пометка многоплоскостности (старший бит)
	ld	(vfm_tn), a	; ncols — туда же
	ld	l, 2	; lo0: габарит МОЖЕТ уехать по вертикали — слитая запись это умеет
	ld	e, (hl)	; (vsm_shift подвинет фон в слоте), но не дальше 15 строк: при
	ld	l, 0x98	; |d| >= 16 старый и новый габариты не пересекаются вовсе и
	ld	d, (hl)	; сдвигать в слоте нечего
	ld	a, d
	sub	e
	jp	nc, vfm_dp
	cpl
	inc	a
vfm_dp:
	cp	16
	jp	nc, vfg_bad
;  ЦЕНА СДВИГА У МНОГОПЛОСКОСТНОГО ОБЪЕКТА (замер по игровым тикам, 884 пачки, траектория
;  тик-в-тик одна и та же): пачка с многоплоскостным объектом БЕЗ сдвига стоит -6879 тактов
;  (выигрыш), а СО сдвигом +2884 (проигрыш): у гасящей плоскости старый путь — POP-хайджек
;  стирания (17 тактов на байт) + vsb_andn (39) + POP-хайджек сейва (17) = 74, а слитая
;  запись со сдвигом — 51 (запись) + 24 (сдвиг блока фона) + накладные фаз = ~85.
;  СДВИНУТЫЕ ВСЁ РАВНО ПРОПУСКАЕМ: приёмка KV — сначала плавность и фликер, потом такты.
;  Гейт «многоплоскостному только d == 0» стоил бы 9 байт и вернул бы 308 тактов на пачку,
;  но транзиент упал бы с -55% всего до -9% (замерены оба варианта). Если такты когда-то
;  станут дороже фликера — гейт ставится сюда: `or a / jp z / ld a,(vfm_tn) / rla / ret c`.
;  ОБЪЕДИНЕНИЕ СТАРОГО И НОВОГО ГАБАРИТОВ (шаг 4): сдвинутый объект пишет 16+|d| строк —
;  хвост старого габарита плюс весь новый. Попарная проверка сравнивает именно эти
;  диапазоны, иначе сосед по плоскости попал бы под хвост. D = верх, E = низ+15.
	ld	a, d
	cp	e
	jp	c, vfm_sp1	; новый выше старого -> D уже min, max = старый
	ld	d, e
	ld	e, a
vfm_sp1:
	ld	a, e
	add	a, 15
;  ЗАВОРОТ (2026-08-20). Та же мина, что vmx_ovl/vec_su_fixup: при e>=241 сумма
;  переполняется в 0..14, и попарная проверка vsp_fastmark отвечает «строки не
;  пересекаются». Слитая пачка тогда принимает героя (p1) вместе с мумией 7 (p1);
;  vsm_p3 добирает край из fb, где ещё лежит силуэт мумии прошлого кадра, — сейв кожи
;  заражается, и после ухода остаются зелёные точки (mummy_contact_probe MUM=7 JP=8).
;  При переполнении клампим низ в 255: ложное «пересекается» лишь уводит на медленный
;  путь, ложное «не пересекается» портит картинку. +5 Б, 10/17 тактов на объект.
	jp	nc, vfm_spok
	ld	a, 255
vfm_spok:
	ld	e, a
	ld	a, (vfm_tn)	; AND сбрасывает перенос: годен + Z по одноплоскостности
	and	0x80
	ret
vfg_bad:
	ld	a, 1	; NZ для vmx_one, CY для vsp_fastmark
	scf
	ret
;  vop_eff: A != 0 -> паре можно только старый путь (vec_spr_show). Три причины OR-ом:
;  (1) vop_i1 — герой непрозрачен СЕЙЧАС: гасить чужую плоскость умеет только show;
;  (2) hi0c ШАПКИ слота одежды (vsp_dpg) — ПОСЛЕДНИЙ СЕЙВ снят при непрозрачности:
;      p0-блок ещё хранит куски мумии (save пары идёт ПЕРВЫМ, до restore остальных),
;      и слитая запись/микс вынесли бы их в кадр «полоской»;
;  (3) [2026-08-18] БЛОК ФОНА ПАРЫ НЕПУСТ (ZFLAG слота 4 или 5 = 0): слитая запись
;      пишет «фон|спрайт» и не гасит p1 силуэтом одежды. Пока фон пуст (замер
;      su_empty_census: 100% геймплея) — разницы нет, но у ворот входа тайлы двери
;      ложатся ПОВЕРХ героя, vec_su_fixup кладёт створку в блок, и fast/микс рисовали
;      «створка|одежда» = p1+p2 = КРАСНЫЕ ТОЧКИ на створке (жалоба с железа).
;      ZFLAG'и считает vsp_fastmark в этом же тике для объектов списка; у стоящей вне
;      списка пары они замирают вместе с блоком — протухнуть врозь не могут.
;  Старый путь пересейвит пару и обнулит hi0c; ZFLAG отпустит, когда фон снова пуст.
;  Клоб C,H,L; флаги от финального OR (обе точки вызова зовут его до занятия C).
vop_eff:
	ld	a, (vec_spr_save+0x4D1)	; ZFLAG слота 4 (одежда)
	ld	hl, vec_spr_save+0x5D1	; ZFLAG слота 5 (кожа)
	and	(hl)
	dec	a	; оба блока пусты (1&1) -> 0; любой непуст -> 0xFF
	ld	c, a
	ld	a, (vsp_dpg)
	ld	h, a
	ld	l, 5
	ld	a, (vop_i1)
	or	(hl)
	or	c
	ret
vsp_fastmark:
	xor	a
	ld	(vsp_fast), a
;  Гейт vop_eff стоит НЕ здесь, а ПОСЛЕ прохода 1 (см. ниже): его часть (3) читает
;  ZFLAG'и пары, а их пересчитывает vfm_zs именно в проходе 1 — здесь они ещё вчерашние
;  (vec_su_save каждой пачки снимает флаг), и гейт душил бы fast-путь НАВСЕГДА.
	ld	a, (vsp_n)
	or	a
	ret	z
	cp	8	; кэш геометрии на 7 объектов; больше — пачка идёт старым путём
	ret	nc	; (за все замеры в пачке максимум 4 объекта)
	add	a, a
	add	a, a
	ld	(vfm_n4), a	; конец кэша = 4*n
	ld	c, 0	; --- проход 1: годен ли КАЖДЫЙ ---
vfm_a:
	ld	a, c	; ИНЛАЙН vso_setidx+vec_su_ptr: страница слота прямо из списка
	add	a, vsp_list&255	; (проход горячий — после шага 4 он идёт до конца почти
	ld	l, a	; всегда, а vec_nsp_idx здесь никому не нужен)
	ld	h, 255&(vsp_list>>8)
	ld	a, (hl)
	add	a, 0x0E0
	ld	h, a
	ld	l, 0	; слот валиден?
	ld	a, (hl)
	dec	a
	ret	nz
	ld	l, 0x96	; pending=1 (не скрыт, не дедуплен)?
	ld	a, (hl)
	dec	a
	ret	nz
;  ЗАДАЧА#49 (2026-08-04): ПУСТОЙ ФОН. Здесь, В ТИКЕ, доказывается «блок фона слота
;  ЦЕЛИКОМ НУЛЕВОЙ» — прямым OR всего блока (12 тактов на байт). Замер su_empty_census.js
;  (6000 кадров геймплея): у героя 758/772, у мумий 228/228 — спрайт ровно в рост коридора,
;  кирпичи лежат СТРОГО вне габарита. Что это даёт под лучом, см. vso_merge1 и vsz_mcol.
;  ПОЧЕМУ ИМЕННО ЗДЕСЬ, А НЕ В СЕЙВЕ. Первая редакция копила OR прямо в POP-хайджеке
;  vec_su_save (там байты и так читаются, +4 такта на байт). Замер beam_ab по игровым
;  тикам показал ЦЕНУ: сейв идёт МЕЖДУ проходом стирания и выводом, то есть удлиняет окно
;  «объект разобран» КАЖДОМУ объекту старого пути — транзиент 13368 -> 16224 пикс при
;  выигрыше только на слитом пути. Здесь проход стоит те же байты, но В ТИКЕ, и старый
;  путь остаётся байт-в-байт прежним.
;  ПРОТУХНУТЬ ФЛАГ НЕ МОЖЕТ: читает его только слитая запись, а она идёт лишь тогда, когда
;  ВСЕ объекты пачки прошли этот проход в ЭТОМ тике (vsp_fast ставится в самом конце).
;  Единственный писатель блока между тиком и пачкой — vec_su_fixup, он закрыт гейтом
;  vfl_dany в vso_merge1.
;  ДОКАЗАННОЕ НЕ ПЕРЕДОКАЗЫВАЕМ: ZFLAG=1 держится сам собой, пока блок никто не трогал.
;  Писателей блока ровно три, и каждый флаг снимает: vec_su_save (положил свежий фон),
;  vsm_p3 (добор края притащил ненулевые байты) и слияние sticky (vec_su_fixup переписал
;  клетку). Поэтому проход нужен только после одного из этих событий, а в установившемся
;  движении — ноль тактов. Замер beam_ab: безусловный проход стоил +0.5% кадров на игру.
	ld	l, 0x0D1
	ld	a, (hl)
	dec	a
	jp	z, vfm_zok
	push	bc	; C = индекс в списке вывода
	call	vfm_zs
	pop	bc
vfm_zok:
	call	vfm_geo	; ФАЗА 4: общая с vmx_one проверка геометрии объекта
	ret	c	; C = объект негоден -> вся пачка старым путём
	ld	a, c	; --- геометрию в кэш: [hi0, ncols, верх, низ] ---
	add	a, a
	add	a, a
	add	a, vfm_arr&255
	ld	l, a
	ld	h, 255&(vfm_arr>>8)
	ld	(hl), b
	inc	l
	ld	a, (vfm_tn)
	ld	(hl), a
	inc	l
	ld	(hl), d
	inc	l
	ld	(hl), e
	inc	c
	ld	a, c
	ld	hl, vsp_n
	cp	(hl)
	jp	c, vfm_a
;  ===== ЭКСПЕРИМЕНТ «КОМПОЗИТ25», ЭТАП 1 (2026-09-11): vop_eff БОЛЬШЕ НЕ ВЕТИРУЕТ ПАЧКУ
;  БЫЛО: `call vop_eff / ret nz` — «гасить силуэтом умеет только vec_spr_show, значит вся
;  пачка старым путём». Гейт про ПАРУ ГЕРОЯ, а платили им ВСЕ объекты пачки, и прежде
;  всего МУМИИ: у них слитая запись (vso_merge1 + vsm_multi/vsn_col) даёт ровно одну
;  запись на байт и существует в этой линии с августа — но она ПАЧЕЧНАЯ, всё или ничего.
;  ЗАМЕР (tools/verify/mummy_merge_why.js, сцена walk, 400 тиков, мумии живые):
;    кратность записи на байт МУМИИ 1.00 в слитых пачках против 2.44 в обычных;
;    слитыми оказываются лишь 3.8% пачек с мумиями, решений vsp_fastmark «разрешено» 15.6%;
;    65.1% ВСЕХ отказов — ровно этот `ret nz`.
;  ЗОНД (NOVOPEFF=1 в том же стенде — vop_eff приколочен к нулю прямо в образе): решений
;  «разрешено» 60.9%, кратность на байте мумии 2.42 -> 1.72. То есть veto пары и есть
;  главный держатель мерцания мумий, а не механика записи.
;  СТАЛО: пара выводится ТЕМ ЖЕ СТАРЫМ МЕХАНИЗМОМ (restore -> save -> show), но ВНУТРИ
;  слитой пачки и ЦЕЛИКОМ В ЕЁ НАЧАЛЕ — vpr_fs2, то есть vpr_sout + vpr_ssd, те самые две
;  фазы, которыми slow-пара уже ходит в обычной пачке (задача#53, 2026-08-18). Ни одной
;  новой формы вывода героя не заведено: меняется только то, КТО ещё едет в этой пачке.
;  ПОЧЕМУ ЗАКОННО: попарная проверка прохода 2 (ниже) доказывает, что ОБЪЕДИНЁННЫЙ габарит
;  каждого объекта (старый И новый, все плоскости) не пересекается ни с чьим. Значит под
;  парой в момент её save лежит её собственный чистый фон, а слитые соседи в её байты не
;  пишут — это ровно то же доказательство, что у микса и у slow-пары.
;  РЕАЛИЗАЦИЯ БЕЗ ЯЧЕЙКИ: адрес писателя пары кладётся ОПЕРАНДОМ в `call` внутри
;  vso_fastall (vfa_cp). Протухнуть не может: vsp_fastmark зовётся в ТОМ ЖЕ тике, что и
;  vpr_scan, ровно перед vsp_rdy=1, а при выходе ДО этой точки vsp_fast=0 и vso_fastall
;  не исполняется вовсе.
;  Стоит ПОСЛЕ прохода 1: ZFLAG'и пары уже пересчитаны vfm_zs.
	call	vop_eff	; непрозрачный герой / грязный сейв / непустой фон пары
	ld	hl, vmxp	; 0 -> паре можно слитую запись (прежний путь, микс-писатель)
	jp	z, vfm_pw
	ld	hl, vbw_fs2	; иначе -> пара старым путём, первой в слитой пачке (apex-fast: сначала BEAMW пары, vec_bw.asm)
vfm_pw:
	ld	(vfa_cp+1), hl
;  --- проход 2: попарные конфликты. Идёт ПО КЭШУ vfm_arr (4 байта на объект, заполнен
;  проходом 1), а не по слотам: ни vso_setidx, ни vec_su_ptr, ни чтений записи вывода.
;  Замер профиля: пачек, доходящих до этого прохода, стало вчетверо больше (шаг 4 снял
;  ограничение на lo0), и прежний вариант с обходом слотов стоил 1273 такта на кадр.
	ld	c, 0	; C = 4*i (смещение записи первого в кэше)
vfm_i:
	ld	a, c
	add	a, 4
	ld	(vfm_j), a	; 4*j
	ld	h, 255&(vfm_arr>>8)
	ld	a, c
	add	a, vfm_arr&255
	ld	l, a
	ld	a, (hl)	; hi0 первого
	ld	(vfm_hi), a
	and	0x1F
	ld	(vfm_ci), a	; столбец первого
	inc	l
	ld	a, (hl)
	ld	(vfm_nc), a
	inc	l
	ld	a, (hl)
	ld	(vfm_lo), a	; верх объединения габаритов первого
	inc	l
	ld	a, (hl)
	ld	(vfm_lh), a	; низ
vfm_j2:
	ld	a, (vfm_j)
	ld	hl, vfm_n4
	cp	(hl)
	jp	nc, vfm_inext
	ld	h, 255&(vfm_arr>>8)
	add	a, vfm_arr&255
	ld	l, a
	ld	a, (hl)
	ld	e, a	; E = hi0 второго
	inc	l
	ld	d, (hl)	; D = ncols второго (старший бит = многоплоскостный)
;  ШАГ C: сравнение плоскостей смотрит ТОЛЬКО на hi0. Если хоть один из пары держит ещё
;  hi0b/hi0c, конфликт может сидеть в них — тогда решаем по одному пересечению габаритов.
;  Пометка едет В СТАРШЕМ БИТЕ кэшированного ncols, поэтому она же сама делает сравнение
;  столбцов ниже консервативным (c+ncols уезжает за 0x80 и «не пересекаются» не срабатывает)
;  — маскировать её не нужно. Замер: 613 слитых пачек против 617 у точной проверки.
	ld	a, (vfm_nc)
	or	d
	rla
	jp	c, vfm_r0
	ld	a, (vfm_hi)
	xor	e
	and	0x0E0	; разные плоскости, оба одноплоскостные -> конфликта нет
	jp	nz, vfm_jnext
vfm_r0:
	inc	l
	ld	a, (vfm_lh)	; низ первого ВЫШЕ верха второго -> по строкам не пересекаются
	cp	(hl)
	jp	c, vfm_jnext
	inc	l
	ld	a, (vfm_lo)	; верх первого НИЖЕ низа второго -> тоже нет
	cp	(hl)
	jp	z, vfm_r1
	jp	nc, vfm_jnext
vfm_r1:
	ld	a, e	; столбец второго
	and	0x1F
	ld	e, a
	add	a, d	; c1 >= c2+nc2 -> не пересекаются
	ld	d, a
	ld	a, (vfm_ci)
	cp	d
	jp	nc, vfm_jnext
	ld	a, (vfm_ci)	; c2 >= c1+nc1 -> не пересекаются
	ld	d, a
	ld	a, (vfm_nc)
	add	a, d
	ld	d, a
	ld	a, e
	cp	d
	jp	nc, vfm_jnext
;  ===== [КОМПОЗИТ25 2026-09-11] ИСКЛЮЧЕНИЕ: ДВЕ ПОЛОВИНЫ ГЕРОЯ — НЕ КОНФЛИКТ ==========
;  ЗАЧЕМ. Слоты 4 (одежда) и 5 (кожа) занимают ОДНУ И ТУ ЖЕ область fb в разных
;  плоскостях — это и есть пара. Сравнение плоскостей выше их разводит, ПОКА ОБА
;  одноплоскостные; но как только герой непрозрачен, слот 4 берёт ещё и hi0c (гасит p0),
;  становится многоплоскостным, и проверка честно уходит на консервативный путь «решаем
;  по пересечению габаритов» — то есть объявляет конфликт ПАРЫ С САМОЙ СОБОЙ и валит
;  пачку. Замер зондом NOVOPEFF: после снятия veto vop_eff ровно этот `ret` стал главным
;  отказом — 24.9% решений.
;  ПОЧЕМУ ЗАКОННО. Пара НИКОГДА не едет через слитую запись как два независимых объекта:
;  её позиции в пачке обрабатывает ОДИН писатель (vfa_cp -> vmxp либо vpr_fs2), а общий
;  цикл обе позиции пропускает (vpr_at). Делить байты половинам героя положено — обе
;  формы вывода пары это умеют и на этом построены.
;  ПРОВЕРКА УЗКАЯ — ИМЕННО СЛОТЫ 4 И 5, а не «похожая геометрия»: широкий геометрический
;  признак совпал бы с признаком vpr_scan лишь приблизительно, и объект, который vpr_scan
;  парой НЕ признал, поехал бы слитой записью поверх соседа. Слот берём из vsp_list по
;  позиции: C = 4*i, (vfm_j) = 4*j (оба строятся сложением четвёрок от нуля, старшие биты
;  заведомо нулевые — поэтому два rrca дают индекс без маски).
	ld	a, c
	rrca
	rrca
	call	vfm_sl	; A = слот позиции i
	cp	4
	ret	c	; не герой -> конфликт настоящий
	cp	6
	ret	nc
	ld	a, (vfm_j)
	rrca
	rrca
	call	vfm_sl	; A = слот позиции j
	cp	4
	ret	c
	cp	6
	ret	nc
	jp	vfm_jnext	; обе половины героя — пропускаем, это не конфликт
vfm_sl:
	add	a, vsp_list&255
	ld	l, a
	ld	h, 255&(vsp_list>>8)
	ld	a, (hl)
	ret
vfm_jnext:
	ld	a, (vfm_j)
	add	a, 4
	ld	(vfm_j), a
	jp	vfm_j2
vfm_inext:
	ld	a, c	; следующая запись кэша (шаг 4 байта)
	add	a, 4
	ld	c, a
	ld	hl, vfm_n4
	cp	(hl)
	jp	c, vfm_i
	ld	a, 1
	ld	(vsp_fast), a
	ret
vec_spr_out:
;  ЗАДАЧА#53: список берём, ТОЛЬКО если подготовка его достроила (vsp_rdy). Пачка теперь
;  зовётся и с вложенного прерывания, то есть посреди тика; ЗАБИРАЕМ список сразу (флаг
;  вниз), чтобы вывести его ровно один раз.
	ld	a, (vsp_rdy)
	cp	1	; 2 = список ещё СТРОИТСЯ (см. vflp_done): забирать нельзя
	ret	nz
	xor	a
	ld	(vsp_rdy), a
	ld	a, (vsp_n)	; ничего не подготовлено -> делать нечего
	or	a
	ret	z
	ld	(vso_i), a
	ld	hl, VBW_S1	; BEAMW: программный счёт времени от запроса IRQ стартует с пачкой
	ld	a, (vec_isr_depth)
	dec	a
	jp	z, vso_bs
	ld	hl, VBW_S2
vso_bs:
	ld	(vbw_s), hl
;  СЛИТАЯ ЗАПИСЬ ВСЕЙ ПАЧКИ (задача #37): ни прохода стирания, ни фронта сейвов —
;  каждый объект переписывает свой габарит готовым «фон OR спрайт» за одну запись на байт.
	ld	a, (vsp_fast)
	or	a
	jp	nz, vso_fastall
	call	vbw_pf	; BEAMW: ВСЕ ожидания луча — здесь, пока ничего не стёрто (см. vec_bw.asm); пара не LAST — первой, до чужих ожиданий
;  МИКС (задача#50): пара — ПЕРВОЙ, ДО стираний. Её байты не пересекаются ни с чьими
;  (это проверил vmx_check), поэтому место в пачке — вопрос только ЛУЧА: чем раньше
;  дописана пара, тем меньше окно, в котором луч может застать пиксель героя с одной
;  записанной плоскостью. Начало пачки — самый ранний из возможных моментов.
	ld	a, (vpr_mix)
	cp	0x0FE
	jp	z, vso_rloop
	ld	a, (vpr_sl)	; ЗАДАЧА#53: пара НЕ годна для слитой записи (непрозрачный
	or	a	; герой, разошедшийся hi0b, переехавший габарит) — стираем её
	jp	z, vpr_smx	; ПЕРВОЙ, save+show после общего стирания (vpr_ssd)
;  [2026-08-18 ОТКАТ ЭКСПЕРИМЕНТА «slow-пара в общий поток»] Полный инвариант фронта
;  (vpr_mix=0xFE) A/B-метрикам нравился, но НА ЖЕЛЕЗЕ герой мерцал ЗАМЕТНО СИЛЬНЕЕ
;  (вердикт владельца; глаз — финальный судья приёмки), а мусор при перепрыгивании
;  мумий НЕ ушёл — заражение сейвов не было его причиной. Вывод пары пачкой полезен —
;  оставлена двухфазная форма: стереть первой, save+show после vso_rloop.
	jp	vpr_s2x	; right-half: развилка LAST / не LAST — в vec_bw.asm (за .align), A = vpr_sl
vpr_smx:
	call	vmx_pair
;  ПОРЯДОК СТИРАНИЯ = ОБРАТНЫЙ ПОРЯДОК ВЫВОДА (ЗАДАЧА#50, 2026-08-04). Раньше стирание шло
;  по списку ПОДГОТОВКИ с конца, то есть герой (слоты 4-5, голова списка) стирался почти
;  ПЕРВЫМ, а рисовался в верхних строках — ПЕРВЫМ по ходу луча. Между этими точками лежала
;  вся остальная пачка: дыра стирания героя avg 12741 тактов (замер hero_atomic.js), и луч
;  успевал пройти по СТЁРТОМУ герою — то самое «мерцание вверху» с железа.
;  ТЕПЕРЬ стирание идёт по vso_ord С КОНЦА: НИЖНИЕ объекты стираются первыми (луч дойдёт
;  до них нескоро), ВЕРХНИЕ — последними, впритык к своему сейву и выводу. Дыра каждого
;  объекта сжимается тем сильнее, чем он выше, то есть чем раньше над ним луч.
;  ПОЧЕМУ ПЕРЕСТАНОВКА БЕЗОПАСНА: стирания КОММУТИРУЮТ. Если сохранённые области двух
;  объектов пересекаются, оба сейва сняты ДО вывода любого из них (инвариант фронта, см.
;  выше), значит в пересечении оба слота держат ОДИН И ТОТ ЖЕ чистый фон — порядок записи
;  не меняет итога. Цена: ноль байт (vso_setord вместо vso_setidx).
vso_rloop:	; --- проход 1: стирание, по порядку вывода С КОНЦА (снизу вверх) ---
	ld	a, (vso_i)
	dec	a
	ld	(vso_i), a
	ld	hl, vpr_mix	; МИКС (задача#50): пару не стираем — она выводится слитой
	sub	(hl)	; записью, дыры стирания у неё нет по построению
	cp	2
	jp	c, vso_rskip
	ld	a, (vso_i)
	call	vso_setord
	call	vso_static	; неподвижная створка стирания не требует (см. выше)
	or	a
	jp	nz, vso_rskip
	call	vec_su_restore
vso_rskip:
	ld	a, (vso_i)
	or	a
	jp	nz, vso_rloop
;  [2026-08-18] ФАЗА 2 slow-пары: фон уже чист (все restore прошли) — save+show.
;  Гейт vpr_mix обязателен: при 0xFE (пары нет) vpr_sl протухший, а vps_two по
;  vpr_mix=0xFE ушёл бы в ord[254]. См. разбор у vpr_sout.
	ld	a, (vpr_mix)
	cp	0x0FE
	jp	z, vso_nps
	ld	a, (vpr_sl)
	or	a
	call	nz, vpr_ssd
vso_nps:
	xor	a
	ld	(vso_e), a	; A=0 после петли стирания: фронт сейвов (и vso_i уже 0)
;  ЗАДАЧА#37: сортировка порядка вывода отсюда УБРАНА — её делает ПОДГОТОВКА, в тике
;  (хвост vec_nat_sprites). Здесь она стоила 2496 тактов в длинных пачках и задерживала
;  ВСЕ выводы, в том числе самого ВЕРХНЕГО объекта — того, над которым луч проходит
;  первым. Данные (lo0 в записях вывода) готовы уже к концу подготовки, так что перенос
;  ничего не меняет по смыслу и не добавляет работы: она просто ушла из-под луча.
vso_dloop:
	ld	a, (vso_i)	; МИКС (задача#50): пара уже выведена В НАЧАЛЕ пачки —
	ld	hl, vpr_mix	; пропустить обе её позиции; фронт сейвов не трогаем,
	cp	(hl)	; соседи пары продвинут его своими порогами
	jp	nz, vso_nmx
	inc	a
	ld	(vso_i), a
	jp	vso_adv
vso_nmx:
	ld	a, (vso_e)	; фронт дошёл до конца списка -> сохранять некого и порог
	ld	hl, vsp_n	; считать незачем: сразу вывод
	cp	(hl)
	jp	nc, vso_sdone
	ld	a, (vso_i)	; порог: кто НЕ ниже lo0(выводимого)-16, тот может с ним
	call	vso_setord	; пересечься по вертикали (спрайт высотой 16 строк)
	call	vso_lo
	sub	16
	jp	nc, vso_thok
	xor	a	; страховка от заёма (у скрытого объекта lo0 протухший)
vso_thok:
	ld	(vso_th), a
vso_sloop:	; --- догнать фронт сейвов: сохранить фон всем, кто пересекается ---
	ld	a, (vso_e)	; (что фронт внутри списка, уже проверено)
	add	a, vso_ord&255	; ИНЛАЙН vso_setord+vso_lo (петля горячая, идёт под лучом):
	ld	l, a	; A = lo0(ord[e]), заодно vec_nsp_idx = ord[e] для сейва
	ld	h, 255&(vso_ord>>8)
	ld	a, (hl)
	ld	(vec_nsp_idx), a
	add	a, 0x0E0
	ld	h, a
	ld	l, 0x98
	ld	e, (hl)
	ld	a, (vso_th)
	cp	e	; порог >= lo0 -> не пересекается, сохраним у СВОЕГО объекта
	jp	nc, vso_sdone
	ld	a, (vso_e)	; МИКС (задача#50): паре фон НЕ пересохранять. ОБЯЗАТЕЛЬНО:
	ld	hl, vpr_mix	; fb под ней не стёрт, и сейв снял бы САМОГО героя как «фон»
	sub	(hl)	; (шлейф). Чистый фон пары уже лежит в её слотах.
	cp	2
	jp	c, vso_ssk
	call	vso_static	; неподвижной створке пересохранять фон не надо (см. vso_static)
	or	a
	jp	nz, vso_ssk
	call	vec_su_save
vso_ssk:
	ld	a, (vso_e)
	inc	a
	ld	(vso_e), a
	ld	hl, vsp_n
	cp	(hl)
	jp	c, vso_sloop	; фронт ещё внутри списка — проверить следующего
vso_sdone:	; --- вывод объекта: фон под ним и под всеми соседями уже снят ---
	ld	a, (vso_i)
	call	vso_setord
	call	vec_su_ptr	; pending=2 (объект скрыт) -> выводить НЕЧЕГО: шапка слота
	ld	l, 0x96	; уже невалидна, а её старые hi0/ncols увели бы вывод
	ld	a, (hl)	; куда попало (ncols=0 у чистого слота = 256 столбцов!)
	cp	2
	jp	z, vso_noshow
	call	vec_spr_show
vso_noshow:
	call	vso_prev	; снапшот prev = то, что реально выведено
vso_adv:
	ld	a, (vso_i)
	inc	a
	ld	(vso_i), a
	ld	hl, vsp_n
	cp	(hl)
	jp	c, vso_dloop
	ld	(hl), 0	; список израсходован
;  [2026-09-19] ПАРА ПОСЛЕДНЕЙ на пересечении с мумией (vpr_sl=2). Стирание и сейв
;  пары уже прошли (vpr_sout / vpr_ssd без show), мумии нарисованы. Героя кладём
;  сверху одной записью на плоскость (vop_ow). vtm_hrd не зовём. Под створкой не рисуем.
;  [2026-09-27] отложенный restore+save до vop_ow ОТКАТАН: сейв мумии снимал героя
;  с fb → two_mum_jump_resid / hero_width / opaque_composite красные.
	ld	a, (vpr_sl)
	cp	2
	jp	nz, vtm_hrd
	ld	e, 0
	ld	a, 4
	call	vhr_ovl
	ret	nz
	call	vop_ow
	ld	hl, vso_prev
	jp	vps_two
;  vso_fastall: пачка целиком слитой записью. Порядок — тот же, что у обычного пути
;  (сверху вниз, по ходу луча), хотя корректность его уже не требует: объекты этой пачки
;  попарно не делят ни одного байта fb (проверено в vsp_fastmark).
;  ===== ЧЕРЕДОВАНИЕ ПАРЫ ПО СТОЛБЦАМ (ЗАДАЧА#38, 2026-08-02) ========================
;  ДЕФЕКТ С ЖЕЛЕЗА: «у героя лицо подмаргивает бело-красным — на мгновение белое, потом
;  как надо красное». Цвет пикселя на Векторе — КОМБИНАЦИЯ битов p0/p1/p2, а герой пишется
;  ДВУМЯ объектами: после дедупа слот 5 держит p1 (кожа), слот 4 — p2 (одежда). Каждый байт
;  пишется один раз и правильным значением (байтовые метрики beam_tear/beam_late молчат),
;  но МЕЖДУ записью p1 и записью p2 одного и того же пикселя луч видит цвет, которого нет
;  ни в старом кадре, ни в новом.
;  ЗАМЕР (tools/verify/beam_color.js, 2600 тиков): окно между плоскостями avg 7360 / p50
;  5916 / p90 14724 / max 22000 тактов = 31..115 строк луча. Атрибуция по PC: 18576 окон из
;  28201 (66%) — это vsb_merge -> vsb_merge, то есть слитая запись пары ЗДЕСЬ: между
;  столбцами объекта A и столбцами объекта B лежала ВСЯ обработка B (сдвиг фона в слоте,
;  добор края) плюс остаток записи A.
;  ЧТО СДЕЛАНО: если два соседних объекта пачки пишут ОДНУ И ТУ ЖЕ область fb в РАЗНЫХ
;  плоскостях (равные lo0 и ncols, равный столбец, разные биты плоскости — это ровно пара
;  героя), их подготовка (vsm_shift) выполняется для ОБОИХ, а запись идёт ЧЕРЕДУЯСЬ ПО
;  СТОЛБЦАМ: A.столбец0, B.столбец0, A.столбец1, B.столбец1, ... Окно между плоскостями
;  одного пикселя схлопывается до ОДНОГО столбца (16 байт x 48 тактов = 768 тактов, 4
;  строки луча) независимо от того, сколько столбцов у объекта.
;  ПОЧЕМУ ЭТО БЕЗОПАСНО: объекты пачки слитой записи попарно НЕ ДЕЛЯТ НИ ОДНОГО байта fb
;  (это уже проверил vsp_fastmark), поэтому порядок записей между объектами не значит
;  ничего — каждый байт по-прежнему пишется ровно один раз и сразу окончательным значением.
;  Порядок фаз ВНУТРИ объекта (хвост -> сдвиг -> край -> запись) сохранён.
;  ПОБОЧНЫЙ ВЫИГРЫШ: хвосты старых габаритов (vsm_p1r, |d| строк, которые объект покинул)
;  тоже сближаются — между ними остаётся лишь сдвиг+край одного объекта, а не вся запись.
;  ЦЕНА: указатели столбца перезагружаются из ОЗУ на каждый столбец каждого объекта, а не
;  идут через inc — см. vpr_wr.
vso_fastall:
;  === ГЕЙТ FIXUP ОБЯЗАН БЫТЬ ВЗВЕДЁН И НА СЛИТОМ ПУТИ (жалоба с железа, 2026-08-04) =====
;  vec_su_fixup выходит на первой инструкции, если vsu_any=0 («валидных слотов нет»).
;  Взводил его ТОЛЬКО vec_su_save — а слитая запись фон не пересохраняет и save не зовёт.
;  Итог: как только пачка целиком уходила слитым путём (после шага C это 69% пачек),
;  vsu_any оставался нулём, и ЛЮБОЙ блит клетки под живым спрайтом переставал (1) освежать
;  сохранённый в слоте фон и (2) взводить sticky vfl_dirty, то есть спрайт больше не
;  перерисовывался. Слитая запись при этом СОСТАВЛЯЕТ кадр из этого самого сохранённого
;  фона — она зависит от fixup сильнее, чем медленный путь.
;  КАК ЭТО ВЫГЛЯДЕЛО: вход в пирамиду 1, анимация закрытия ворот блитит свои 15 клеток
;  под неподвижными створками. Замер: 534 блита в столбцы створок, ВСЕ при vsu_any=0,
;  вывод створок 8 раз за 200 кадров -> тайлы ворот затирали створку, и на её месте
;  оставался кирпич В ТОН КАМНЯ (золото на 1-й пирамиде) вместо зелёной створки.
;  Слоты здесь ЗАВЕДОМО валидны: пачка непуста, а её объекты прошли save в тот кадр,
;  когда появились. Ставим флаг один раз на пачку — 18 тактов.
	ld	a, 1
	ld	(vsu_any), a
	xor	a
	ld	(vso_i), a
	ld	(vpr_def), a	; писать сразу — пока не готовим пару
;  ПАРА — ПЕРВОЙ (задача#50). Объекты слитой пачки попарно не делят ни байта fb (это
;  проверил vsp_fastmark), поэтому порядок вывода между ними — вопрос только ЛУЧА.
;  Пара героя — единственный объект, чей ПИКСЕЛЬ собирается ДВУМЯ записями (p1+p2), и
;  только у неё есть межплоскостное окно; выводим её раньше всех, пока луч не дошёл.
;  Остальные пишут байт одним значением: луч до записи видит СТАРЫЙ кадр (лаг), не мусор.
	ld	a, (vpr_at)
	inc	a	; 0xFF+1=0 -> пары нет
	jp	z, vfa_l
	dec	a
	ld	(vmx_w), a	; общий писатель vmxp (задача#50 делит его с миксом)
	ld	(vpr_mix), a	; [КОМПОЗИТ25] vpr_sout/vpr_ssd адресуют пару через vpr_mix
;  ОПЕРАНД (см. разбор у vop_eff в vsp_fastmark): vmxp — пара слитой записью, vpr_fs2 —
;  пара старым путём (restore -> save -> show) целиком в начале СЛИТОЙ пачки.
vfa_cp:
	call	vmxp
vfa_l:
	ld	a, (vso_i)	; позиция пары найдена ещё в тике (vpr_scan)
	ld	hl, vpr_at
	cp	(hl)
	jp	nz, vfa_one
	inc	a	; пара выведена до цикла — пропустить обе позиции
	ld	(vso_i), a
	jp	vfa_next
vfa_one:
	ld	a, (vso_i)
	call	vso_setord
	call	vso_merge1
	call	vso_prev	; снапшот = то, что реально выведено (как в обычном пути)
vfa_next:
	ld	a, (vso_i)
	inc	a
	ld	(vso_i), a
	ld	hl, vsp_n
	cp	(hl)
	jp	c, vfa_l
	ld	(hl), 0	; список израсходован
	ret
;  ===== ПАРА ПЕРВОЙ ОБЫЧНЫМ МЕХАНИЗМОМ (ЗАДАЧА#53, 2026-08-06) =======================
;  ЗАЧЕМ. Транзиент («луч прошёл над объектом между стиранием и выводом») у ГЕРОЯ бывает
;  только на медленном пути: restore пары идёт в общем проходе стирания, а её show — после
;  того, как фронт сейвов догонит её позицию. Между этими точками лежат стирания всех, кто
;  ниже, и сейвы всех, кто пересекается: замер атрибуции — 2776 из 2968 пикселей транзиента
;  дали пачки, где сама пара выводиться слитой записью НЕ МОГЛА (vop_i1 или hi0b).
;  ЧТО ДЕЛАЕМ. Ровно то же, что микс, но обычным механизмом и целиком в начале пачки:
;    restore(a), restore(b) -> save(a), save(b) -> show(a), show(b).
;  Окно «пара разобрана» схлопывается до двух сейвов вместо всей пачки.
;  ПОЧЕМУ ЭТО ЗАКОННО — то же доказательство, что у микса: vmx_check уже доказал, что
;  ОБЪЕДИНЁННЫЙ габарит пары (строки И столбцы, шапки И записи) не пересекается НИ С ЧЬИМ
;  габаритом в пачке. Значит: (1) под парой в этот момент лежит чистый фон (её собственный
;  restore только что его вернул, а чужого рисунка там нет), поэтому save снимает именно
;  фон, а не соседа; (2) ничьё последующее стирание, сохранение или вывод в байты пары не
;  попадает. Позиции пары в общих проходах пропускаются ТЕМ ЖЕ гейтом vpr_mix, что и у
;  микса, — стирания/сейва/вывода второй раз не будет.
;  ОБА СЕЙВА ДО ОБОИХ ВЫВОДОВ: объекты пары стоят в одной точке, и сейв второго снял бы
;  первого как «фон» (это и есть шлейф, из-за которого сняли старый быстрый путь).
;  [2026-08-18] vpr_sout РАЗРЕЗАН НА ДВЕ ФАЗЫ. Раньше он делал restore+save+show пары
;  ЦЕЛИКОМ ДО общего прохода стирания, и save пары снимал fb, где мумии ЕЩЁ НАРИСОВАНЫ
;  (их restore идёт позже, в vso_rloop): p0-блок одежды (hi0c) уносил КУСКИ МУМИИ, и
;  каждый следующий restore пары выплёвывал их «фоном» — при прыжке через мумию её
;  restore затирал призрак не целиком (сдвиг габарита), оставалась ЖЁЛТАЯ ПОЛОСА
;  (жалоба с железа; hide-метрика herojump_top_probe: 19-27 p0-орфанов).
;  ТЕПЕРЬ: фаза 1 (vpr_sout) — только СТЕРЕТЬ пару, по-прежнему первой в пачке;
;  фаза 2 (vpr_ssd, зовётся ПОСЛЕ vso_rloop) — save с уже ЧИСТОГО фона + show.
;  Инвариант фронта для сейва пары восстановлен; цена лучу — show пары уехал за
;  стирания соседей (~2-3 тыс. тактов), это всё ещё сильно раньше старого общего пути.
vpr_sout:
	ld	hl, vec_su_restore
	jp	vps_two
;  [КОМПОЗИТ25 2026-09-11] vpr_fs2: ОБЕ фазы slow-пары подряд, для СЛИТОЙ пачки. В обычной
;  пачке они разнесены нарочно (save пары обязан идти ПОСЛЕ общего прохода стирания, иначе
;  p0-блок одежды уносит куски ещё не стёртой мумии — жалоба с железа 2026-08-18). В слитой
;  пачке стирания нет вовсе: каждый сосед переписывает свой габарит готовым значением, а
;  попарная проверка уже доказала, что в байты пары не пишет никто. Значит фон под парой
;  чист сразу после её собственного restore, и разносить фазы не нужно — наоборот, вместе
;  они дают САМОЕ КОРОТКОЕ окно «пара разобрана» из возможных.
vpr_fs2:
	call	vpr_sout	; стереть пару… и провалиться в save+show
vpr_ssd:
;  Фон обеих частей снимаем один раз до выбора писателя, в том числе для LAST.
	call	vpr_sv
	ld	a, (vpr_sl)
	cp	2
	ret	z	; LAST: show после мумий, фон уже сохранён
;  vop_ow пишет по ширине одежды во ВСЕ три плоскости. При ncols(4)!=ncols(5)
;  это выходит за область сейва кожи, а детектор p0 мог не захватить край одежды.
;  Прыжок у лестницы: ncols=3/2, p0 не сохранена, vop_ow гасит один бит кирпича;
;  следующий сейв принимает повреждение за фон — остаётся постоянная серая точка.
;  Разная ширина -> штатный вывод каждой части в её собственных границах.
	ld	a, (0x0E499)
	ld	hl, 0x0E599
	cp	(hl)
	jp	nz, vpr_sd
	ld	e, 0
	ld	a, 4
	call	vhr_ovl	; створки: старый vss_or (слот 4 ANDN p1)
	jp	nz, vpr_sd
	call	vop_ow	; одинаковая ширина: одна RMW на плоскость
	ld	hl, vso_prev
	jp	vps_two
vpr_sv:
	ld	hl, vec_su_save
	jp	vps_two
vpr_sd:
	ld	hl, vps_draw	; сейвы уже выполнены в начале vpr_ssd
;  vps_two: применить процедуру (HL) к обеим позициям пары. Последний вызов — провалом,
;  поэтому ret самой процедуры возвращает уже вызывающему vpr_ssd.
vps_two:
	ld	(vps_c+1), hl
	ld	a, (vpr_mix)
	call	vps_one
	ld	a, (vpr_mix)
	inc	a
vps_one:
	call	vso_setord
vps_c:
	jp	0	; ОПЕРАНД: restore / save / vps_draw
;  vps_draw: вывод одного объекта пары — та же проверка «скрыт», что в vso_sdone.
vps_draw:
	call	vec_su_ptr
	ld	l, 0x96
	ld	a, (hl)
	cp	2
	jp	z, vps_nd
	call	vec_spr_show
vps_nd:
	jp	vso_prev
;  vmx_pair: пара героя слитой записью посреди ОБЫЧНОЙ пачки (МИКС, задача#50) — тот же
;  писатель vmxp, что у vso_fastall: подготовка обоих с отложенной записью (vso_merge1 +
;  vpr_save) и чередованная по столбцам запись vpr_wr.
vmx_pair:
	ld	a, (vpr_mix)
	ld	(vmx_w), a
	ld	a, 1	; гейт fixup обязан быть взведён и здесь: слитая запись пары
	ld	(vsu_any), a	; составляет кадр из фона слота (см. шапку vso_fastall), а
	;              в пачке из одних миксов+скрытых vec_su_save не звался бы вовсе
vmxp:
	xor	a	; ЗАДАЧА#53: счётчик годности пары к стек-блиту с нуля (vpr_save)
	ld	(vpz_ok), a
	ld	a, vpr_pa&255	; --- ПАРА: подготовить ОБОИХ, запись отложить ---
	ld	(vpr_def), a
	ld	a, (vmx_w)
	call	vso_setord
	call	vso_merge1
	ld	a, vpr_pb&255
	ld	(vpr_def), a
	ld	a, (vmx_w)
	inc	a
	call	vso_setord
	call	vso_merge1
	xor	a
	ld	(vpr_def), a
	call	vpr_wr	; чередованная запись по столбцам
	ld	a, (vmx_w)
	call	vso_setord
	call	vso_prev
	ld	a, (vmx_w)
	inc	a
	call	vso_setord
	jp	vso_prev	; хвостовой вызов — общий выход
;  vpr_scan: ГДЕ В ПАЧКЕ ПАРА. Идёт в ТИКЕ (хвост vec_nat_sprites, сразу за сортировкой
;  порядка вывода) — ровно по той же причине, по какой туда уехали сортировка и решатель
;  слитой записи: под лучом разбор условий стоит такты, а пачке достаточно одного байта.
;  Замер: проверка «прямо в пачке» стоила 291 такт на кадр (453 на вызов, 1029 вызовов),
;  здесь — один проход на пачку, и пачка платит 40 тактов на объект вместо 453.
;  ПРИЗНАК ПАРЫ: слоты 4 и 5 подряд, равные lo0 и ncols, hi0 отличаются ТОЛЬКО
;  битами плоскости. Две мумии (слоты 6/7, p0 и p1, тот же ряд) этому геометрическому
;  признаку тоже удовлетворяют — без гейта по номеру слота они воровали vpr_at,
;  и прыжок через двоих оставлял силуэт героя (two_mum_jump_resid).
;  ЗАДАЧА#50: гейт vsp_fast отсюда СНЯТ — пара нужна и ОБЫЧНОЙ пачке (микс, см. vmx_check
;  ниже). Оба выхода сканера уходят в vmx_check; пустой/одиночный список отсеян явно.
vpr_scan:
	ld	a, 0x0FF
	ld	(vpr_at), a	; 0xFF = пары нет (позиция такой не бывает)
	ld	a, 0x0FE
	ld	(vpr_mix), a	; 0xFE = микса нет
	xor	a
	ld	(vpr_sl), a	; не тащить sl=2 в кадр без микса
	ld	a, (vsp_n)
	or	a
	ret	z	; пустой список — искать не в чем
	dec	a
	ret	z	; один объект — пары нет
	ld	c, a	; C = сравнений = n-1
	ld	b, 0	; B = позиция в порядке вывода
vprs_l:
	ld	a, b
	add	a, vso_ord&255
	ld	l, a
	ld	h, 255&(vso_ord>>8)
	ld	a, (hl)
	cp	4	; пара героя — ТОЛЬКО 4+5. Две мумии (разные плоскости, тот же
	jp	nz, vprs_nx	; lo0/ncols) иначе воруют vpr_at: сейв снимает героя, а
	add	a, 0x0E0	; vps_two стирает мумий и не рисует их — шлейф прыжка.
	ld	d, a	; D = страница слота первого
	inc	l
	ld	a, (hl)
	cp	5
	jp	nz, vprs_nx
	add	a, 0x0E0
	ld	h, a	; HL -> запись вывода второго
	ld	l, 0x97
	ld	a, (hl)
	ld	e, a	; E = hi0 второго
	inc	l
	ld	a, (hl)
	ld	(vpr_t), a	; lo0 второго
	inc	l
	ld	a, (hl)	; ncols второго
	ld	h, d	; -> первый, L уже 0x99
	or	a
	jp	z, vprs_nx
	; ncols 4 и 5 могут разойтись (одежда шире на p0-гашение) — союз соберёт vmx_one
	dec	l	; lo0
	ld	a, (vpr_t)
	cp	(hl)
	jp	nz, vprs_nx
	dec	l	; hi0
	ld	a, e
	xor	(hl)	; ноль -> одна и та же плоскость, не пара
	jp	z, vprs_nx
	and	0x1F	; разные столбцы -> не пара
	jp	nz, vprs_nx
	ld	a, b
	ld	(vpr_at), a
	jp	vmx_check
vprs_nx:
	inc	b
	dec	c
	jp	nz, vprs_l
;  ===== МИКС-ПАЧКА (ЗАДАЧА#50, 2026-08-04): ПАРА СЛИТОЙ ЗАПИСЬЮ В ОБЫЧНОЙ ПАЧКЕ =======
;  ДИАГНОЗ (tools/verify/hero_atomic.js, лучевая метрика): «герой мерцает вверху» — это
;  ДЫРА СТИРАНИЯ обычного пути: restore возвращает фон под героем в начале пачки, а OR
;  спрайта идёт через avg ~13 тыс. тактов, и луч успевает пройти по СТЁРТОМУ герою.
;  Атрибуция по классам пачек: ВСЕ 718 попаданий луча в дыру героя — пачки, которые увела
;  на обычный путь ДВИЖУЩАЯСЯ МУМИЯ (её габарит/набор плоскостей меняется, слоту нужен
;  новый сейв — отказ vsp_fastmark ЗАКОНЕН). Сама пара героя в этих пачках ГОДНА для
;  слитой записи: стоит на месте (или съехала лишь по вертикали), фон в её слотах лежит.
;  РЕШЕНИЕ: пара выводится слитой записью (vso_merge1 + чередование vpr_wr — тот же код,
;  что на быстром пути) ПРЯМО ВНУТРИ обычной пачки: её не стирают (vso_rloop пропускает),
;  ей не пересохраняют фон (vso_sloop пропускает — ОБЯЗАН пропускать: fb под парой не
;  стёрт, сейв снял бы САМОГО героя как «фон»), а дыры стирания у неё нет ПО ПОСТРОЕНИЮ.
;  КОГДА ЭТО ЗАКОННО (проверяет vmx_check, в ТИКЕ):
;   1) оба объекта пары прошли бы личную проверку vsp_fastmark: слот валиден, pending=1,
;      одноплоскостные (hi0b/hi0c = 0 и в записи, и в шапке — чередование vpr_wr умеет
;      только пару одноплоскостных), hi0/ncols не менялись, |d lo0| < 16;
;   2) непрозрачный режим выключен (vop_i1=0): гашение силуэтом соседа умеет только
;      vec_spr_show;
;   3) НИ ОДИН другой объект пачки не пересекает ОБЪЕДИНЁННЫЙ габарит пары (строки обеих
;      записей И шапок ±15, столбцы) ни своей ЗАПИСЬЮ (его сейв/вывод сняли бы или
;      закрасили байты пары), ни своей ШАПКОЙ (консервативно: его стирание пишет в байты
;      пары; финально это тот же чистый фон и пара поверх него перерисуется, но порядок
;      внутри пачки проверять дороже, чем отказаться).
;  Проверка идёт в тике (как и весь решатель слитой записи) — пачка платит одно сравнение.
;  ЗАДАЧА#53 (2026-08-06): ПАРА ПЕРВОЙ И НА МЕДЛЕННОМ ПУТИ. Проверка непересечения ниже —
;  единственное, что нужно для перестановки пары в НАЧАЛО пачки: если пара ни с кем не делит
;  байт fb, её порядок относительно остальных не значит НИЧЕГО (то же обоснование, что у
;  микса). Годность для СЛИТОЙ записи стала не условием, а РАЗВИЛКОЙ: годна -> vmx_pair,
;  негодна -> vpr_sout (restore->save->show пары, тоже до общего стирания). Признак в vpr_sl.
;  Замер атрибуции транзиента (3000 кадров): 50% пикселей давали пачки, отвергнутые по
;  vop_i1 (непрозрачный герой), 43% — по разошедшемуся hi0b. Обе причины запрещают СЛИТУЮ
;  запись, но не мешают вывести пару первой обычным механизмом.
vmx_check:
	ld	a, (vsp_fast)
	or	a
	ret	nz	; пачка целиком слитая — пару выводит vso_fastall
	ld	a, (vpr_at)
	cp	0x0FF
	ret	z	; пары нет
	ld	(vmx_p), a
	call	vop_eff	; непрозрачный герой / грязный сейв / непустой фон (см. vop_eff)
	ld	(vpr_sl), a	; -> медленный путь, но пара всё равно идёт ПЕРВОЙ
	ld	a, 0x0FF	; объединение габарита пары: min/max по строкам И по столбцам
	ld	(vmx_l0), a	; (при медленном пути hi0/ncols шапки и записи могут разойтись,
	ld	(vmx_c0), a	; и объединение столбцов уже не равно записи)
	xor	a
	ld	(vmx_l1), a
	ld	(vmx_c1), a
	ld	a, (vmx_p)
	call	vmx_one	; первый объект пары годен? (негоден -> vmx_bad снимает вызов)
	ld	a, (vmx_p)
	inc	a
	call	vmx_one
	ld	c, 0	; --- никто из остальных не пересекает габарит пары ---
vmx_j:
	ld	a, (vmx_p)
	ld	b, a
	ld	a, c
	sub	b	; позиции самой пары пропускаем
	cp	2
	jp	c, vmx_jn
	ld	a, c
	add	a, vso_ord&255
	ld	l, a
	ld	h, 255&(vso_ord>>8)
	ld	a, (hl)
	add	a, 0x0E0
	ld	h, a	; H = страница слота кандидата (vmx_ovl H/L не трогает)
	ld	l, 0x96
	ld	a, (hl)
	cp	2
	jp	z, vmx_h2	; скрыт: записи вывода нет, шапку всё равно проверить
	ld	l, 0x97	; --- габарит ЗАПИСИ кандидата ---
	call	vmx_gb
vmx_h2:
	ld	l, 0
	ld	a, (hl)
	dec	a
	jp	nz, vmx_jn	; шапки нет — стирать нечего
	ld	l, 1	; --- габарит ШАПКИ кандидата ---
	call	vmx_gb
vmx_jn:
	inc	c
	ld	a, c
	ld	hl, vsp_n
	cp	(hl)
	jp	c, vmx_j
	jp	vcm_tick	; микс + LAST, если vhr_ovl видит мумию (vmx_ovl часто нет)
;  vmx_one: A = позиция. ЖЁСТКО требуется только «слот валиден и pending=1» — иначе пары
;  как объекта нет и переставлять нечего (vmx_bad снимает возврат в vmx_check). Дальше
;  собирается ОБЪЕДИНЕНИЕ габаритов шапки и записи (строки vmx_l0/l1, столбцы vmx_c0/c1) —
;  именно его проверяет vmx_ovl на пересечение с остальными. Хвост процедуры решает, годна
;  ли пара для СЛИТОЙ записи; негодность больше не отменяет перестановку, а лишь взводит
;  vpr_sl («выводить первой, но обычным механизмом»).
vmx_one:
	jp	vcm_pone
;  vmx_un (ФАЗА 4): габарит, на который смотрит L (hi0 по L, lo0 по L+1, ncols по L+2 —
;  так лежат и шапка 1/2/3, и запись 0x97/0x98/0x99), целиком в объединение пары: строки
;  в vmx_l0/l1, столбцы в vmx_c0/c1. Раньше это были ДВЕ процедуры (vmx_mm по строкам,
;  vmx_cc по столбцам) и ЧЕТЫРЕ вызова с перезагрузкой L; порядок слияния на результат не
;  влияет — min/max коммутативны. Плоскость в столбцах игнорируем: пересечение считается
;  по столбцам, как и в vmx_ovl. Клоб A,B,C,D,L; C свободен (vmx_check заводит счётчик
;  петли уже ПОСЛЕ обоих vmx_one).
vmx_un:
	ld	a, (hl)
	and	0x1F
	ld	b, a	; B = левый столбец
	inc	l
	ld	d, (hl)	; D = lo0
	inc	l
	ld	a, (hl)
	add	a, b
	ld	c, a	; C = правый край (эксклюзивно)
	ld	a, (vmx_c0)
	cp	b
	jp	c, vmx_cc1
	ld	a, b
	ld	(vmx_c0), a
vmx_cc1:
	ld	a, (vmx_c1)
	cp	c
	jp	nc, vmx_cc2
	ld	a, c
	ld	(vmx_c1), a
vmx_cc2:
	ld	a, (vmx_l0)
	cp	d
	jp	c, vmx_m1	; l0 < d — минимум не меняется
	ld	a, d
	ld	(vmx_l0), a
vmx_m1:
	ld	a, (vmx_l1)
	cp	d
	jp	nc, vmx_m2
	ld	a, d
	ld	(vmx_l1), a
vmx_m2:
	ret
;  vmx_gb (ФАЗА 4): габарит по L -> (vmx_t)=lo0, D=hi0, E=ncols и сразу vmx_ovl. Шапка
;  (hi0 1, lo0 2, ncols 3) и запись (0x97/0x98/0x99) лежат ОДИНАКОВО — база, база+1,
;  база+2, — поэтому обоим кандидатским габаритам хватает одного тела. Выходит с L=база+2;
;  vmx_ovl L не трогает, а vmx_check L перезагружает. Глубина вызова прежняя (1) — на неё
;  опирается `pop bc` в vmx_bad.
vmx_gb:
	ld	d, (hl)	; hi0
	inc	l
	ld	a, (hl)	; lo0
	ld	(vmx_t), a
	inc	l
	ld	e, (hl)	; ncols
;  vmx_ovl: пересекается ли габарит-кандидат (vmx_t = lo0, D = hi0, E = ncols) с
;  объединённым габаритом пары? Пересекается -> vmx_bad. Клоб A,B,D,E; H,L и C НЕ трогает.
vmx_ovl:
	ld	a, e
	or	a
	ret	z	; ncols=0 — пусто
	ld	a, (vmx_l1)	; строки: lo > l1+15 -> ниже пары не бывает... выше пары -> мимо
	add	a, 15
;  ЗАВОРОТ СТРОК (2026-08-20). Обе границы считались 8 битами, и обе врали в зоне заворота:
;  при l1>=241 сумма l1+15 переполняется в 0..14, при l0<15 разность l0-15 заёмом уезжает
;  в 241..255. В обоих случаях сравнение отвечало «строки НЕ пересекаются» — то есть
;  разрешало быстрый путь пары там, где он незаконен. Ошибка была в ОПАСНУЮ сторону:
;  ложное «пересекается» лишь уводит на медленный путь, ложное «не пересекается» портит
;  картинку. Теперь при переполнении/заёме соответствующая граница просто не проверяется:
;  «выше пары» невозможно, если верх пары за 255, и «ниже пары» невозможно, если низ за 0.
;  Родня этой мины — заворот в vec_su_fixup (см. vec_blit.asm), там он давал баг владельца
;  «половина спрайта остаётся в верхнем ряду». Цена здесь: 6 байт, 10 тактов на проверку.
	jp	c, vmx_r1
	ld	b, a
	ld	a, (vmx_t)
	cp	b	; lo кандидата > l1+15 -> строки не пересекаются
	jp	z, vmx_r1
	jp	nc, vmx_ok
vmx_r1:
	ld	a, (vmx_l0)
	sub	15
	jp	c, vmx_cols
	ld	b, a
	ld	a, (vmx_t)
	cp	b	; lo кандидата < l0-15 -> тоже нет
	jp	c, vmx_ok
vmx_cols:
	ld	a, d	; столбцы: [c..c+nc) против [c0..c1)
	and	0x1F
	ld	d, a
	add	a, e
	ld	e, a	; E = правый край кандидата (эксклюзивно)
	ld	a, (vmx_c0)
	cp	e	; c0 >= правого края кандидата -> не пересекаются
	jp	nc, vmx_ok
	ld	a, (vmx_c1)
	ld	b, a
	ld	a, d
	cp	b	; левый край кандидата >= c1 -> не пересекаются
	jp	nc, vmx_ok
;  [2026-09-19] ПЕРЕСЕЧЕНИЕ С МУМИЕЙ, ПАРА ГЕРОЯ. Раньше vmx_bad снимал микс, пара
;  шла SAT-порядком (герой, потом мумия) и vtm_hrd рисовал её СНОВА — кратность 3.
;  Теперь микс остаётся: стереть+сейв как у slow-пары, show ПОСЛЕ мумий (vop_ow).
;  Створки (слоты 0-3) по-прежнему vmx_bad: их накрывает SAT 0-3, last-show героя
;  им не нужен.
	ld	a, (vmx_p)
	add	a, vso_ord&255
	ld	l, a
	ld	h, 255&(vso_ord>>8)
	ld	a, (hl)
	cp	4
	jp	z, vmx_last
	cp	5
	jp	nz, vmx_bad
	ld	a, (vop_i1)
	or	a
	jp	z, vmx_bad
vmx_last:
	ld	a, 2
	ld	(vpr_sl), a
	ld	a, (vmx_p)
	ld	(vpr_mix), a
	pop	bc
	ret
vmx_bad:
	pop	bc	; снять возврат (vmx_one/vmx_ovl зовутся с глубины 1) и выйти в тик
	ret
vmx_ok:
	ret
;  vpr_wr: чередованная запись пары. (vsb_lo)=lo0, (vsb_nc)=ncols — общие у обоих (это и
;  есть условие пары), страницы слотов и hi0 сложены подготовкой в vpr_pa/ha, vpr_pb/hb.
;  Смещение спрайта в слоте = смещение фона + 0x9A (6 -> 0xA0), отдельной ячейки не надо.
;  ЗАДАЧА#53 (2026-08-07): ЭТО ТЕПЕРЬ ЗАПАСНОЙ ПУТЬ. Если фон под ОБЕИМИ половинами пары
;  доказанно нулевой (vpz_ok = 2, счётчик набирает vpr_save), пара пишется СТЕК-БЛИТОМ
;  (vpz_pair, 868 тактов на столбец-пару против 1388 здесь). Сюда попадает лишь редкий
;  случай ненулевого фона хотя бы у одной половины — там нужен OR с блоком слота, а
;  стек-блит держит в SP буфер спрайта и второго указателя не имеет.
vpr_wr:
	ld	a, (vpz_ok)
	cp	2
	jp	nz, vpr_or
	ld	a, (vsb_lo)
	cp	240
	jp	c, vpz_pair	; PUSH в fb не пересекает адрес 0
vpr_or:
	ld	a, (vpr_pa)
	ld	h, a
	ld	d, a
	ld	l, 6	; смещения столбца в слоте: фон 6+16c, спрайт 0xA0+16c —
	ld	e, 0x0A0	; У ОБОИХ ОДНИ И ТЕ ЖЕ (это условие пары), поэтому L и E
vpr_c:		; не перезагружаются, а идут через возврат из vsb_mcol
	ld	a, (vpr_ha)
	ld	b, a	; страница fb столбца первого
	inc	a
	ld	(vpr_ha), a
vpr_ka:
	call	vsb_mcol	; ОПЕРАНД (ЗАДАЧА#49): vsb_mcol / vsz_mcol при нулевом фоне
	ld	a, l	; тот же столбец, но второму объекту
	sub	16
	ld	l, a
	ld	a, e
	sub	16
	ld	e, a
	ld	a, (vpr_pb)
	ld	h, a
	ld	d, a
	ld	a, (vpr_hb)
	ld	b, a
	inc	a
	ld	(vpr_hb), a
vpr_kb:
	call	vsb_mcol	; ОПЕРАНД (ЗАДАЧА#49); L,E ушли на СЛЕДУЮЩИЙ столбец — как и надо
	ld	a, (vpr_pa)
	ld	h, a
	ld	d, a
	ld	a, (vsb_nc)
	dec	a
	ld	(vsb_nc), a
	jp	nz, vpr_c
	ret

;  vso_static: A = 1, если объект vec_nsp_idx — СТВОРКА ВОРОТ (слоты 0-3), её слот валиден
;  и габарит СОВПАЛ с записью вывода, то есть створка НЕ ДВИГАЛАСЬ. Иначе A = 0. Клоб A,H,L.
;  === ЗАЧЕМ (жалоба с железа 2026-08-04: «мигает правая створка, когда герой входит внутрь
;  === ворот») ========================================================================
;  ЗАМЕР: мерцание идёт парами кадров, ровно на 79 пикселей, каждые ~24 кадра:
;    f101 пачка=[4,5,0,1,2] -> idx14 превращается в idx6 (створка потеряла p0);
;    f102 пачка=[3]         -> idx6 обратно в idx14.
;  То есть ПАЧКА НЕ УКЛАДЫВАЕТСЯ В КАДР и рвётся между БАЗОЙ створки (слот 2, кладёт p1+p2
;  и гасит p0) и её ДЕТАЛЬЮ (слот 3, кладёт p0 на лица кирпичей). Один кадр створка стоит
;  без p0 — вся красная.
;  ЛЕЧЕНИЕ: створка НЕПОДВИЖНА и НЕПРОЗРАЧНА — она перерисовывает свой габарит целиком.
;  Значит ей не нужны ни стирание (restore), ни пересохранение фона (save), пока габарит
;  тот же: фон в слоте и так поддерживает vec_su_fixup при каждом блите клетки под ней.
;  Снимаем два прохода из трёх — пачка в кадрах с воротами укорачивается и перестаёт
;  рваться. Как только габарит МЕНЯЕТСЯ (створка поехала или появилась), обе операции
;  выполняются как раньше: шапка слота всё это время описывает ТУ ЖЕ позицию, в которой
;  створка нарисована, поэтому restore по ней корректен.
vso_static:
	ld	a, (vec_nsp_idx)
	cp	4
	jp	nc, vst_no
	add	a, 0x0E0
	ld	h, a
	ld	l, 0
	ld	a, (hl)	; valid шапки
	or	a
	jp	z, vst_no
	ld	l, 1	; hi0 шапки против hi0 записи вывода
	ld	a, (hl)
	ld	l, 0x97
	cp	(hl)
	jp	nz, vst_no
	ld	l, 2	; lo0
	ld	a, (hl)
	ld	l, 0x98
	cp	(hl)
	jp	nz, vst_no
	ld	l, 3	; ncols
	ld	a, (hl)
	ld	l, 0x99
	cp	(hl)
	jp	nz, vst_no
	ld	a, 1
	ret
vst_no:
	xor	a
	ret

;  ===== BEAMW: ждать, пока луч не уйдёт со строк объекта (ветка beamwait) ================
;  ЗАЧЕМ. Объект стирается (restore) и выводится (show) в РАЗНЫЕ моменты, между ними в fb
;  пустой фон. Если луч в это время идёт по строкам объекта — виден пустой фон (мерцание).
;  ЧТО ДЕЛАЕТ. Перед restore объекта оценивает срок жизни окна C (до последнего show) и
;  ждёт, пока луч не окажется ВНЕ строк объекта на весь этот срок: или ещё не дошёл и не
;  дойдёт за C, или уже ушёл ниже. Окно невозможно (C + высота объекта не влезают в кадр)
;  или фазы нет -> не ждём вовсе (поведение как раньше).
;  ИСТОЧНИК ФАЗЫ. Канал 2 ВИ53 (часы музыки: период 60000 отсчётов, отсчёт = 2 такта CPU).
;  Шапка ISR (vsnd_tick_hdr) и так читает его раз в кадр — копия в vbw_t0, vbw_ok=1, если
;  часы были доступны. Время от запроса кадрового IRQ: tau = (vbw_t0 - сейчас) mod 60000
;  + VBW_K0, затем mod 29952 (кадр). Канал под нотой (vtm_have=0) -> ждать нечем.
;  ГЕОМЕТРИЯ ЛУЧА (beam_harness): строка fb lo видна на экранной строке r=(VS-lo)&255,
;  луч проходит её через (40+r)*192-44 тактов после запроса IRQ = 3818+96*r отсчётов.
;  Вход: vec_nsp_idx = слот; B = последняя позиция в vso_ord (включительно): стоимость
;  C = VBW_C0 + VBW_KC * sum(ncols слотов vso_ord[0..B]). Сохраняет все регистры.
;  Если дошёл до опроса часов, возвращает DI (restore всё равно начинается с di).
VBW_FQ:		equ 29952	; кадр в отсчётах ВИ53
VBW_T0:		equ 3818	; отсчёты от запроса IRQ до луча на строке r=0
VBW_M:		equ 130	; запас по лучу с каждой стороны (отсчёты)
VBW_KC:		equ 2200	; отсчётов на столбец объекта (restore+save+show)
VBW_C0:		equ 1500	; постоянная добавка: вложенные тики, обвязка
VBW_LMAX:	equ 21000	; дуга длиннее (отсчёты) — не ждём: окно > ~0.7 кадра всё равно накрывает луч, а ожидание только теряет кадровые IRQ
VBW_RES:	equ 1200	; резерв кадра: окно длиннее FQ-RES считаем невозможным
VBW_KA:		equ 1150	; отсчёты от запроса IRQ до показания в шапке внешнего ISR
VBW_KB:		equ 760	; то же во вложенном ISR
VBW_OV:	equ 110	; программный счёт: обвязка одного опроса (отсчёты)
VBW_MAXW:	equ 16000	; потолок ожидания, отсчёты (30000 = без потолка)
VBW_KRO:	equ 3000	; программный счёт: отсчётов restore на столбец, мумия и прочие
VBW_KRH:	equ 1100	; то же, слоты героя 4-5
VBW_MS:		equ 600	; запас программного счёта (отсчёты)
VBW_S1:		equ 3400	; старт пачки во внешнем ISR (отсчёты от запроса IRQ)
VBW_S2:		equ 3000	; то же во вложенном
vbw_wait:
	push	af
	push	bc
	push	de
	push	hl
	xor	a
	ld	(vbw_np), a	; счётчик опросов: страховка от зависшего счётчика ВИ53
	ld	a, b
	ld	(vbw_cb), a
	xor	a
	ld	(vbw_hw), a	; hw=1: фаза по счётчику ВИ53; hw=0: программный счёт vbw_s
	ld	a, (vbw_ok)
	or	a
	jp	z, vbw_g0
	ld	a, (vtm_have)
	or	a
	jp	z, vbw_g0
	inc	a
	ld	(vbw_hw), a
vbw_g0:
	ld	a, (vec_nsp_idx)
	add	a, 0x0E0
	ld	h, a
	ld	l, 0
	ld	a, (hl)	; шапка невалидна -> restore пуст, окна нет
	or	a
	jp	z, vbw_out
	ld	l, 2
	ld	d, (hl)	; D = lo прежнего габарита
	ld	l, 0x96
	ld	a, (hl)
	ld	l, 0x98
	ld	e, (hl)	; E = lo нового габарита
	cp	2
	jp	nz, vbw_g1
	ld	e, d	; объект скрыт: новый = прежний
vbw_g1:
	ld	a, d
	cp	e
	jp	c, vbw_g2
	ld	a, e	; D = min lo, E = max lo
	ld	e, d
	ld	d, a
vbw_g2:
	ld	a, e
	add	a, 15
	jp	nc, vbw_g3	; apex-fast: верх за fb 255 клипом не рисуется (ЗАДАЧА#56), луч видит строки до fb 255 -> клампим, а не «не ждём»
	ld	a, 255
vbw_g3:
	ld	c, a
	ld	a, vec_vscroll
	sub	c	; A = rmin (верхняя экранная строка)
	ld	(vbw_r), a
	ld	b, a
	ld	a, vec_vscroll
	sub	d	; A = rmax
	sub	b
	jp	c, vbw_out	; габарит перевалил через край экрана: не ждём
	inc	a	; n = число строк луча
	jp	z, vbw_out
	call	vbw_x96
	ld	de, 2*VBW_M
	add	hl, de
	ld	(vbw_len), hl	; Len0 = 96*n + 2M
	ld	a, (vbw_cb)
	ld	b, a
	call	vbw_pfx	; apex-fast: D = 0, C = начало префикса (0; для окна пары — её позиция), см. vec_bw.asm
vbw_cl:
	ld	a, c
	add	a, vso_ord&255
	ld	l, a
	ld	h, 255&(vso_ord>>8)
	ld	a, (hl)
	add	a, 0x0E0
	ld	h, a
	ld	l, 3
	ld	a, (hl)	; ncols прежнего габарита
	ld	l, 0x99
	cp	(hl)
	jp	nc, vbw_c1
	ld	a, (hl)	; ncols нового больше
vbw_c1:
	add	a, d
	ld	d, a
	ld	a, c
	inc	c
	cp	b
	jp	nz, vbw_cl
	ld	hl, VBW_C0
	ld	a, d
	ld	de, VBW_KC
	or	a
	jp	z, vbw_k1
vbw_mul:
	add	hl, de
	dec	a
	jp	nz, vbw_mul
vbw_k1:
	ld	a, (vbw_hw)
	or	a
	jp	nz, vbw_k2
	ld	de, VBW_MS	; программный счёт грубее: запас на начало дуги
	add	hl, de
vbw_k2:
	ld	(vbw_c), hl	; C в отсчётах
	ex	de, hl
	ld	hl, (vbw_len)
	add	hl, de
	ld	(vbw_len), hl	; Len = 96n + 2M + C
	ld	a, l
	sub	255&VBW_LMAX
	ld	a, h
	sbc	a, 255&(VBW_LMAX>>8)
	jp	nc, vbw_out	; окно невозможно или слишком длинное: тяжёлую пачку не ждём (она теряет IRQ и тики музыки)
	ld	a, (vbw_r)
	call	vbw_x96
	ld	de, VBW_T0-VBW_M
	add	hl, de
	ex	de, hl	; DE = T0 - M + 96*rmin
	ld	hl, (vbw_c)
	push	de
	ex	de, hl
	ld	hl, (vbw_ao)	; смещение начала restore объекта от старта ожидания (отсчёты)
	add	hl, de	; HL = C + ao
	pop	de
	ld	a, e	; DE -= (C + ao)
	sub	l
	ld	e, a
	ld	a, d
	sbc	a, h
	ld	d, a
	jp	nc, vbw_a1
vbw_a0:
	ld	hl, VBW_FQ
	add	hl, de
	ex	de, hl
	jp	nc, vbw_a0	; всё ещё меньше нуля: ещё кадр
vbw_a1:
	ex	de, hl
	ld	(vbw_a), hl	; A = начало запретной дуги стартов (mod кадр)
vbw_poll:
	ld	a, (vbw_hw)
	or	a
	jp	nz, vbw_hwr
	ld	hl, (vbw_s)
	jp	vbw_p2
vbw_hwr:
	di
	ld	a, 0x80	; latch канала 2
	out	(0x08), a
	in	a, (0x09)
	ld	e, a
	in	a, (0x09)
	ld	d, a	; DE = показание сейчас
	ld	hl, (vbw_t0)
vbw_ei:
	ei	; DI только на чтение счётчика и vbw_t0 (иначе теряются кадровые IRQ)
	ld	a, l
	sub	e
	ld	l, a
	ld	a, h
	sbc	a, d
	ld	h, a	; HL = t0 - сейчас
	jp	nc, vbw_p1
	ld	de, 60000
	add	hl, de
vbw_p1:
vbw_p2:
	ld	a, l
	sub	255&VBW_FQ
	ld	e, a
	ld	a, h
	sbc	a, 255&(VBW_FQ>>8)
	jp	c, vbw_tau
	ld	h, a
	ld	l, e
	jp	vbw_p2
vbw_tau:	; HL = tau (отсчёты от запроса IRQ, mod кадр)
	ex	de, hl
	ld	hl, (vbw_a)
	ld	a, e
	sub	l
	ld	e, a
	ld	a, d
	sbc	a, h
	ld	d, a	; DE = tau - A
	jp	nc, vbw_p4
	ld	hl, VBW_FQ
	add	hl, de
	ex	de, hl
vbw_p4:
	ld	hl, (vbw_len)
	ld	a, e
	sub	l
	ld	a, d
	sbc	a, h
	jp	nc, vbw_out	; d >= Len: вне запретной дуги, можно
	ld	a, l	; R = Len - d: сколько ещё ждать (отсчёты)
	sub	e
	ld	l, a
	ld	a, h
	sbc	a, d
	ld	h, a
	ld	a, l	; потолок ожидания: дольше VBW_MAXW не ждём, лучше редкое мерцание
	sub	255&VBW_MAXW
	ld	a, h
	sbc	a, 255&(VBW_MAXW>>8)
	jp	nc, vbw_out
	ld	a, (vbw_np)
	inc	a
	ld	(vbw_np), a
	jp	z, vbw_out	; 256 опросов подряд — счётчик стоит (нет часов/стенд без времени): не ждём
	ld	a, 1
	ld	(vbw_chg), a	; ждём на самом деле (vbw_all повторит проход)
;  Пауза до следующего опроса ~ R/16 кругов (10 отсчётов на круг), от 4 до 200. Каждый опрос — короткий
;  DI на чтение счётчика, а кадровое прерывание под DI ТЕРЯЕТСЯ (не защёлкивается): частые опросы
;  теряли кадры и тики музыки («звук заедает»). Музыку в ожидании НЕ тикаем: кадровый тик даёт шапка
;  вложенного ISR в постоянной фазе, тик из ожидания в произвольной фазе давал пары интервалов 0.5/1.5.
	ld	a, h
	cp	13
	ld	a, 200
	jp	nc, vbw_sn
	ld	a, l
	rrca
	rrca
	rrca
	rrca
	and	0x0F
	ld	e, a
	ld	a, h
	add	a, a
	add	a, a
	add	a, a
	add	a, a
	or	e
	cp	200
	jp	c, vbw_sm
	ld	a, 200
vbw_sm:
	cp	4
	jp	nc, vbw_sn
	ld	a, 4
vbw_sn:
	ld	b, a
	ei
	ld	a, (vbw_hw)
	or	a
	jp	nz, vbw_sp
	ld	l, b	; без часов: время ведём сами, круг = 10 отсчётов + обвязка
	ld	h, 0
	ld	d, h
	ld	e, l
	add	hl, hl
	add	hl, hl
	add	hl, de
	add	hl, hl
	ld	de, VBW_OV
	add	hl, de
	ex	de, hl
	ld	hl, (vbw_s)
	add	hl, de
	ld	(vbw_s), hl
vbw_sp:
	dec	b
	jp	nz, vbw_sp
	jp	vbw_poll
vbw_out:
	pop	hl
	pop	de
	pop	bc
	pop	af
	ret
;  [stair-gem] vbw_soft0 снят: программный счёт vbw_s прибавлял цену restore ПРЕДЫДУЩИХ позиций, хотя все ожидания идут ДО первого restore
;  (vbw_all), и пара героя стирается первой. Часы уходили вперёд на 2-3 restore, ожидание пары считало луч уже позади и не ждало.
;  vbw_x96: A -> HL = 96*A. Клоб DE.
vbw_x96:
	ld	l, a
	ld	h, 0
	add	hl, hl
	add	hl, hl
	add	hl, hl
	add	hl, hl
	add	hl, hl
	ld	d, h
	ld	e, l
	add	hl, hl
	add	hl, de
	ret
;  vso_setidx: A = позиция в списке вывода -> vec_nsp_idx = индекс слота.
vso_setidx:
	add	a, vsp_list&255
	ld	l, a
	ld	h, 255&(vsp_list>>8)
	ld	a, (hl)
	ld	(vec_nsp_idx), a
	ret
;  vso_setord: то же, но из ОТСОРТИРОВАННОГО порядка вывода.
vso_setord:
	add	a, vso_ord&255
	ld	l, a
	ld	h, 255&(vso_ord>>8)
	ld	a, (hl)
	ld	(vec_nsp_idx), a
	ret
;  vso_sortord: vso_ord = список вывода, УСТОЙЧИВО отсортированный по lo0 ПО УБЫВАНИЮ.
;  lo0 = 240-Y, значит БОЛЬШЕЕ lo0 = ВЫШЕ на экране => обход идёт в порядке хода луча:
;  верхние объекты дописываются в fb первыми и успевают до подхода растра. По этому же
;  порядку идёт теперь и сохранение фона (скользящим фронтом, см. vec_spr_out); стирание
;  (20->0) остаётся как было — его порядок обеспечивает раскрутку перекрытий.
;  УСТОЙЧИВОСТЬ ОБЯЗАТЕЛЬНА: два спрайта героя (слоты 4 и 5) имеют ОДИН lo0 и обязаны
;  остаться рядом и в прежнем порядке — они компонуются OR-ом поверх общего фона.
;  Вставочная сортировка: объектов единицы, ~400 тактов против ~15 тыс. у пачки.
vso_sortord:
;  Устойчивая вставочная сортировка по lo0 УБЫВ. На железе обязательна (ret = нет спрайтов).
;  Сжата под mumJump (engine-cleanup).
	ld	a, (vsp_n)
	or	a
	ret	z
	ld	b, a
	xor	a
vsrt_i:
	ld	c, a
	call	vso_setidx
	ld	a, (vec_nsp_idx)
	ld	(vsrt_v), a
	call	vso_lo
	ld	(vsrt_k), a
	ld	a, c
vsrt_w:
	ld	(vsrt_j), a
	or	a
	jp	z, vsrt_put
	dec	a
	call	vsrt_at	; HL = &ord[A], A = ord[A]
	ld	(vsrt_t), a
	call	vso_lo
	ld	e, a
	ld	a, (vsrt_k)
	cp	e
	jp	c, vsrt_put
	jp	z, vsrt_put
	ld	a, (vsrt_j)
	call	vsrt_at
	ld	a, (vsrt_t)
	ld	(hl), a
	ld	a, (vsrt_j)
	dec	a
	jp	vsrt_w
vsrt_put:
	ld	a, (vsrt_j)
	call	vsrt_at
	ld	a, (vsrt_v)
	ld	(hl), a
	ld	a, c
	inc	a
	cp	b
	jp	nz, vsrt_i
	ret
;  A = индекс -> HL=&ord[A], A=ord[A]. Клоб H,L.
vsrt_at:
	ld	hl, vso_ord
	add	a, l
	ld	l, a
	ld	a, (hl)
	ret
;  [2026-07-30] БЫСТРЫЙ «слитый» путь (vso_fast/vec_spr_showm/vsb_merge) БЫЛ СНЯТ. Он писал
;  в fb сразу фон-из-слота OR спрайт ОДНОЙ записью, минуя стирание и сохранение, и был
;  неверен для объектов, ДЕЛЯЩИХ плоскость и точку с другим объектом пачки: у героя
;  слоты 4 (одежда, p2) и 5 (кожа, p1 + дубль в p2) стоят в одной точке, и запись
;  второго затирала вклад первого, подставляя вместо него фон, снятый КАДРОМ РАНЬШЕ
;  => одна половина героя отставала на кадр (шлейф; на железе виден глазом, замером
;  T_resid — лишние биты p2 под героем в 24.8% кадров, до 31 пикселя).
;  [2026-07-31, ЗАДАЧА#37 ШАГ 3] ВЕРНУЛИ. Диагноз «чистая запись не компонуется» верен,
;  но лечится не отказом, а тем, что делящие плоскость объекты СКЛАДЫВАЮТСЯ ЗАРАНЕЕ:
;  спрайт слота 5 OR-ится в буфер слота 4 ещё в подготовке (vsd_dropb), после чего каждую
;  плоскость пишет ровно один объект, и компоновать в fb уже нечего. Остальные случаи
;  отсекает попарная проверка vsp_fastmark (общая плоскость + пересечение габаритов ->
;  старый путь). См. vsb_merge/vso_fastall и гейт D в tools/verify/spr_resid_gate.js.
;  vso_prev: Y,X,pat из записи вывода -> vec_nsp_prev[idx] (детект изменений след. кадра).
vso_prev:
	ld	a, (vec_nsp_idx)
	ld	l, a
	ld	h, 0
	ld	d, h
	ld	e, l
	add	hl, hl	; idx*3
	add	hl, de
	ld	de, vec_nsp_prev
	add	hl, de
	ex	de, hl	; DE = prev
	call	vec_su_ptr
	ld	l, 0x9C
	ld	a, (hl)
	ld	(de), a
	inc	l
	inc	de
	ld	a, (hl)
	ld	(de), a
	inc	l
	inc	de
	ld	a, (hl)
	ld	(de), a
	ret
;  vec_spr_show: буфер (слот+0xA0) -> fb во все плоскости объекта. Геометрию берём ИЗ
;  ЗАПИСИ ВЫВОДА (+0x97 hi0, +0x98 lo0, +0x99 ncols, +0x9F hi0b, +0x9B hi0c), а НЕ из
;  шапки слота (ЗАДАЧА#37). Две причины: (1) при pending=3 шапки нет вовсе — сейв этого
;  объекта снят как дубль, слот инвалидирован; (2) +0x9A (hi0b ДЛЯ СЕЙВА) дедуп может
;  обнулить, а рисовать 2-ю плоскость всё равно надо — для вывода служит копия +0x9F.
;  Значения те же, что раньше писала в шапку vec_su_save, — цена правки ноль тактов.
vec_spr_show:
;  ЗАДАЧА#39: НЕПРОЗРАЧНЫЙ ГЕРОЙ. Если подготовка нашла под силуэтом чужой фон, кожа
;  гасит СВОЮ плоскость силуэтом СОСЕДА (он держит весь силуэт) ПЕРЕД своим OR — иначе
;  фон p1 просвечивал бы сквозь одежду. Чужую p0 гасит сосед штатным hi0c (см. vsd_dropb).
;  Цена, когда это не наш объект: 45 тактов на вывод (18 тактов на кадр геймплея).
	ld	a, (vop_i1)
	ld	c, a
	ld	a, (vec_nsp_idx)
	inc	a
	cp	c
	jp	nz, vss_nomask
	call	vec_su_ptr
	ld	l, 0x99
	ld	b, (hl)	; ncols
	ld	a, b
	or	a
	jp	z, vss_nomask
	ld	l, 0x98
	ld	a, (hl)
	ld	(vsb_lo), a
	ld	l, 0x97
	ld	c, (hl)	; своя плоскость+столбец
	ld	a, (vop_pg)
	ld	d, a	; DE = буфер соседа = силуэт
	ld	e, 0x0A0
	call	vsb_andn
vss_nomask:
	call	vec_su_ptr
	ld	l, 0x98
	ld	a, (hl)	; lo0
	ld	(vsb_lo), a
	ld	l, 0x99
	ld	b, (hl)	; ncols
	ld	a, b	; СТРАХОВКА: ncols=0 (слот не заполнен) -> dec b дал бы 256
	or	a	; столбцов записи «куда попало». Три инструкции на объект.
	ret	z
	ld	l, 0x0D3	; ЗАДАЧА#52: ЗАЛИВКА створки -> композит по всем трём плоскостям
	ld	a, (hl)	; (значение признака = страница слота ДЕТАЛИ, где лежат лица)
	or	a
	jp	nz, vsc_leaf
vss_or:
;  Створка SWAP держит p1 (idx4). OR одежды в p2 поверх неё = idx6, цвет кожи —
;  «голый» при живом p2. Слот 4 гасит p1 своим силуэтом; кожа (5) вернёт p1 на
;  лицо/руки. Пачка и vec_hero_redraw обе входят сюда. Замер: door_close_planes.js.
	ld	a, (vec_nsp_idx)
	cp	4
	jp	nz, vss_or2
	ld	l, 0x97
	ld	a, (hl)	; hi0 = p2+столбец
	xor	0x60	; -> p1+столбец
	ld	c, a
	ld	d, h
	ld	e, 0x0A0
	push	bc
	call	vsb_andn
	pop	bc
	ld	h, d
vss_or2:
	ld	l, 0x97
	ld	c, (hl)	; hi0
	ld	d, h	; DE = буфер сдвинутого спрайта
	ld	e, 0x0A0
	call	vsb_or
	ld	h, d	; vsb_or/vsb_andn двигают только E — страница слота цела в D
	ld	l, 0x9F
	ld	c, (hl)	; hi0b: 2-я плоскость (dual), 0 = нет
	ld	a, c
	or	a
	jp	z, vss_c
	ld	l, 0x0D0	; ЗАДАЧА#41: у непрозрачной мумии hi0b не РИСУЕТ, а ГАСИТ —
	ld	a, (hl)	; ей нужно гасить ДВЕ чужие плоскости, а поле hi0c одно
	or	a	; (флаги переживают ld — они от этого or a)
	ld	l, 0x99
	ld	b, (hl)
	ld	d, h
	ld	e, 0x0A0
	jp	nz, vss_bandn
	call	vsb_or
	jp	vss_c
vss_bandn:
	call	vsb_andn
vss_c:
	ld	h, d	; (D = страница слота на всех путях сюда, см. выше)
	ld	l, 0x9B
	ld	c, (hl)	; hi0c: гасимая плоскость masked-спрайта, 0 = нет
	ld	a, c
	or	a
	jp	z, vss_done
	ld	l, 0x99
	ld	b, (hl)
	ld	d, h
	ld	e, 0x0A0
	call	vsb_andn
vss_done:
	jp	vtm_afterdraw
;  ===== СТВОРКА ВОРОТ ОДНИМ ОБЪЕКТОМ (ЗАДАЧА#52, 2026-08-05) =========================
;  ЭТАЛОН (msx_p1_leaf на картридже): $DC цвет 3 — сплошной светло-зелёный прямоугольник,
;  поверх $D8 цвет 1 — ЧЁРНЫЙ рисунок швов. У нас заливка клала p1+p2 на весь габарит
;  (= idx6, тот же слот палитры, что кожа героя — владелец так и описал: «просвечивает
;  красный, похожий на кожу»), а деталь добавляла p0 только на лица.
;  p1 := (фон & ~заливка) | лица -> idx4 ЗЕЛЁНЫЙ; p2/p0 := andn заливкой (швы чёрные).
;  SWAP ауры: лица не во все три плоскости (idx14 = мерцание).
vsc_leaf:
	ld	(vsc_pg), a
	ld	a, h
	ld	(vsc_own), a
	ld	a, b
	ld	(vsc_nc0), a
	ld	l, 0x97
	call	vsc_plane	; H = own
	ld	l, 0x9F
	call	vsc_andfill	; H ещё own
	ld	a, (vsc_own)
	ld	h, a
	ld	l, 0x9B
	call	vsc_andfill
	ret	; не vec_hero_redraw: створка обязана накрыть героя (MSX SAT 0-3)
vsc_andfill:
	ld	c, (hl)
	ld	a, c
	or	a
	ret	z
	ld	a, (vsc_nc0)
	ld	b, a
	ld	d, h	; страница слота (вызывающий держит own в H)
	ld	e, 0x0A0
	jp	vsb_andn
vsc_plane:
	ld	c, (hl)
	ld	a, c
	or	a
	ret	z
	ld	a, (vsc_nc0)
	ld	(vsb_nc), a
	ld	b, c
	ld	a, (vsc_own)
	ld	h, a
	ld	l, 0x0A0
	ld	a, (vsc_pg)
	ld	d, a
	ld	e, 0x0A0
vsc_merge:
	ld	a, (vsb_lo)
	ld	c, a
	ld	a, 16
	ld	(vsc_k), a
vsc_ln:
	ld	a, (bc)
	cpl
	or	(hl)
	cpl
	ex	de, hl
	or	(hl)
	ex	de, hl
	ld	(bc), a
	inc	hl
	inc	de
	inc	c
	ld	a, (vsc_k)
	dec	a
	ld	(vsc_k), a
	jp	nz, vsc_ln
	inc	b
	ld	a, (vsb_nc)
	dec	a
	ld	(vsb_nc), a
	jp	nz, vsc_merge
	ret
;  vsb_or: C=hi (плоскость+столбец), B=ncols, DE=буфер, (vsb_lo)=lo0. Столбец fb —
;  16 подряд байт внутри страницы (lo0 <= 240), буфер тоже подряд => обе адресации
;  через inc l / inc e, без переносов. Развёрнуто на 16 строк: счётчик строк стоил бы
;  15 тактов на байт, а это самый горячий код кадра (идёт под лучом).
vsb_or:
vsb_or1:
	ld	a, (vsb_lo)
	ld	l, a
	ld	h, c
	ld	a, (de)
	inc	e
	or	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	or	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	or	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	or	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	or	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	or	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	or	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	or	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	or	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	or	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	or	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	or	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	or	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	or	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	or	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	or	(hl)
	ld	(hl), a
	inc	c	; следующий столбец
	dec	b
	jp	nz, vsb_or1
	ret
;  ===== СЛИТАЯ ЗАПИСЬ (ЗАДАЧА#37 ШАГ 3, 2026-07-31) =================================
;  ЧТО ЭТО. Байт fb переходит из СТАРОГО содержимого сразу в НОВОЕ, ОДНОЙ записью:
;  fb := фон-из-слота OR спрайт. Ни стирания, ни сохранения фона — промежуточного
;  состояния, которое мог бы увидеть луч, НЕ СУЩЕСТВУЕТ. Это и есть «подготовить в тени,
;  а потом быстро вывести»: сдвинутый спрайт собран в буфер ещё в тике, фон уже лежит в
;  слоте, здесь остаётся только сложить их прямо в экран.
;  ПОЧЕМУ ЭТО НЕ СНЯТЫЙ vso_fast. Тот падал на объектах, ДЕЛЯЩИХ ПЛОСКОСТЬ: пара героя
;  писала p2 дважды, и второй подставлял вместо вклада первого свой фон (шлейф). Теперь
;  общая плоскость пары СЛИТА В ОДИН БУФЕР ещё в подготовке (vsd_dropb), поэтому каждую
;  плоскость пишет ровно один объект, и вся пачка допускается к слитой записи только
;  после попарной проверки (vsp_fastmark): совпала плоскость и пересеклись габариты —
;  идём старым путём.
;  ЦЕНА: 48 тактов на байт против 22 (стирание) + 22 (сейв) + 40 (OR-вывод) = 84.
;  vsb_merge: H=страница слота, L=6 (фон), D=H, E=0xA0 (спрайт), B=hi0 (страница fb),
;  (vsb_lo)=lo0, (vsb_nc)=ncols. Столбец fb — 16 подряд байт внутри страницы, фон и
;  спрайт в слоте тоже подряд => все три указателя идут через inc. Развёрнуто на 16
;  строк: это самый горячий код кадра.
;  ЗАДАЧА#38: тело ОДНОГО столбца выделено в vsb_mcol — его же вызывает вперемежку
;  чередованная запись пары (vpr_wr). Цена разреза — call/ret на столбец (27 тактов).
;  ===== ЗАДАЧА#53 (2026-08-07): СТЕК-БЛИТ ЗАПИСИ СПРАЙТА В ПАЧКЕ ====================
;  ЗАМЕР (tools/verify/pack_write_bench.js, реальные такты Вектора — машинный цикл добит
;  до 4 тактов, поэтому `inc l` стоит 8, а не 5): пересылка буфера в fb стоит
;    ld a,(de) / ld (bc),a / inc e / inc c            = 32 т/байт  (прежний vsz_mcol)
;    pop de / ld (hl),e / inc l / ld (hl),d / inc l   = 22 т/байт  (стек-блит)
;  POP берёт ДВА байта источника за один машинный цикл-тройку — это и есть весь выигрыш;
;  ни эмита, ни ОЗУ под код он не требует (компилированный блиттер выигрывает ещё 7 т/байт,
;  но берёт за них 63 такта ТИКА на байт — отвергнут арифметикой, см. шапку бенча).
;  ПОЧЕМУ ПЕТЛЯ, А НЕ ЯДРО-ПОДПРОГРАММА. SP-хайджек стоит 40 тактов на shld/lhld плюс
;  di/ei; если платить их НА КАЖДЫЙ СТОЛБЕЦ, весь выигрыш съедается (516 т против 560 т
;  у vsz_mcol — считано до правки). Поэтому хайджек поднят на уровень ОБЪЕКТА, а внутри
;  него call/ret ЗАПРЕЩЕНЫ (SP держит буфер) — тело столбца обязано быть встроенным.
;  Отсюда форма: одна петля обслуживает и одиночный объект, и ЧЕРЕДОВАННУЮ ПАРУ героя,
;  вторая половина отключается операндом vpz_jb (тот же приём, что vsm_d2 у плоскостей).
;  ПРАВИЛА ХАЙДЖЕКА (те же, что у vec_su_save/vec_su_restore, vec_saveunder.asm): DI на
;  весь хайджек, запрет call/push, SP восстановить на ВСЕХ путях (путь здесь ровно один —
;  петля не имеет досрочных выходов), безусловный ei в конце. Пачка зовётся и с ГЛУБИНЫ 2
;  (вложенное прерывание) — под DI это безопасно ровно так же, как у vsu_*: реентерантности
;  нет, потому что внутрь хайджека прерывание не входит.
;  БУФЕРЫ СТОЛБЦОВ СПРАЙТА ЛЕЖАТ ПОДРЯД (0xA0+16c), но SP всё равно перезаряжается на
;  каждой половине столбца: у пары половины живут в РАЗНЫХ слотах.
;  vpz_pair: вход для пары. vpr_pa/vpr_pb — страницы слотов, vpr_ha/vpr_hb — страницы fb
;  первого столбца каждого; столбцы и lo0 у пары ОБЩИЕ (это и есть условие пары), поэтому
;  дельта страниц fb постоянна и раскладывается операндом.
vpz_pair:
	ld	a, (vpr_pa)
	ld	(vpz_pa+1), a
	ld	a, (vpr_pb)
	ld	(vpz_pb+1), a
	ld	hl, vpz_bh	; вторая половина ВКЛЮЧЕНА (метка для стендов/гейтов; пишет обе vpz_f2)
	ld	(vpz_jb+1), hl
	ld	hl, vpz_f2	; столбец пары: обе плоскости ЧЕРЕДУЯСЬ по 4 строки (см. vpz_f2)
	ld	(vpz_cf+1), hl
	ld	a, (vpr_ha)
	ld	b, a	; B = страница fb столбца первого объекта
	ld	a, (vpr_hb)
	sub	b
	ld	(vpz_d+1), a	; ОПЕРАНД: hi0(B) - hi0(A), постоянна по столбцам
	jp	vpz_wr
;  vsz_merge: одиночный объект с ЗАВЕДОМО НУЛЕВЫМ ФОНОМ (ЗАДАЧА#49: блок фона в слоте
;  целиком нулевой у геймплейных объектов в 98-100% выводов — «фон OR спрайт» = спрайт).
;  Вход прежний: H = страница слота, B = hi0, (vsb_lo) = lo0, (vsb_nc) = ncols. DE/L,
;  которые готовил vsm_wr, стек-блиту не нужны — он адресует буфер через SP.
vsz_merge:
	ld	a, (vsb_lo)
	cp	240
	jp	nc, vsb_mrow	; PUSH из SP=0 уходит на предыдущую страницу
	ld	a, h
	ld	(vpz_pa+1), a
	ld	hl, vpz_ce	; вторая половина ВЫКЛЮЧЕНА
	ld	(vpz_jb+1), hl
	ld	hl, vpz_fast
	ld	(vpz_cf+1), hl
;  vpz_wr: общая часть. B = страница fb первого столбца, операнды разложены.
;  Столбец: POP 16 бит из буфера, PUSH 16 бит в fb. По 4 байта (HL+DE), без AF:
;  i8080 в F фиксирует биты, PUSH AF портил маску спрайта (шлейф героя и зелёной мумии).
;  lo0 < 240 — иначе PUSH переходит через адрес 0 (см. vpr_or).
vpz_wr:
	ld	c, 0x0A0	; C = смещение столбца спрайта в слоте
	di	; === начало SP-хайджека ===
vpz_col:
vpz_pa:
	ld	h, 0	; ОПЕРАНД: страница слота объекта A
	ld	a, b	; A = страница fb
vpz_cf:
	call	vpz_fast	; ОПЕРАНД: vpz_fast (одиночный) / vpz_f2 (пара: обе плоскости, возврат в vpz_ce)
vpz_jb:
	jp	vpz_bh	; ОПЕРАНД: vpz_bh (пара) / vpz_ce (одиночный объект)
vpz_bh:
vpz_pb:
	ld	h, 0	; ОПЕРАНД: страница слота объекта B
	ld	a, b
vpz_d:
	add	a, 0	; ОПЕРАНД: дельта страниц fb между половинами пары
	call	vpz_fast
vpz_ce:
	ld	a, c	; следующий столбец: буфер +16, страница fb +1
	add	a, 16
	ld	c, a
	inc	b
	ld	a, (vsb_nc)
	dec	a
	ld	(vsb_nc), a
	jp	nz, vpz_col
	ei
	jp	vtm_afterdraw
;  H = слот, A = fb, C = смещение столбца. B,C сохраняет. 4 залпа HL/DE, без AF.
vpz_fast:
	ld	(vpz_dh+1), a
	ld	a, (vsb_lo)
	add	a, 4
	ld	(vpz_dl+1), a
	ld	a, h
	ld	(vpz_sh+1), a
	ld	a, b
	ld	(vpz_svb+1), a
	ld	hl, 0
	add	hl, sp
	ld	(vpz_sp), hl
	ld	a, c
	ld	(vpz_sl+1), a
	ld	b, 4
vpz_lp:
vpz_sh:
	ld	h, 0
vpz_sl:
	ld	l, 0
	ld	sp, hl
	pop	hl
	ld	(vpz_th), hl
	pop	de
	ld	a, (vpz_sl+1)
	add	a, 4
	ld	(vpz_sl+1), a
vpz_dh:
	ld	h, 0
vpz_dl:
	ld	l, 0
	ld	sp, hl
	push	de
	ld	hl, (vpz_th)
	push	hl
	ld	a, (vpz_dl+1)
	add	a, 4
	ld	(vpz_dl+1), a
	dec	b
	jp	nz, vpz_lp
vpz_svb:
	ld	b, 0
	ld	hl, (vpz_sp)
	ld	sp, hl
	ret
vpz_th:
	dw	0
;  ===== ПОСТРОЧНАЯ СЛИТАЯ ЗАПИСЬ (ЗАДАЧА#53, 2026-08-05) ============================
;  ЗАЧЕМ. Владелец с железа: «мерцание уходит, если сдвинуть поле вниз» (сдвиг даёт пачке
;  +6144 такта до луча). Замер beam_late подтвердил: транзиент 2968 пикс / 11 объектов
;  против 176 / 1. Транзиент — это «луч прошёл над объектом, пока строка была разобрана».
;  А разобрана она потому, что запись идёт ПО СТОЛБЦАМ: столбец = 16 байт одной страницы,
;  то есть вертикальная полоса. Строка fb шириной ncols дописывается только к концу
;  объекта, и всё это время луч может застать её наполовину старой.
;  ЗАПИСЬ ПО СТРОКАМ закрывает строку целиком, прежде чем перейти к следующей: луч видит
;  либо старую строку, либо новую, но никогда смесь. Это же снимает запрет на
;  ГОРИЗОНТАЛЬНЫЙ ПЕРЕЕЗД габарита (шаг 5 задачи#37 откатили именно из-за столбцовой
;  записи — см. разбор выше), а он даёт 29.8% пачек, уходящих сейчас на медленный путь.
;  ЦЕНА. Буфер фона и буфер спрайта лежат в слоте ПО СТОЛБЦАМ (16 подряд), поэтому внутри
;  строки указатели идут с шагом 16, а не через inc. Замер прототипа — в задаче #53.
;  КОНТРАКТ ВХОДА тот же, что у vsb_merge: B = страница fb первого столбца, (vsb_lo) = lo0,
;  (vsb_nc) = ncols, HL = слот:база блока фона, DE = слот:база спрайта.
vsb_mrow:
	ld	a, b
	ld	(vsb_b0), a	; страница первого столбца — её возвращаем на каждой строке
	ld	a, l
	ld	(vsb_l0), a	; смещение блока фона на начале строки
	ld	a, (vsb_lo)
	ld	c, a	; C = строка fb
	add	a, 16
	ld	(vsb_ke), a	; строка, на которой объект кончается
vsb_rl:
	ld	a, (vsb_nc)
	ld	(vsb_ci), a
vsb_cl:
	ld	a, (de)
	or	(hl)
	ld	(bc), a	; байт строки готов ОКОНЧАТЕЛЬНО
	inc	b	; следующий столбец: страница fb +1, буферы +16
	ld	a, l
	add	a, 16
	ld	l, a
	ld	a, e
	add	a, 16
	ld	e, a
	ld	a, (vsb_ci)
	dec	a
	ld	(vsb_ci), a
	jp	nz, vsb_cl
;  строка дописана: вернуть fb на первый столбец, буферы — на начало строки + 1
	ld	a, (vsb_b0)
	ld	b, a
	ld	a, (vsb_l0)
	inc	a
	ld	(vsb_l0), a
	ld	l, a
	add	a, 0x0A0-6	; спрайт = 0xA0 + (смещение фона - 6): базы отличаются константой
	ld	e, a
	inc	c	; следующая строка fb
	ld	a, (vsb_ke)
	cp	c
	jp	nz, vsb_rl
	jp	vtm_afterdraw
vsb_merge:
	call	vsb_mcol
	inc	b	; следующий столбец
	ld	a, (vsb_nc)
	dec	a
	ld	(vsb_nc), a
	jp	nz, vsb_merge
	ret
;  vsb_mcol: ОДИН столбец. На выходе L и E продвинуты на 16 (следующий столбец слота).
vsb_mcol:
	ld	a, (vsb_lo)
	ld	c, a
	ld	a, (de)
	or	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, (de)
	or	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, (de)
	or	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, (de)
	or	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, (de)
	or	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, (de)
	or	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, (de)
	or	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, (de)
	or	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, (de)
	or	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, (de)
	or	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, (de)
	or	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, (de)
	or	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, (de)
	or	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, (de)
	or	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, (de)
	or	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, (de)
	or	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ret
;  vsn_col: та же слитая запись, но спрайт ГАСИТ плоскость: fb := фон AND NOT спрайт.
;  Ею идут дополнительные плоскости непрозрачной мумии (ЗАДАЧА#41) и спрайтов карты
;  долины. Вход и выход — ТОТ ЖЕ КОНТРАКТ, ЧТО У vsb_mcol (ОДИН столбец): H = страница
;  слота, L = база столбца фона этой плоскости, D = H, E = смещение столбца спрайта,
;  B = её страница fb, (vsb_lo) = lo0; на выходе L и E продвинуты на 16.
;  СЧЁТЧИКА СТРОК НЕТ: буфер спрайта начинается с 0xA0, столбец занимает 16 байт, значит
;  конец столбца — это (E & 0x0F) == 0. Развёрнуто по 2 строки: тело гашения на байт
;  дороже тела OR (нужен cpl), а кода на полный анролл 16 строк нет в бюджете.
;  ЦЕНА: 51 такт на байт против 83 у старого пути (стирание 22 + сейв 22 + vsb_andn 39).
;  ШАГ D (2026-08-04): петля ПО СТОЛБЦАМ отсюда убрана — гасящая плоскость больше не
;  выводится целиком подряд, её столбцы чередуются со столбцами остальных плоскостей
;  объекта (см. vsm_cw). Единственным вызывающим стал этот цикл.
vsn_col:
	ld	a, (vsb_lo)
	ld	c, a
vsn_r:
	ld	a, (de)
	cpl
	and	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, (de)
	cpl
	and	(hl)
	ld	(bc), a
	inc	l
	inc	e
	inc	c
	ld	a, e
	and	0x0F
	jp	nz, vsn_r
	ret
;  vso_merge1: вывести объект vec_nsp_idx слитой записью (геометрия — из записи вывода).
;  Габарит мог УЕХАТЬ ПО ВЕРТИКАЛИ с прошлого кадра (это 87% всех несовпадений, см.
;  vsm_shift) — тогда фон в слоте сначала сдвигается на d строк, а дальше идёт та же
;  одна запись на байт.
;  ===== ШАГ C: МНОГОПЛОСКОСТНЫЙ ОБЪЕКТ (2026-08-03) ================================
;  ЗАЧЕМ. Объект может писать НЕСКОЛЬКО плоскостей: hi0 (всегда), hi0b (+0x9F) и hi0c
;  (+0x9B). У непрозрачной мумии обе дополнительные ГАСЯТ (ЗАДАЧА#41), у спрайтов карты
;  долины — тоже, у dual-спрайта (p1 с дублем в p2) hi0b РИСУЕТ. До шага C любой такой
;  объект уводил ВСЮ пачку на старый путь, и это была самая частая причина отказа —
;  284 объекта из 492 негодных, то есть половина оставшегося мерцания.
;  КАК. Плоскость A (hi0) идёт ПРЕЖНИМ путём, БЕЗ единого лишнего такта на объект — она
;  же и единственная у 95% объектов. Дополнительные плоскости выводятся тем же по смыслу
;  кодом (с шага D — чередуясь с ней по столбцам, vsm_cw). У каждой плоскости:
;    - свой блок фона в слоте: блоки идут подряд по 16*ncols байт в порядке hi0 -> hi0b
;      -> hi0c (ровно так их кладёт vec_su_save и так же читает стирание) — курсор блока
;      в vsm_bb, а начало следующего блока даёт сама запись: L после vsb_merge стоит ровно
;      за последним столбцом;
;    - своя страница fb (vsm_hp);
;    - ОБЩИЙ буфер спрайта (+0xA0): гасящая плоскость гасится ТЕМ ЖЕ силуэтом.
;  Сдвиг габарита по вертикали делается ДЛЯ КАЖДОЙ плоскости отдельно (её блок фона живёт
;  своей жизнью), а направление сдвига и |d| считаются один раз на объект (vsm_dir) — как
;  и переезд шапки слота на новый lo0.
;  ЦЕНА ШАГА C ДЛЯ ОДНОПЛОСКОСТНОГО ОБЪЕКТА — 5 инструкций (~64 такта): сохранить курсор
;  блока и проверить, есть ли hi0b/hi0c. Первая редакция гоняла ЛЮБОЙ объект через общий
;  обход плоскостей и стоила +1101 такт на пачку (замер по игровым тикам, 812 пачек,
;  которые и до шага C шли слитой записью) — то есть съедала весь выигрыш.
;  ИНВАРИАНТ ПРЕЖНИЙ: каждый байт fb пишется РОВНО ОДИН РАЗ и сразу окончательным
;  значением — ни стирания, ни пересохранения фона нет и у дополнительных плоскостей.
;  ===== ЗАДАЧА#49 (2026-08-04): ПУСТОЙ ФОН — НИ СДВИГА БЛОКА, НИ ЧТЕНИЯ СЛОТА ========
;  ИДЕЯ ВЛАДЕЛЬЦА: «не сохранять под героем поле, а восстанавливать из карты тайлов —
;  он вроде с мумиями не пересекается». Буквальная форма мертва арифметикой (клетка
;  кирпича = 1308 тактов блита, герой накрывает 4-9 клеток, а весь save-under кадра 1586),
;  но рабочая форма — та же по сути: ЕСЛИ ФОН ПОД ГАБАРИТОМ НУЛЕВОЙ, его не надо ни
;  двигать, ни читать.
;  ЗАМЕР (tools/verify/su_empty_census.js, 6000 кадров геймплея): блок фона в слоте у
;  геймплейных объектов ЦЕЛИКОМ НУЛЕВОЙ в 100% выводов слитой записи (герой 468/468,
;  мумии 147/147) — спрайт ровно в рост коридора, кирпичи лежат СТРОГО вне габарита, да
;  и тайлы поля живут в p0/p1, а герой с мумиями пишут p1/p2. То же по силуэту: у мумии
;  под ним чёрный фон в 94.7% пикселей (momia_hidden), у ножа в 96.2% (knife_purity).
;  ДВА СЛЕДСТВИЯ, оба под лучом:
;    1) сдвиг блока (фаза 2 vsm_ph3: 1334 такта у героя, 1167 у мумии = 36% цены сдвига)
;       над нулями — ТОЖДЕСТВО, его не делаем вовсе;
;    2) «фон OR спрайт» при нулевом фоне = спрайт: ядро столбца становится vsz_mcol,
;       24 такта на байт вместо 36.
;  ПРИЗНАК — ZFLAG слота (+0xD1). Его считает ЗАНОВО КАЖДЫЙ ТИК vsp_fastmark (vfm_zs)
;  прямым OR всего блока, а снимают три писателя блока: vec_su_save (положил свежий фон),
;  добор края vsm_p3 (притащил ненулевые байты) и слияние sticky (vec_su_fixup переписал
;  клетку). Читает его ТОЛЬКО слитая запись, а она идёт лишь когда ВСЕ объекты пачки
;  прошли vsp_fastmark в ЭТОМ тике, — протухнуть флаг не может.
;  ГЕЙТ vfl_dany: fixup мог переписать блок ПОСЛЕ подготовки этого кадра (порядок тика:
;  updateSprites -> логика -> блиты), а sticky сливается лишь в подготовке СЛЕДУЮЩЕГО
;  тика — то есть уже после этой пачки. Пока vfl_dany взведён, ZFLAG не верим.
;  ЗАМЕР ЭФФЕКТА (детерминированный A/B по игровым тикам, beam_ab 2600 тиков — обе сборки
;  играют ОДНУ И ТУ ЖЕ игру, 1602 кадра геймплея, 2207 объектов):
;    КОНЕЦ ПАЧКИ avg 19521 -> 18091, p50 17472 -> 15008 (-14.1%), p90 33052 -> 31248;
;    «позже луча» мумии 13.6% -> 10.7%, герой 4.4% -> 4.4%;
;    ТРАНЗИЕНТ 13368 -> 13552 пикс (в пределах шума), beam_color: окно между плоскостями
;      avg 6053 -> 5939, луч внутри 3.44% -> 3.25%, «показан старый цвет» 2863 -> 2125;
;    ПЛАВНОСТЬ НЕ ТРОНУТА: кадров на ту же игру 4764 -> 4767 (+0.06%), тик длиннее кадра
;      51.7% -> 51.6%.
;    КАРТИНКА НЕ ИЗМЕНИЛАСЬ: coltab_frame_parity, 259 контрольных тиков — p0/p1/p2 и
;      палитра совпадают БАЙТ В БАЙТ на каждом тике.
;  ОТВЕРГНУТАЯ РЕДАКЦИЯ (замерена, не гадание): копить OR прямо в POP-хайджеке
;  vec_su_save — там байты и так читаются, всего +4 такта на байт. НО сейв идёт МЕЖДУ
;  проходом стирания и выводом, поэтому удлиняет окно «объект разобран» КАЖДОМУ объекту
;  СТАРОГО пути, который от приёма ничего не получает: транзиент 13368 -> 16224 пикс и
;  door_leaf_purity краснел «герой просвечивает сквозь створку» (1.7%). Перенос счёта в
;  тик (vfm_zs) снял и то, и другое.
vso_merge1:
	call	vec_su_ptr
	ld	l, 0x99
	ld	a, (hl)
	ld	(vsb_nc), a
	or	a	; СТРАХОВКА: ncols=0 -> петля ушла бы на 256 столбцов
	ret	z
	ld	l, 0x0D1	; ZFLAG слота: блок фона целиком нулевой?
	ld	a, (hl)
	ld	e, a
	ld	a, (vfl_dany)	; fixup лазил в слоты после подготовки -> ZFLAG не верим
	or	a
	ld	a, 0	; MVI флаги не трогает
	jp	nz, vsm_z0
	ld	a, e
vsm_z0:
	ld	(vsm_z), a
	ld	l, 0x98
	ld	a, (hl)
	ld	(vsb_lo), a
	ld	l, 2	; lo0 ШАПКИ: строка, под которой сейчас лежит сохранённый фон
	sub	(hl)
	ld	(vsm_d), a	; d нужен и дополнительным плоскостям — кладём на обоих путях
	jp	nz, vsm_shift	; габарит уехал на d строк -> подвинуть фон в слоте
	ld	l, 1	; ЗАДАЧА#53 ОСТАТОК: строки на месте, но габарит мог уехать по
	ld	a, (hl)	; СТОЛБЦАМ или сменить ШИРИНУ — это тоже сдвиг блока фона
	ld	l, 0x97
	cp	(hl)
	jp	nz, vsm_shift
	ld	l, 3
	ld	a, (hl)
	ld	l, 0x99
	cp	(hl)
	jp	nz, vsm_shift
vsm_wr:
	ld	l, 0x97
	ld	b, (hl)	; B = hi0 (страница fb первого столбца)
	ld	a, (vpr_def)	; ЗАДАЧА#38: пара -> запись отложена, сюда кладём её адреса
	or	a	; (пара всегда одноплоскостная — см. vsp_fastmark)
	jp	nz, vpr_save
	ld	l, 0x9F	; есть ли у объекта плоскости B/C?
	ld	a, (hl)
	ld	l, 0x9B
	or	(hl)
	jp	nz, vsm_multi
	ld	d, h	; ОДНОПЛОСКОСТНЫЙ (95% объектов) — прежний путь, ноль лишних
	ld	e, 0x0A0	; тактов: те же два чтения записи вывода стояли и раньше,
	ld	l, 6	; только ПОСЛЕ записи
	ld	a, (vsm_z)	; ЗАДАЧА#49: фон нулевой -> писать спрайт БЕЗ чтения слота
	or	a
	jp	nz, vsz_merge
;  ЗАДАЧА#53: ПОСТРОЧНОЕ ядро вместо столбцового (разбор — у vsb_mrow выше).
	jp	vsb_mrow
;  ===== ШАГ D (2026-08-04): ПЛОСКОСТИ ОДНОГО ОБЪЕКТА ЧЕРЕДУЮТСЯ ПО СТОЛБЦАМ ==========
;  ДЕФЕКТ С ЖЕЛЕЗА: «мерцание в верхних строках лабиринта». Цвет пикселя на Векторе —
;  КОМБИНАЦИЯ битов p0/p1/p2, и пока записана одна плоскость, а вторая нет, луч показывает
;  цвет, которого нет ни в старом кадре, ни в новом. Байтовые метрики (beam_late/beam_tear)
;  к этому слепы: каждый байт записан один раз и правильным значением.
;  ЗАМЕР (beam_color.js + атрибуция окна по PC, 2600 игровых тиков): окно между первой и
;  последней записью ОДНОГО пикселя avg 7169 тактов; из 1938 попаданий луча ВНУТРЬ окна
;  837 (43%) дала пара vsb_mcol -> vsn_r — то есть МНОГОПЛОСКОСТНЫЙ объект слитой записи.
;  Шаг C выводил его плоскости ОДНУ ЗА ДРУГОЙ (вся A, потом вся B, потом C), да ещё и с
;  фазами сдвига следующей плоскости МЕЖДУ ними: среднее окно 8594 такта = 45 строк луча.
;  ЧТО СДЕЛАНО (то же лекарство, что у пары героя в ЗАДАЧЕ#38, только ВНУТРИ объекта):
;  сначала для ВСЕХ плоскостей делаются фазы сдвига (хвост -> сдвиг блока -> добор края),
;  а потом запись идёт СТОЛБЕЦ ЗА СТОЛБЦОМ, и внутри столбца — все плоскости подряд:
;  A.столбец0, B.столбец0, C.столбец0, A.столбец1, ... Окно между плоскостями одного
;  пикселя схлопывается до ОДНОГО столбца (16 байт x 48 тактов = 768 тактов, 4 строки
;  луча) независимо от того, сколько у объекта столбцов.
;  ПОЧЕМУ ЭТО БЕЗОПАСНО. Плоскости объекта — РАЗНЫЕ страницы fb, общих байт у них нет,
;  поэтому порядок записей между плоскостями не значит ничего: каждый байт по-прежнему
;  пишется ровно один раз и сразу окончательным значением, а гашение (AND NOT) и рисование
;  (OR) местами не меняются — они всегда идут в РАЗНЫЕ плоскости. Фазы сдвига переставлять
;  тоже можно: фаза 1 пишет в fb только СВОЮ плоскость, фаза 3 читает из fb только СВОЮ.
;  ЦЕНА: ~50 тактов на плоскость-столбец (перезарядка страницы fb и базы блока фона —
;  та же цена, что у чередования пары) + разбор плоскостей на объект. Одноплоскостный
;  объект не платит НИЧЕГО: он сюда не заходит.
;  РАСКЛАДКА БЛОКОВ ФОНА В СЛОТЕ: подряд по 16*ncols байт в порядке hi0 -> hi0b -> hi0c,
;  ОТСУТСТВУЮЩИЕ пропущены (ровно так их кладёт vec_su_save). Поэтому доп. плоскости
;  собираются в тот же порядок, а шаг между блоками один и тот же — S = 16*ncols.
vsm_multi:
	ld	d, h	; D = страница слота на весь разбор (vsm_addp её возвращает)
	ld	a, h
	ld	(vsm_pg), a	; при d=0 vsm_shift не звался — страницу слота кладём здесь
	ld	a, b
	ld	(vsm_hp), a	; страница fb ПОСЛЕДНЕЙ подключённой плоскости (пока hi0);
	ld	a, (vsb_nc)	; она же вход фаз сдвига, поэтому ячейка одна
	add	a, a	; S = 16*ncols: шаг между блоками фона соседних плоскостей
	add	a, a
	add	a, a
	add	a, a
	ld	(vsm_bs), a
	add	a, 6
	ld	(vsm_bb), a	; блок первой ДОП. плоскости (у hi0 блок всегда 6)
	sub	22	; ОПЕРАНД обоих блоков: с блока прошлой плоскости на блок
	ld	(vsm_b1+1), a	; этой, ТОТ ЖЕ столбец (vsb_mcol оставляет L ЗА столбцом)
	ld	(vsm_b2+1), a
	ld	a, 0x0C3	; блок 2 по умолчанию ВЫКЛЮЧЕН: его первые три байта
	ld	(vsm_d2), a	; (`ld a,b` + `add a,dp`) заняты ровно под `jp vsm_ce`
	ld	hl, vsm_ce
	ld	(vsm_d2+1), hl
	ld	hl, vsm_d1	; HL = блок операндов для следующей доп. плоскости
	ld	e, 0x9F	; --- hi0b: РИСУЕТ (dual) или ГАСИТ (мумия, карта) ---
	ld	a, (de)
	or	a
	jp	z, vsm_mc
	ld	e, 0x0D0	; ЗАДАЧА#41: признак «hi0b не рисует, а ГАСИТ»
	ld	a, (de)
	or	a
	ld	e, 0x9F
	ld	a, (de)
	ld	de, vsb_mcol
	jp	z, vsm_mb
	ld	de, vsn_col
vsm_mb:
	call	vsm_addp
	ld	hl, vsm_d2	; следующая доп. плоскость — во второй блок
vsm_mc:
	ld	e, 0x9B	; --- hi0c: ГАСИТ всегда (створка ворот, мумия, карта) ---
	ld	a, (de)
	or	a
	jp	z, vsm_mgo	; второй доп. плоскости нет — блок 2 так и остался выключен
	ld	c, a
	ld	a, l	; блок 1 уже занят hi0b -> ВКЛЮЧИТЬ блок 2: вернуть на
	cp	vsm_d1&255	; место `ld a,b` + `add a,`
	jp	z, vsm_mc2
	push	hl
	ld	hl, 0x0C678
	ld	(vsm_d2), hl
	pop	hl
vsm_mc2:
	ld	a, c
	ld	de, vsn_col
	call	vsm_addp
vsm_mgo:
	ld	h, d	; H = D = страница слота (их ждут ядра столбца)
	ld	l, 0x97
	ld	c, (hl)	; C = hi0 = страница плоскости 0
	ld	a, (vsm_hp)	; ОПЕРАНД возврата: с последней плоскости на плоскость 0
	ld	e, a	; СЛЕДУЮЩЕГО столбца, то есть 1 - (page_last - page_0)
	ld	a, c
	sub	e
	inc	a
	ld	(vsm_dr+1), a
	ld	a, (vsm_bb)	; ОПЕРАНД возврата по блокам: -(число доп. плоскостей)*S
	ld	e, a	; = (6+S) - курсор блока (курсор ушёл на S за каждую доп.)
	ld	a, (vsm_bs)
	add	a, 6
	sub	e
	ld	(vsm_br+1), a
	ld	b, c	; --- поехали: плоскость 0, столбец 0 ---
	ld	e, 0x0A0
	ld	l, 6
;  vsm_cw: ОДИН СТОЛБЕЦ ВСЕМИ ПЛОСКОСТЯМИ ПОДРЯД. B = страница fb столбца текущей
;  плоскости, L = её блок фона, E = столбец спрайта (общий у всех плоскостей), H = D =
;  страница слота (vsb_mcol/vsn_col их не трогают). Дельты между плоскостями — операнды,
;  их разложил vsm_addp; блок отсутствующей второй доп. плоскости перепрыгнут.
vsm_cw:
	call	vsb_mcol	; плоскость 0 (hi0) — она всегда РИСУЕТ
vsm_d1:
	ld	a, b	; --- первая доп. плоскость (её страница fb) ---
	add	a, 0	; ОПЕРАНД: page1 - page0
	ld	b, a
	ld	a, l
vsm_b1:
	add	a, 0	; ОПЕРАНД: S-16 (блок этой плоскости, ТОТ ЖЕ столбец)
	ld	l, a
	ld	a, e
	sub	16	; спрайт общий — вернуть на начало столбца
	ld	e, a
	call	vsb_mcol	; ОПЕРАНД (vsm_d1+13): vsb_mcol рисует / vsn_col гасит
vsm_d2:
	ld	a, b	; --- вторая доп. плоскость (нет -> здесь стоит jp vsm_ce) ---
	add	a, 0	; ОПЕРАНД: page2 - page1
	ld	b, a
	ld	a, l
vsm_b2:
	add	a, 0	; ОПЕРАНД: S-16
	ld	l, a
	ld	a, e
	sub	16
	ld	e, a
	call	vsb_mcol	; ОПЕРАНД (vsm_d2+13)
vsm_ce:
	ld	a, b	; --- столбец кончился: назад на плоскость 0, столбец +1 ---
vsm_dr:
	add	a, 0	; ОПЕРАНД: 1 - (page_last - page_0)
	ld	b, a
	ld	a, l
vsm_br:
	add	a, 0	; ОПЕРАНД: -(число доп. плоскостей)*S
	ld	l, a
	ld	a, (vsb_nc)
	dec	a
	ld	(vsb_nc), a
	jp	nz, vsm_cw
	jp	vtm_afterdraw	; MASK/F5: мульти-плоскость шла в ret без afterdraw

;  vsm_addp: подключить доп. плоскость к чередованию. A = её страница fb, HL = база её
;  блока операндов (vsm_d1/vsm_d2), DE = ядро столбца (vsb_mcol рисует / vsn_col гасит).
;  Здесь же идут фазы сдвига ЭТОЙ плоскости — до того, как начнётся запись хоть одной
;  (иначе окно между плоскостями снова растянулось бы на весь сдвиг).
vsm_addp:
	ld	c, a
	ld	a, (vsm_hp)	; страница ПРЕДЫДУЩЕЙ плоскости
	ld	b, a
	ld	a, c
	ld	(vsm_hp), a	; теперь текущая — её ждут фазы сдвига
	sub	b	; ОПЕРАНД: дельта страницы fb от предыдущей плоскости
	inc	hl
	inc	hl
	ld	(hl), a
	ld	bc, 11	; ОПЕРАНД ядра столбца лежит в блоке на +13
	add	hl, bc
	ld	(hl), e
	inc	hl
	ld	(hl), d
	ld	a, (vsm_d)	; габарит уехал -> хвост, сдвиг фона в блоке, добор края
	or	a
	call	nz, vsm_ph3
	ld	a, (vsm_bs)	; курсор блока -> следующая плоскость
	ld	c, a
	ld	a, (vsm_bb)
	add	a, c
	ld	(vsm_bb), a
	ld	a, (vsm_pg)	; фазы сдвига сломали D — вернуть страницу слота вызывающему
	ld	d, a
	ret
;  vpr_save: страница слота и hi0 -> vpr_pa/ha (первый пары) или vpr_pb/hb (второй).
;  vpr_def держит ПРЯМО младший байт адреса пары ячеек — выбор без ветвления.
vpr_save:
	ld	l, a
	ld	a, h
	ld	h, 0
	ld	(hl), a
	inc	l
	ld	(hl), b
;  ЗАДАЧА#53 (2026-08-07): вместо выбора ядра столбца — СЧЁТЧИК ГОДНОСТИ ПАРЫ. Флаг
;  нулевого фона у половин пары СВОЙ У КАЖДОЙ (плоскости-то разные: кожа в p1, одежда в
;  p2), а стек-блит пишет спрайт БЕЗ чтения слота — значит он годен, только если фон
;  нулевой У ОБЕИХ. Обнуляет счётчик vmxp перед подготовкой пары, здесь он лишь растёт:
;  vpz_ok = 2 на входе в vpr_wr и означает «обе половины доказали нулевой фон». Так
;  надёжнее флага-И: половина, чья подготовка вообще не дошла сюда (ncols=0), счётчик не
;  наберёт, и пара уйдёт запасным путём, а не с протухшим признаком.
	ld	a, (vsm_z)
	or	a
	ret	z
	ld	hl, vpz_ok
	inc	(hl)
	ret
;  ===== СЛИТАЯ ЗАПИСЬ СО СДВИГОМ ПО ВЕРТИКАЛИ (ЗАДАЧА#37 ШАГ 4, 2026-08-01) =========
;  ЗАЧЕМ. Слитая запись (шаг 3) требовала, чтобы габарит СОВПАЛ с прошлым кадром: фон в
;  слоте обязан покрывать ровно то, куда пишем. Замер spr_same_footprint.js: не совпадает
;  у 67% объектов, и в 87% этих случаев отличается ТОЛЬКО lo0 — объект просто уехал на
;  1-2 строки по вертикали. Поэтому покрытие слитой записи стояло на 33% объектов, а
;  остальные пачки шли старым путём (стереть -> сохранить -> вывести), где строка живёт
;  разобранной тысячи тактов и луч показывает смесь кадров.
;  ИДЕЯ. Фон под новым габаритом СОБИРАЕТСЯ ИЗ ДВУХ ИСТОЧНИКОВ, и оба доступны:
;    - 16-|d| строк, общих со старым габаритом, уже лежат в слоте — их надо лишь
;      подвинуть внутри слота на d;
;    - |d| КРАЕВЫХ строк нового габарита лежат ВНЕ старого, то есть в fb там ЧИСТЫЙ фон
;      (объекта там в прошлом кадре не было) — читаем прямо из fb;
;    - |d| строк ХВОСТА старого габарита, которых в новом нет, закрываем фоном из слота.
;      Это ТОЖЕ финальное состояние байта, а не промежуточное: объекта там больше нет.
;  Итог прежний и главный: КАЖДЫЙ байт fb пишется РОВНО ОДИН РАЗ и сразу окончательным
;  значением. Ни стирания, ни пересохранения фона нет и здесь.
;  ПОЧЕМУ СДВИГ БЛОКА — ОДНА ЛИНЕЙНАЯ КОПИЯ. Данные слота идут столбцами по 16 байт
;  подряд, и новому столбцу c строка j нужна из старого столбца c строки j+d, то есть
;  new[16c+j] = old[16c+j+d] = old[i+d] — сдвиг ВСЕГО блока на d, без разбивки по
;  столбцам. Копируем всегда 48 байт (3 столбца): при ncols=2 третий столбец — мусорный
;  хвост слота, который никто не читает. Байты, куда сдвиг натащил соседний столбец,
;  ровно те, что тут же перезаписывает добор края из fb.
;  ПОРЯДОК ФАЗ ОБЯЗАТЕЛЕН: хвост читает старые байты слота, которые сдвиг затирает,
;  а добор края затирает те байты старого блока, из которых хвост берёт данные СЛЕДУЮЩЕГО
;  столбца. Поэтому сначала хвост по ВСЕМ столбцам, потом сдвиг, потом край.
;  ГЕЙТ |d| <= 15 СТОИТ В vsp_fastmark: при |d| >= 16 старый и новый габариты не
;  пересекаются вовсе, сдвигать в слоте нечего — такая пачка идёт старым путём.
;  ГЕЙТ КОРРЕКТНОСТИ: spr_resid_gate.js проверка D — после слитой пачки каждый байт fb в
;  габарите обязан равняться «фон-из-слота OR/AND NOT спрайт», причём фон берётся из слота
;  УЖЕ сдвинутого, а габарит — из шапки, которую vso_merge1 переводит на новый lo0.
;  ШАГ C: ВСЕ ТРИ ФАЗЫ РАБОТАЮТ НАД БЛОКОМ ОДНОЙ ПЛОСКОСТИ — базой служит vsm_bb, страницей
;  fb vsm_hp, и vso_merge1 зовёт vsm_shift отдельно для каждой плоскости объекта. Сдвиг
;  затягивает в конец блока байты СЛЕДУЮЩЕГО блока (а в последний — мусор за блоками) —
;  это те же |d| байт на столбец, что тут же перезаписывает добор края.
;  vsm_shift: вход ПЛОСКОСТИ A. Всё, что одно на объект (страница слота, старый lo0,
;  переезд шапки, направление сдвига), считается здесь; фазы 1-3 (vsm_ph3) работают уже
;  над блоком конкретной плоскости — их же зовёт vsm_addp для плоскостей B/C, ДО того как
;  начнётся запись хоть одной (шаг D: иначе сдвиг встал бы между плоскостями пикселя).
vsm_shift:
	ld	a, h
	ld	(vsm_pg), a
	ld	l, 2
	ld	a, (hl)
	ld	(vsm_lo), a	; lo0 СТАРОГО габарита (под ним лежит фон слота)
	ld	a, (vsb_lo)	; шапка слота переезжает на новый габарит: с этого момента
	ld	(hl), a	; и стирание, и vec_su_fixup описывают то, что нарисовано
;  ЗАДАЧА#53 ОСТАТОК: ПЕРЕЕЗД ПО СТОЛБЦАМ И СМЕНА ШИРИНЫ. Столбцы в слоте лежат по 16
;  байт подряд, поэтому new[16j+i] = old[16j+i + 16*dc + d] — ОДИН линейный сдвиг блока
;  на db = 16*dc + d, и фаза 2 не меняется ни на инструкцию. Шапка переезжает и по
;  столбцам (+1), и по ширине (+3): с этого момента стирание и vec_su_fixup описывают
;  НОВЫЙ габарит. Старые hi0/ncols нужны фазе 1 — они уходят в vsm_dc/vsm_no.
	ld	l, 1
	ld	e, (hl)	; E = hi0 СТАРОГО габарита
	ld	l, 0x97
	ld	a, (hl)
	ld	(vsm_hp), a	; плоскость A: её страница fb
	ld	l, 1
	ld	(hl), a
	sub	e
	ld	(vsm_dc), a	; dc = столбец_нов - столбец_стар (по гейту <= 0)
	add	a, a	; 16*dc
	add	a, a
	add	a, a
	add	a, a
	ld	e, a
	ld	a, (vsm_d)
	add	a, e
	ld	(vsm_db), a	; db = 16*dc + d
	ld	l, 3
	ld	a, (hl)
	ld	(vsm_no), a	; ncols СТАРОГО габарита — по нему идёт фаза 1
	ld	a, (vsb_nc)
	ld	(hl), a
	ld	a, 6
	ld	(vsm_bb), a	; и её блок фона — первый в слоте
	ld	a, (vsm_d)
	call	vsm_dir	; направление, а следом (провалом) фазы 1-3 плоскости A
	jp	vsm_wr
;  vsm_dir: направление сдвига, |d| и индексы хвоста/края. Зависит только от d, поэтому
;  считается ОДИН раз на объект, а не на каждую плоскость, и ПРОВАЛИВАЕТСЯ в фазы 1-3
;  (плоскость A всегда идёт сразу за расчётом направления — лишний call/ret ни к чему).
vsm_dir:
	or	a
	jp	m, vsm_neg
	ld	(vsm_ad), a	; --- d > 0: габарит уехал в сторону РОСТА адресов fb ---
	ld	c, a
	xor	a
	ld	(vsm_s0), a	; хвост старого габарита = |d| нижних строк (индексы 0..)
	ld	a, 16
	sub	c
	ld	(vsm_t0), a	; край нового габарита = |d| верхних строк (16-|d|..)
	jp	vsm_ph3
vsm_neg:
	cpl		; --- d < 0: габарит уехал в сторону УБЫВАНИЯ адресов ---
	inc	a
	ld	(vsm_ad), a
	ld	c, a
	ld	a, 16
	sub	c
	ld	(vsm_s0), a	; хвост сверху (индексы 16-|d|..15)
	xor	a
	ld	(vsm_t0), a	; край снизу (индексы 0..|d|-1)
;  vsm_ph3: фазы 1-3 над блоком фона ТЕКУЩЕЙ плоскости — (vsm_bb) база блока, (vsm_hp)
;  её страница fb. Зовётся по разу на плоскость. На выходе H = страница слота.
vsm_ph3:
;  ЗАДАЧА#53 ОСТАТОК: страница fb ПЕРВОГО столбца СТАРОГО габарита ЭТОЙ плоскости.
;  Считается на каждую плоскость, потому что у плоскостей B/C своя страница; у них dc = 0
;  (гейт vfm_geo: переезд по столбцам умеет только ОДНОПЛОСКОСТНЫЙ объект), поэтому
;  формула даёт им ровно их vsm_hp. Фаза 3 по этой странице отличает столбцы, которые
;  БЫЛИ в старом габарите (там |d| краевых строк), от ПОЯВИВШИХСЯ (весь столбец из fb).
	ld	a, (vsm_dc)
	ld	e, a
	ld	a, (vsm_hp)
	sub	e
	ld	(vsm_o0), a
;  (1) ХВОСТ: то, что было в СТАРОМ габарите и чего нет в новом -> фон из слота.
;  ЗАДАЧА#53 ОСТАТОК (2026-08-06): ПОКИНУТЫЕ СТОЛБЦЫ. Пока габарит умел только расти по
;  столбцам, хвост был чисто СТРОЧНЫМ (|d| строк в каждом столбце), и при |d| = 0 фаза
;  целиком пропускалась. Теперь габарит может СУЖАТЬСЯ и уезжать ВПРАВО — тогда столбец
;  старого габарита выпадает из нового ЦЕЛИКОМ, и закрыть его надо всеми 16 строками,
;  даже когда по вертикали объект не двигался. Тест тот же, что у фазы 3 (vsm_p3c),
;  только зеркальный: смещение столбца от первого столбца НОВОГО габарита; вне
;  [0, ncols_нов) — столбец покинут. Вычитание беззнаковое: столбец ЛЕВЕЕ нового даёт
;  заём и уходит за ncols_нов сам.
;  ПОЧЕМУ ЗАКРЫВАТЬ ЕГО МОЖНО: фон под ним лежит в слоте (столбец БЫЛ в старом габарите,
;  его блок ещё не сдвинут — фаза 1 идёт ДО фазы 2), а соседей по плоскости в пачке нет
;  (попарную проверку делает vsp_fastmark по ОБЪЕДИНЕНИЮ старого и нового габаритов).
;  ГЕЙТА «|d| = 0 -> фазы нет» больше нет: покинутый столбец бывает и при d = 0 (замер
;  geo_probe: 69% горизонтальных случаев). Вместо него — проверка счётчика строк на ноль
;  в самом столбце: общий столбец при d = 0 не требует ничего.
	call	vsm_ph1
vsm_p1c:
	ld	a, (vsb_nc)
	ld	b, a
	ld	a, (vsm_hp)
	ld	c, a
	ld	a, (vsm_hc)
	sub	c	; смещение столбца от первого столбца НОВОГО габарита
	cp	b
	ld	e, 0	; ПОКИНУТ: закрывается фоном ЦЕЛИКОМ, с индекса 0
	ld	d, 16
	jp	nc, vsm_p1g
	ld	a, (vsm_s0)	; ОБЩИЙ столбец: прежние |d| строк хвоста
	ld	e, a
	ld	a, (vsm_ad)
	ld	d, a
	or	a
	jp	z, vsm_p1n	; d = 0 у общего столбца -> закрывать нечего
vsm_p1g:
	ld	a, (vsm_pg)
	ld	h, a
	ld	a, (vsm_sb)
	add	a, e
	ld	l, a	; HL = слот: данные столбца + начальный индекс
	ld	a, (vsm_hc)
	ld	b, a
	ld	a, (vsm_lo)
	add	a, e
	ld	c, a	; BC = fb: страница столбца, строка lo0_old + индекс
vsm_p1r:
	ld	a, (hl)
	ld	(bc), a
	inc	l
	inc	c
	dec	d
	jp	nz, vsm_p1r
vsm_p1n:
	call	vsm_next
	jp	nz, vsm_p1c
vsm_p2e:
;  ЗАДАЧА#49: блок фона нулевой -> сдвигать нечего (сдвиг нулей = тождество), фаза 2 вон.
;  Замер: 1334 такта у героя и 1167 у мумии на КАЖДЫЙ сдвиг, и все сдвиги геймплея идут
;  по нулевому блоку. Цена проверки, когда блок не нулевой, — 17 тактов на плоскость.
	ld	a, (vsm_z)
	or	a
	jp	z, vsm_p2g
;  ЗАДАЧА#53 ОСТАТОК: «нулевой блок = сдвигать нечего» ВЕРНО ТОЛЬКО ПРИ НЕИЗМЕННОЙ ШИРИНЕ.
;  Стоял 2026-08-06 на герое (dc=-1, dn=+1, блок нулевой): блок СТАЛ ШИРЕ, и его хвост за
;  пределами старого габарита никогда не занулялся — там лежал мусор слота, а фаза 3 его
;  не трогает (столбец-то ОБЩИЙ, у него дочитываются лишь |d| краевых строк). Следующий
;  кадр поднимал этот мусор как «фон» — 26 бит в слоте и каскад по кадрам.
;  Сдвиг нулей и есть зануление хвоста, поэтому при выросшей ширине фаза 2 обязательна.
;  ТОЧНОЕ УСЛОВИЕ — «ШИРИНА НЕ ВЫРОСЛА», А НЕ «НЕ МЕНЯЛАСЬ» (2026-08-06, задача #53).
;  Опасен ровно хвост блока за старым габаритом, [16*ncols_ст, 16*ncols_нов): он в старом
;  блоке не лежал, поэтому нулевым не доказан. Когда ширина УПАЛА (а с покинутыми
;  столбцами это половина новых случаев), такого хвоста нет вовсе, и сдвиг нулей — снова
;  тождество: каждый байт нового блока либо общий (ноль и есть фон), либо его целиком
;  перепишет фаза 3 (появившийся столбец / краевые строки). Байт кода тот же — `jp z`
;  стал `jp nc`, — а сдвиг стоит 1334 такта у героя и 1167 у мумии.
	ld	hl, vsb_nc
	ld	a, (vsm_no)
	cp	(hl)
	jp	nc, vsm_p3
vsm_p2g:
;  (2) СДВИГ ФОНА В СЛОТЕ на d байт: ОДНА линейная копия 16*ncols байт. d > 0 — по
;      возрастанию (пишем ПОЗАДИ чтения), d < 0 — по убыванию (пишем ВПЕРЕДИ).
;      Развёрнуто по 8 байт: это самая длинная часть сдвинутого пути, счётчик на байт
;      стоил бы 15 тактов. Хвост копии затягивает в столбец c соседние байты столбца c+1
;      (а в последний — мусор за блоком) — это ровно те |d| байт, которые тут же
;      перезапишет добор края, поэтому читать их не грех.
	ld	a, (vsm_pg)
	ld	h, a
	ld	d, a
	ld	a, (vsm_db)	; ЗАДАЧА#53 ОСТАТОК: db = 16*dc + d, а не одно только d
	or	a
	jp	m, vsm_p2d
	ld	c, a
	ld	a, (vsm_bb)	; блок фона ЭТОЙ плоскости
	ld	l, a
	add	a, c
	ld	e, a	; src = блок + d
;  ЗАДАЧА#53 (2026-08-07): АНРОЛЛ 8x -> 4x, обе стороны. Фаза 2 работает ТОЛЬКО когда
;  блок фона НЕ нулевой (замер su_empty_census: у геймплейных объектов он нулевой в
;  98-100% выводов) либо когда ширина габарита ВЫРОСЛА, поэтому она не горячая: замер
;  burst_cost.js — 329 тактов на пачку на обе стороны. Виток при 4x стоит 15 тактов на
;  4 байта вместо 15 на 8, то есть +1.9 такта на байт = +26 тактов на пачку. Отдано
;  30 байт pre-align, и они идут в финансирование быстрого прохода фаз 1/3 (там
;  выигрыш на два порядка больше — 2000 тактов на пачку).
	ld	a, (vsb_nc)
	add	a, a
	add	a, a
	ld	b, a	; B = 4*ncols витков по 4 байта
vsm_p2u:
	ld	a, (de)
	ld	(hl), a
	inc	l
	inc	e
	ld	a, (de)
	ld	(hl), a
	inc	l
	inc	e
	ld	a, (de)
	ld	(hl), a
	inc	l
	inc	e
	ld	a, (de)
	ld	(hl), a
	inc	l
	inc	e
	dec	b
	jp	nz, vsm_p2u
	jp	vsm_p3
vsm_p2d:
	ld	a, (vsb_nc)
	add	a, a
	add	a, a
	ld	b, a	; B = 4*ncols витков по 4 байта (анролл 8x -> 4x, см. vsm_p2u)
	add	a, a
	add	a, a	; A = 16*ncols
	ld	c, a
	ld	a, (vsm_bb)	; блок фона ЭТОЙ плоскости
	add	a, c
	dec	a
	ld	l, a	; dst = последний байт занятой части блока
	ld	c, a
	ld	a, (vsm_db)
	add	a, c	; src = dst + db (db < 0)
	ld	e, a
vsm_p2dl:
	ld	a, (de)
	ld	(hl), a
	dec	l
	dec	e
	ld	a, (de)
	ld	(hl), a
	dec	l
	dec	e
	ld	a, (de)
	ld	(hl), a
	dec	l
	dec	e
	ld	a, (de)
	ld	(hl), a
	dec	l
	dec	e
	dec	b
	jp	nz, vsm_p2dl
vsm_p3:
;  (3) КРАЙ: |d| строк нового габарита, которых не было в старом. Там ЧИСТЫЙ фон —
;      читаем его прямо из fb (эти строки лежат ВНЕ старого габарита объекта, а соседей
;      по плоскости в пачке нет: попарную проверку делает vsp_fastmark).
;  ЗАДАЧА#49: ЭТО ЕДИНСТВЕННОЕ МЕСТО, ГДЕ В НУЛЕВОЙ БЛОК МОЖЕТ ПРИЙТИ НЕНОЛЬ (объект
;  наехал на кирпич). Копим OR прочитанного в E — регистр освободился тем, что vsm_t0
;  теперь читается дважды вместо спилла через E (те же байты, +13 тактов на столбец).
;  Ненулевой край => ZFLAG слота снят И vsm_z снят: запись ЭТОГО кадра обязана идти
;  штатным ядром, фон в блоке уже не нули.
	ld	e, 0	; аккумулятор «край не нулевой»
	call	vsm_ph
;  ЗАДАЧА#53 ОСТАТОК: СТОЛБЕЦ БЫЛ В СТАРОМ ГАБАРИТЕ ИЛИ ПОЯВИЛСЯ? Смещение текущего
;  столбца от первого столбца СТАРОГО габарита: если оно вне [0, ncols_стар), фона под
;  этим столбцом в слоте нет вовсе — берём ВЕСЬ столбец из fb (там чистый фон: столбец
;  лежит за пределами старого габарита объекта, а соседей по плоскости в пачке нет).
;  Иначе — прежние |d| краевых строк, и при d = 0 столбцу не нужно ничего.
;  Вычитание беззнаковое: столбец ЛЕВЕЕ старого даёт заём и уходит за ncols_стар сам.
vsm_p3c:
	ld	a, (vsm_o0)
	ld	c, a
	ld	a, (vsm_hc)
	sub	c
	ld	c, a
	ld	a, (vsm_no)
	cp	c
	jp	c, vsm_p3f
	jp	z, vsm_p3f
	ld	a, (vsm_t0)	; общий столбец: |d| краевых строк, как и раньше
	ld	(vsm_tc), a
	ld	a, (vsm_ad)
	jp	vsm_p3g
vsm_p3f:
	xor	a	; ПОЯВИВШИЙСЯ столбец: все 16 строк из fb
	ld	(vsm_tc), a
	ld	a, 16
vsm_p3g:
	ld	(vsm_ac), a
	or	a
	jp	z, vsm_p3n	; d = 0 и столбец общий -> дочитывать нечего
	ld	a, (vsm_pg)
	ld	h, a
	ld	a, (vsm_sb)
	ld	l, a
	ld	a, (vsm_tc)
	add	a, l
	ld	l, a
	ld	a, (vsm_hc)
	ld	b, a
	ld	a, (vsb_lo)	; НОВЫЙ lo0
	ld	c, a
	ld	a, (vsm_tc)
	add	a, c
	ld	c, a
	ld	a, (vsm_ac)
	ld	d, a
vsm_p3r:
	ld	a, (bc)
	ld	(hl), a
	or	e
	ld	e, a
	inc	l
	inc	c
	dec	d
	jp	nz, vsm_p3r
vsm_p3n:
	call	vsm_next
	jp	nz, vsm_p3c
	ld	a, (vsm_pg)	; фон блока описывает НОВЫЙ габарит -> дальше обычная запись
	ld	h, a
	ld	a, e	; край принёс ненулевые байты?
	or	a
	ret	z
	xor	a	; да -> блок больше не нулевой
	ld	l, 0x0D1
	ld	(hl), a
	ld	(vsm_z), a
	ret
;  vsm_ph: начало прохода по столбцам ТЕКУЩЕЙ плоскости — база её блока фона, её страница
;  fb, счётчик столбцов.
;  ЗАДАЧА#53 ОСТАТОК: у ФАЗЫ 1 свой вход — она закрывает СТАРЫЙ габарит, а он мог быть
;  и левее, и уже нового (гейт вложенности разрешает только рост). Отсюда своя стартовая
;  страница fb (vsm_o0) и свой счётчик столбцов (vsm_no). Хвост общий с vsm_ph.
vsm_ph1:
	ld	a, (vsm_o0)
	ld	(vsm_hc), a
	ld	a, (vsm_no)
	jp	vsm_phc
vsm_ph:
	ld	a, (vsm_hp)
	ld	(vsm_hc), a
	ld	a, (vsb_nc)
vsm_phc:
	ld	(vsm_cc), a
	ld	a, (vsm_bb)
	ld	(vsm_sb), a
	ret
;  vsm_next: следующий столбец; Z = столбцы кончились (ld (nn),a флаги не трогает).
vsm_next:
	ld	a, (vsm_sb)
	add	a, 16
	ld	(vsm_sb), a
	ld	a, (vsm_hc)
	inc	a
	ld	(vsm_hc), a
	ld	a, (vsm_cc)
	dec	a
	ld	(vsm_cc), a
	ret
;  vsb_andn: то же, но спрайт ГАСИТ плоскость (p &= ~s) — «рисунок кирпичей» створки
;  ворот не должен складываться с фоном.
;  ЗАДАЧА#39: раньше эта петля шла только по 4 статичным створкам и была компактной. Теперь
;  ею гасит фон непрозрачный герой (две плоскости в 5% выводов), поэтому строка развёрнута
;  вчетверо: 39 тактов на байт вместо 50, ~110 тактов на кадр геймплея за 26 байт кода.
;  [2026-09-27 этап 3] внутренний `ld b,4 / vsa_row` развёрнут в 16 байт подряд:
;  минус 4×(dec+jp) и ld b — ~67 т на столбец плоскости; тело то же (картинка =).
vsb_andn:
vsb_andn1:
	ld	a, (vsb_lo)
	ld	l, a
	ld	h, c
	push	bc
	; --- 16 строк столбца, без счётчика ---
vsa_row:	; метка для pack_prof / .sym
	ld	a, (de)
	inc	e
	cpl
	and	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	cpl
	and	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	cpl
	and	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	cpl
	and	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	cpl
	and	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	cpl
	and	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	cpl
	and	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	cpl
	and	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	cpl
	and	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	cpl
	and	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	cpl
	and	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	cpl
	and	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	cpl
	and	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	cpl
	and	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	cpl
	and	(hl)
	ld	(hl), a
	inc	l
	ld	a, (de)
	inc	e
	cpl
	and	(hl)
	ld	(hl), a
	inc	l
	pop	bc
	inc	c
	dec	b
	jp	nz, vsb_andn1
	ret

